/**
 * Anatomy Editor - Main editor for modular creature manipulation
 * 
 * This is a complete redesign based on understanding the actual system:
 * - Template-driven creature creation with FORCE variations
 * - Chain hierarchy manipulation with parent-child relationships  
 * - Anatomical constraint editing with biological limits
 * - Attachment point system for intuitive chain reattachment
 * - IK-aware editing that preserves structural integrity
 */

class AnatomyEditor {
    constructor(builder) {
        this.builder = builder;
        this.active = false;

        // UI Components
        this.templateGallery = null;
        this.chainHierarchy = null;
        this.chainProperties = null;
        this.zoomViewer = null;
        this.attachmentSystem = null;

        // State Management
        this.selectedChain = null;
        this.selectedBone = null;
        this.selectedJoint = null;
        this.draggedChain = null;
        this.showAttachmentPoints = false;

        // Visual State
        this.zoomViewOpen = false;
        this.attachmentMode = false;

        // Performance & UX
        this.updateThrottle = 16; // 60fps
        this.lastUpdate = 0;

        console.log('🦴 AnatomyEditor initialized - Template-driven creature editing');
    }

    /**
     * Initialize the anatomy editor UI
     */
    initialize() {
        this.createMainLayout();
        this.initializeComponents();
        this.setupEventHandlers();

        console.log('✅ AnatomyEditor UI ready');
    }

    /**
     * Create main editor layout
     */
    createMainLayout() {
        // Main editor container
        this.container = createDiv();
        this.container.id('anatomy-editor');
        this.container.position(0, 0);
        this.container.style(`
            width: 100vw;
            height: 100vh;
            position: fixed;
            z-index: 1000;
            background: rgba(0,0,0,0.1);
            display: none;
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
        `);

        // Left sidebar for controls
        this.sidebar = createDiv();
        this.sidebar.parent(this.container);
        this.sidebar.style(`
            width: 300px;
            height: 100vh;
            background: #f8f9fa;
            border-right: 2px solid #dee2e6;
            overflow-y: auto;
            box-shadow: 2px 0 10px rgba(0,0,0,0.1);
        `);

        // Main canvas area (existing p5 canvas will show here)
        this.canvasArea = createDiv();
        this.canvasArea.parent(this.container);
        this.canvasArea.style(`
            position: absolute;
            left: 300px;
            top: 0;
            width: calc(100vw - 300px);
            height: 100vh;
            background: #ffffff;
        `);

        // Overlay for attachment point visualization
        this.attachmentOverlay = createDiv();
        this.attachmentOverlay.parent(this.canvasArea);
        this.attachmentOverlay.style(`
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            pointer-events: none;
            z-index: 10;
        `);
    }

    /**
     * Initialize all editor components
     */
    initializeComponents() {
        // Template Gallery - creature selection with FORCE variations
        this.templateGallery = new TemplateGallery(this.builder, this);
        this.templateGallery.initialize(this.sidebar);

        // Chain Hierarchy Tree - visual chain relationships
        this.chainHierarchy = new ChainHierarchy(this.builder, this);
        this.chainHierarchy.initialize(this.sidebar);

        // Chain Properties Panel - selected chain details
        this.chainProperties = new ChainProperties(this.builder, this);
        this.chainProperties.initialize(this.sidebar);

        // Attachment Point System - drag-drop reattachment
        this.attachmentSystem = new AttachmentPointSystem(this.builder, this);
        this.attachmentSystem.initialize(this.attachmentOverlay);

        // Zoom Viewer - detailed chain editing (modal)
        this.zoomViewer = new ZoomChainViewer(this.builder, this);
        this.zoomViewer.initialize(this.container);

        console.log('🏗️ All editor components initialized');
    }

    /**
     * Setup event handlers
     */
    setupEventHandlers() {
        // Canvas click handling for chain selection
        this.canvasArea.mousePressed(() => {
            if (!this.active) return;
            this.handleCanvasClick(mouseX, mouseY);
        });

        // Key shortcuts
        document.addEventListener('keydown', (e) => {
            if (!this.active) return;
            this.handleKeyPress(e);
        });
    }

    /**
     * Show the anatomy editor
     */
    show() {
        this.active = true;
        this.container.style('display: block');

        // Pause creature locomotion for editing
        this.builder.editorActive = true;
        if (this.builder.activeLocomotion) {
            this.savedLocomotion = this.builder.activeLocomotion;
            this.builder.activeLocomotion = null;
        }

        // Switch to skeleton render mode
        this.savedRenderMode = this.builder.renderMode;
        this.builder.renderMode = 'skeleton';

        // Update all components
        this.updateAll();

        console.log('👁️ AnatomyEditor activated');
    }

    /**
     * Hide the anatomy editor
     */
    hide() {
        this.active = false;
        this.container.style('display: none');

        // Restore creature state
        this.builder.editorActive = false;
        if (this.savedLocomotion) {
            this.builder.activeLocomotion = this.savedLocomotion;
        }
        if (this.savedRenderMode) {
            this.builder.renderMode = this.savedRenderMode;
        }

        // Clear selections
        this.clearSelections();

        console.log('👁️ AnatomyEditor deactivated');
    }

    /**
     * Main update loop
     */
    update() {
        if (!this.active) return;

        // Throttle updates for performance
        const now = performance.now();
        if (now - this.lastUpdate < this.updateThrottle) return;

        this.updateAll();
        this.lastUpdate = now;
    }

    /**
     * Update all components
     */
    updateAll() {
        if (this.templateGallery) this.templateGallery.update();
        if (this.chainHierarchy) this.chainHierarchy.update();
        if (this.chainProperties) this.chainProperties.update();
        if (this.attachmentSystem) this.attachmentSystem.update();
        if (this.zoomViewer && this.zoomViewOpen) this.zoomViewer.update();
    }

    /**
     * Handle canvas clicks for chain selection
     */
    handleCanvasClick(x, y) {
        // Adjust coordinates for canvas area offset
        const canvasX = x - 300;
        const canvasY = y;

        // Find clicked chain
        const clickedChain = this.findChainAtPoint(canvasX, canvasY);

        if (clickedChain !== null) {
            this.selectChain(clickedChain);
        } else {
            this.clearSelections();
        }
    }

    /**
     * Find chain at given point
     */
    findChainAtPoint(x, y) {
        const threshold = 15;

        for (let i = 0; i < this.builder.chains.length; i++) {
            const chain = this.builder.chains[i];

            for (let j = 0; j < chain.numBones; j++) {
                const bone = chain.bones[j];
                const dist = this.pointToLineDistance(
                    x, y,
                    bone.start.x, bone.start.y,
                    bone.end.x, bone.end.y
                );

                if (dist < threshold) {
                    return i;
                }
            }
        }

        return null;
    }

    /**
     * Point to line distance calculation
     */
    pointToLineDistance(px, py, x1, y1, x2, y2) {
        const A = px - x1;
        const B = py - y1;
        const C = x2 - x1;
        const D = y2 - y1;

        const dot = A * C + B * D;
        const lenSq = C * C + D * D;

        if (lenSq === 0) return Math.sqrt(A * A + B * B);

        let param = dot / lenSq;
        param = Math.max(0, Math.min(1, param));

        const xx = x1 + param * C;
        const yy = y1 + param * D;

        return Math.sqrt((px - xx) * (px - xx) + (py - yy) * (py - yy));
    }

    /**
     * Select a chain
     */
    selectChain(chainIndex) {
        this.selectedChain = chainIndex;
        this.selectedBone = null;
        this.selectedJoint = null;

        // Update components
        this.chainHierarchy.setSelectedChain(chainIndex);
        this.chainProperties.setSelectedChain(chainIndex);

        // Show attachment points if in attachment mode
        if (this.attachmentMode) {
            this.attachmentSystem.showAttachmentPoints(chainIndex);
        }

        console.log(`🎯 Selected chain ${chainIndex}: ${this.builder.chainConfigs[chainIndex]?.role}`);
    }

    /**
     * Clear all selections
     */
    clearSelections() {
        this.selectedChain = null;
        this.selectedBone = null;
        this.selectedJoint = null;

        this.chainHierarchy.clearSelection();
        this.chainProperties.clearSelection();
        this.attachmentSystem.hideAttachmentPoints();
    }

    /**
     * Open zoom viewer for selected chain
     */
    openZoomViewer() {
        if (this.selectedChain === null) return;

        this.zoomViewOpen = true;
        this.zoomViewer.show(this.selectedChain);
    }

    /**
     * Close zoom viewer
     */
    closeZoomViewer() {
        this.zoomViewOpen = false;
        this.zoomViewer.hide();
    }

    /**
     * Enter attachment mode for chain reattachment
     */
    enterAttachmentMode() {
        if (this.selectedChain === null) return;

        this.attachmentMode = true;
        this.attachmentSystem.enterAttachmentMode(this.selectedChain);

        console.log('🔗 Entered attachment mode');
    }

    /**
     * Exit attachment mode
     */
    exitAttachmentMode() {
        this.attachmentMode = false;
        this.attachmentSystem.exitAttachmentMode();

        console.log('🔗 Exited attachment mode');
    }

    /**
     * Handle keyboard shortcuts
     */
    handleKeyPress(event) {
        switch (event.key.toLowerCase()) {
            case 'escape':
                if (this.zoomViewOpen) {
                    this.closeZoomViewer();
                } else if (this.attachmentMode) {
                    this.exitAttachmentMode();
                } else {
                    this.hide();
                }
                break;

            case 'z':
                if (this.selectedChain !== null) {
                    this.openZoomViewer();
                }
                break;

            case 'a':
                if (this.selectedChain !== null) {
                    this.toggleAttachmentMode();
                }
                break;

            case 'i':
                // Toggle IK test mode (existing functionality)
                this.builder.debugManager?.handleKeyPress('i');
                break;
        }
    }

    /**
     * Toggle attachment mode
     */
    toggleAttachmentMode() {
        if (this.attachmentMode) {
            this.exitAttachmentMode();
        } else {
            this.enterAttachmentMode();
        }
    }

    /**
     * Load a creature template
     */
    loadTemplate(templateName, forceVariations = {}) {
        console.log(`🎨 Loading template: ${templateName}`, forceVariations);

        // Apply FORCE variations to builder config
        if (forceVariations.anatomicalScale) {
            this.builder.anatomicalScale = forceVariations.anatomicalScale;
        }
        if (forceVariations.rhythmIntensity) {
            this.builder.rhythmIntensity = forceVariations.rhythmIntensity;
        }
        if (forceVariations.curveVariation) {
            this.builder.curveVariation = forceVariations.curveVariation;
        }

        // Load the template
        switch (templateName) {
            case 'fish':
                this.builder.buildFish();
                break;
            case 'crane':
                this.builder.buildBipedalCrane();
                break;
            case 'horse':
                this.builder.buildHorse();
                break;
            case 'lizard':
                this.builder.buildLizard();
                break;
            default:
                console.warn(`Unknown template: ${templateName}`);
                return;
        }

        // Clear selections and update UI
        this.clearSelections();
        this.updateAll();

        console.log(`✅ Template ${templateName} loaded successfully`);
    }

    /**
     * Draw editor overlays
     */
    draw() {
        if (!this.active) return;

        // Draw selection highlight
        this.drawSelectionHighlight();

        // Draw attachment points if in attachment mode
        if (this.attachmentMode && this.attachmentSystem) {
            this.attachmentSystem.draw();
        }
    }

    /**
     * Draw selection highlight
     */
    drawSelectionHighlight() {
        if (this.selectedChain === null) return;

        const chain = this.builder.chains[this.selectedChain];
        if (!chain) return;

        push();

        // Highlight selected chain
        stroke(255, 215, 0); // Gold
        strokeWeight(6);
        noFill();

        for (let i = 0; i < chain.numBones; i++) {
            const bone = chain.bones[i];
            line(bone.start.x, bone.start.y, bone.end.x, bone.end.y);
        }

        // Draw chain info
        if (chain.numBones > 0) {
            const firstBone = chain.bones[0];
            const config = this.builder.chainConfigs[this.selectedChain];

            fill(255, 215, 0);
            noStroke();
            textAlign(CENTER);
            textSize(12);
            textStyle(BOLD);
            text(config?.role || 'Unknown', firstBone.start.x, firstBone.start.y - 15);
        }

        pop();
    }

    /**
     * Cleanup editor resources
     */
    cleanup() {
        if (this.container) {
            this.container.remove();
        }

        // Cleanup components
        if (this.templateGallery) this.templateGallery.cleanup();
        if (this.chainHierarchy) this.chainHierarchy.cleanup();
        if (this.chainProperties) this.chainProperties.cleanup();
        if (this.zoomViewer) this.zoomViewer.cleanup();
        if (this.attachmentSystem) this.attachmentSystem.cleanup();

        console.log('🧹 AnatomyEditor cleaned up');
    }
}

// Export for global access
window.AnatomyEditor = AnatomyEditor;

class BoneManipulator {
    constructor(builder) {
        this.builder = builder;
        this.lastUpdate = 0;
        this.selectedBone = null;

        // Performance settings
        this.updateThrottle = 33; // 30fps target
        this.selectionThreshold = 15; // pixels

        console.log('BoneManipulator initialized');
    }

    // Individual bone selection using point-to-line distance
    selectBone(mouseX, mouseY) {
        const startTime = performance.now();

        for (let chainIndex = 0; chainIndex < this.builder.chains.length; chainIndex++) {
            const chain = this.builder.chains[chainIndex];

            for (let boneIndex = 0; boneIndex < chain.numBones; boneIndex++) {
                const bone = chain.bones[boneIndex];
                const start = bone.start;
                const end = bone.end;

                // Use point-to-line distance for accurate selection
                const distance = this.pointToLineDistance(
                    mouseX, mouseY,
                    start.x, start.y,
                    end.x, end.y
                );

                if (distance < this.selectionThreshold) {
                    const result = {
                        chainIndex: chainIndex,
                        boneIndex: boneIndex,
                        bone: bone,
                        distance: distance
                    };

                    this.selectedBone = result;

                    // Performance monitoring
                    const selectionTime = performance.now() - startTime;
                    if (selectionTime > 50) {
                        console.warn(`Bone selection took ${selectionTime.toFixed(1)}ms`);
                    }

                    console.log(`Selected bone ${boneIndex} in chain ${chainIndex}`);
                    return result;
                }
            }
        }

        this.selectedBone = null;
        return null;
    }

    // Point-to-line distance calculation (same as EditorMode but localized)
    pointToLineDistance(px, py, x1, y1, x2, y2) {
        const A = px - x1;
        const B = py - y1;
        const C = x2 - x1;
        const D = y2 - y1;

        const dot = A * C + B * D;
        const lenSq = C * C + D * D;

        if (lenSq === 0) return Math.sqrt(A * A + B * B);

        let param = dot / lenSq;
        param = Math.max(0, Math.min(1, param)); // Constrain to line segment

        const xx = x1 + param * C;
        const yy = y1 + param * D;

        return Math.sqrt((px - xx) * (px - xx) + (py - yy) * (py - yy));
    }

    // Draw bone highlighting with distinct visual from chain highlighting
    drawBoneHighlight(selectedBone) {
        if (!selectedBone || !selectedBone.bone) return;

        const bone = selectedBone.bone;
        const start = bone.start;
        const end = bone.end;

        push();
        // Distinct blue highlight for individual bones (vs yellow for chains)
        stroke(100, 150, 255);
        strokeWeight(6);
        noFill();

        // Draw highlighted bone
        line(start.x, start.y, end.x, end.y);

        // Draw bone endpoints as circles
        fill(100, 150, 255, 150);
        noStroke();
        circle(start.x, start.y, 8);
        circle(end.x, end.y, 8);

        // Draw bone index label
        fill(255);
        stroke(0);
        strokeWeight(1);
        textAlign(CENTER);
        textSize(12);
        const midX = (start.x + end.x) / 2;
        const midY = (start.y + end.y) / 2;
        text(`B${selectedBone.boneIndex}`, midX, midY - 10);

        pop();
    }

    // Handle bone dragging for real-time manipulation
    handleBoneDrag(selectedBone, mouseX, mouseY, manipulationType) {
        if (!selectedBone || !selectedBone.bone) return false;

        // Throttle updates for performance
        const now = performance.now();
        if (now - this.lastUpdate < this.updateThrottle) return false;

        const bone = selectedBone.bone;
        const chain = this.builder.chains[selectedBone.chainIndex];

        try {
            switch (manipulationType) {
                case 'move':
                    return this.handleBoneMove(selectedBone, mouseX, mouseY);

                case 'rotate':
                    return this.handleBoneRotate(selectedBone, mouseX, mouseY);

                case 'scale':
                    return this.handleBoneScale(selectedBone, mouseX, mouseY);

                case 'select':
                default:
                    // Default to end-effector manipulation for intuitive editing
                    return this.handleEndEffectorMove(selectedBone, mouseX, mouseY);
            }
        } catch (error) {
            console.error('Bone manipulation error:', error);
            return false;
        } finally {
            this.lastUpdate = now;
        }
    }

    // Move bone endpoint (most intuitive manipulation)
    handleEndEffectorMove(selectedBone, mouseX, mouseY) {
        const bone = selectedBone.bone;
        const newEndPos = new FIK.V2(mouseX, mouseY);

        // Calculate new length and validate
        const start = bone.start;
        const newLength = start.distanceTo(newEndPos);

        if (!this.validateBoneManipulation(selectedBone, newLength, 0)) {
            return false;
        }

        // Update bone endpoint
        bone.setEndLocation(newEndPos);

        // Solve chain if this affects other bones
        const chain = this.builder.chains[selectedBone.chainIndex];
        if (selectedBone.boneIndex === chain.numBones - 1) {
            // This is the end effector - solve IK for the chain
            this.solveChainWithOptimization(chain, newEndPos);
        }

        console.log(`Moved bone ${selectedBone.boneIndex} endpoint to (${mouseX.toFixed(1)}, ${mouseY.toFixed(1)})`);
        return true;
    }

    // Rotate bone around its start point
    handleBoneRotate(selectedBone, mouseX, mouseY) {
        const bone = selectedBone.bone;
        const start = bone.start;
        const length = bone.getLength();

        // Calculate new angle from start point to mouse
        const dx = mouseX - start.x;
        const dy = mouseY - start.y;
        const newAngle = Math.atan2(dy, dx);
        const newAngleDeg = newAngle * 180 / Math.PI;

        if (!this.validateBoneManipulation(selectedBone, length, newAngleDeg)) {
            return false;
        }

        // Calculate new end position
        const newEndX = start.x + Math.cos(newAngle) * length;
        const newEndY = start.y + Math.sin(newAngle) * length;

        bone.setEndLocation(new FIK.V2(newEndX, newEndY));

        console.log(`Rotated bone ${selectedBone.boneIndex} to ${newAngleDeg.toFixed(1)}°`);
        return true;
    }

    // Scale bone length
    handleBoneScale(selectedBone, mouseX, mouseY) {
        const bone = selectedBone.bone;
        const start = bone.start;
        const currentEnd = bone.end;

        // Calculate new length based on mouse distance from start
        const newLength = start.distanceTo(new FIK.V2(mouseX, mouseY));

        if (!this.validateBoneManipulation(selectedBone, newLength, 0)) {
            return false;
        }

        // Maintain current direction but change length
        const direction = currentEnd.minus(start).normalised();
        const newEndPos = start.plus(direction.multiplyBy(newLength));

        bone.setEndLocation(newEndPos);

        console.log(`Scaled bone ${selectedBone.boneIndex} to length ${newLength.toFixed(1)}px`);
        return true;
    }

    // Move entire bone (both start and end)
    handleBoneMove(selectedBone, mouseX, mouseY) {
        const bone = selectedBone.bone;
        const start = bone.start;
        const end = bone.end;

        // Calculate offset from current position to mouse
        const midX = (start.x + end.x) / 2;
        const midY = (start.y + end.y) / 2;
        const offsetX = mouseX - midX;
        const offsetY = mouseY - midY;

        // Apply offset to both start and end points
        const newStart = new FIK.V2(start.x + offsetX, start.y + offsetY);
        const newEnd = new FIK.V2(end.x + offsetX, end.y + offsetY);

        // Note: Moving individual bones requires careful chain management
        // For now, only move the end point to maintain chain integrity
        bone.setEndLocation(newEnd);

        console.log(`Moved bone ${selectedBone.boneIndex} by offset (${offsetX.toFixed(1)}, ${offsetY.toFixed(1)})`);
        return true;
    }

    // Optimized IK solving for real-time manipulation
    solveChainWithOptimization(chain, target) {
        // Apply performance optimizations for real-time editing
        const originalAttempts = chain.maxIterationAttempts || 15;
        const originalThreshold = chain.solveDistanceThreshold || 1.0;
        const originalMinChange = chain.minIterationChange || 0.01;

        // Temporarily reduce precision for speed
        if (chain.setMaxIterationAttempts) {
            chain.setMaxIterationAttempts(6);
        }
        if (chain.setSolveDistanceThreshold) {
            chain.setSolveDistanceThreshold(2.5);
        }
        if (chain.setMinIterationChange) {
            chain.setMinIterationChange(0.08);
        }

        try {
            chain.solveForTarget(target);
        } catch (error) {
            console.warn('IK solve failed during bone manipulation:', error);
        }

        // Restore original settings
        if (chain.setMaxIterationAttempts) {
            chain.setMaxIterationAttempts(originalAttempts);
        }
        if (chain.setSolveDistanceThreshold) {
            chain.setSolveDistanceThreshold(originalThreshold);
        }
        if (chain.setMinIterationChange) {
            chain.setMinIterationChange(originalMinChange);
        }
    }

    // Add/remove bones from chains
    addBoneToChain(chainIndex, insertIndex = -1) {
        if (chainIndex >= this.builder.chains.length) return false;

        const chain = this.builder.chains[chainIndex];
        const config = this.builder.chainConfigs[chainIndex];

        try {
            if (insertIndex === -1 || insertIndex >= chain.numBones) {
                // Add to end of chain
                const lastBone = chain.bones[chain.numBones - 1];
                const direction = lastBone.getDirectionUV();
                const newLength = lastBone.getLength();

                chain.addConsecutiveBone(direction, newLength, 45, 45);
                console.log(`Added bone to end of chain ${chainIndex}`);
            } else {
                // Insert at specific position - requires chain reconstruction
                console.warn('Bone insertion at specific index not yet implemented');
                return false;
            }

            return true;
        } catch (error) {
            console.error('Error adding bone to chain:', error);
            return false;
        }
    }

    removeBoneFromChain(chainIndex, boneIndex) {
        if (chainIndex >= this.builder.chains.length) return false;

        const chain = this.builder.chains[chainIndex];

        if (chain.numBones <= 1) {
            console.warn('Cannot remove last bone from chain');
            return false;
        }

        if (boneIndex >= chain.numBones) {
            console.warn('Invalid bone index for removal');
            return false;
        }

        try {
            // FIK.js doesn't have direct bone removal - would need chain reconstruction
            // For now, log the intention
            console.warn('Bone removal requires chain reconstruction - not yet implemented');
            return false;
        } catch (error) {
            console.error('Error removing bone from chain:', error);
            return false;
        }
    }

    // Get bone properties for UI display
    getBoneProperties(selectedBone) {
        if (!selectedBone || !selectedBone.bone) return null;

        const bone = selectedBone.bone;
        const start = bone.start;
        const end = bone.end;

        // Calculate bone angle
        const dx = end.x - start.x;
        const dy = end.y - start.y;
        const angle = Math.atan2(dy, dx) * 180 / Math.PI;

        return {
            length: bone.getLength().toFixed(1),
            angle: angle.toFixed(1),
            startX: start.x.toFixed(1),
            startY: start.y.toFixed(1),
            endX: end.x.toFixed(1),
            endY: end.y.toFixed(1),
            constraints: {
                clockwise: bone.joint ? bone.joint.clockwiseConstraintDegs || 0 : 0,
                anticlockwise: bone.joint ? bone.joint.anticlockwiseConstraintDegs || 0 : 0
            }
        };
    }

    // Validate bone manipulation (prevent invalid states)
    validateBoneManipulation(selectedBone, newLength, newAngle) {
        if (!selectedBone || !selectedBone.bone) return false;

        // Check minimum length constraint
        if (newLength < 5) {
            console.warn('Bone length too small (minimum: 5px)');
            return false;
        }

        // Check maximum length constraint  
        if (newLength > 300) {
            console.warn('Bone length too large (maximum: 300px)');
            return false;
        }

        // Check angle constraints if joint exists
        const bone = selectedBone.bone;
        if (bone.joint) {
            const clockwiseLimit = bone.joint.clockwiseConstraintDegs || 180;
            const anticlockwiseLimit = bone.joint.anticlockwiseConstraintDegs || 180;

            if (newAngle > clockwiseLimit || newAngle < -anticlockwiseLimit) {
                console.warn(`Angle ${newAngle.toFixed(1)}° violates joint constraints`);
                return false;
            }
        }

        return true;
    }

    // Clear selection
    clearSelection() {
        this.selectedBone = null;
    }

    // Check if bone manipulator is ready
    isReady() {
        return this.builder && this.builder.chains && this.builder.chains.length > 0;
    }
}

/**
 * Joint Constraint Editor for Skeleton Editing (PRP2 Task 6)
 * 
 * Provides visual constraint arc rendering, real-time constraint editing,
 * and anatomical validation for joint constraints in skeleton editing.
 */

class ConstraintEditor {
    constructor(builder, editorMode) {
        this.builder = builder;
        this.editor = editorMode;

        // Visual constraint settings
        this.constraintVisualization = {
            arcRadius: 25,
            arcStrokeWeight: 2,
            validColor: [100, 255, 100],      // Green for valid
            warningColor: [255, 200, 100],    // Orange for warning
            violationColor: [255, 100, 100],  // Red for violation
            constraintArcColor: [150, 150, 255, 150] // Blue for constraint arcs
        };

        // Constraint validation thresholds
        this.validationThresholds = {
            anatomicalWarning: 0.8,  // Warn when approaching anatomical limits
            anatomicalMax: 1.0       // Maximum anatomical constraint factor
        };

        // Active constraint editing state
        this.activeConstraintEdit = null;
        this.constraintDragState = null;

        this.initializeConstraintEditor();
        console.log('Joint Constraint Editor initialized with anatomical validation');
    }

    initializeConstraintEditor() {
        // Initialize integration with existing constraint system
        if (this.builder.constraintSystem) {
            console.log('✅ Integrated with existing ConstraintSystem');
        } else {
            console.warn('⚠️ ConstraintSystem not available - using basic constraints');
        }

        // Initialize integration with anatomical data
        if (this.builder.anatomicalData || (this.builder.systems && this.builder.systems.anatomicalData)) {
            console.log('✅ Integrated with AnatomicalData system');
        } else {
            console.warn('⚠️ AnatomicalData not available - using generic constraints');
        }
    }

    // Draw constraint visualization for selected joint
    drawJointConstraints(selectedBone) {
        if (!selectedBone || !selectedBone.bone || !selectedBone.bone.joint) {
            return;
        }

        const bone = selectedBone.bone;
        const joint = bone.joint;
        const start = bone.start;

        // Draw constraint arcs
        this.drawConstraintArcs(start, joint, selectedBone);

        // Draw current bone angle indicator
        this.drawCurrentAngleIndicator(selectedBone);

        // Draw constraint violation warnings if any
        this.drawConstraintViolations(selectedBone);
    }

    // Draw constraint arcs showing joint limits
    drawConstraintArcs(position, joint, selectedBone) {
        if (!joint) return;

        const clockwiseLimit = joint.clockwiseConstraintDegs || 45;
        const anticlockwiseLimit = joint.anticlockwiseConstraintDegs || 45;

        push();

        // Set up arc drawing
        translate(position.x, position.y);
        noFill();
        strokeWeight(this.constraintVisualization.arcStrokeWeight);

        // Draw constraint arc background (full range)
        stroke(...this.constraintVisualization.constraintArcColor);
        const fullRangeStart = -anticlockwiseLimit * Math.PI / 180;
        const fullRangeEnd = clockwiseLimit * Math.PI / 180;
        arc(0, 0, this.constraintVisualization.arcRadius * 2, this.constraintVisualization.arcRadius * 2, 
            fullRangeStart, fullRangeEnd);

        // Draw constraint limit indicators
        this.drawConstraintLimitIndicators(clockwiseLimit, anticlockwiseLimit);

        // Draw anatomical validation if available
        this.drawAnatomicalValidation(selectedBone, clockwiseLimit, anticlockwiseLimit);

        pop();
    }

    // Draw current bone angle indicator
    drawCurrentAngleIndicator(selectedBone) {
        const bone = selectedBone.bone;
        const start = bone.start;
        const end = bone.end;

        // Calculate current angle
        const dx = end.x - start.x;
        const dy = end.y - start.y;
        const currentAngle = Math.atan2(dy, dx);

        push();
        translate(start.x, start.y);

        // Draw current angle line
        stroke(255, 255, 255);
        strokeWeight(3);
        const indicatorLength = this.constraintVisualization.arcRadius * 1.2;
        line(0, 0, 
             Math.cos(currentAngle) * indicatorLength, 
             Math.sin(currentAngle) * indicatorLength);

        // Draw angle value text
        fill(255);
        stroke(0);
        strokeWeight(1);
        textAlign(CENTER);
        textSize(10);
        const angleDeg = currentAngle * 180 / Math.PI;
        text(`${angleDeg.toFixed(1)}°`, 
             Math.cos(currentAngle) * (indicatorLength + 15), 
             Math.sin(currentAngle) * (indicatorLength + 15));

        pop();
    }

    // Draw constraint limit indicators (lines at constraint boundaries)
    drawConstraintLimitIndicators(clockwiseLimit, anticlockwiseLimit) {
        const radius = this.constraintVisualization.arcRadius;

        // Clockwise limit
        stroke(255, 100, 100); // Red
        strokeWeight(2);
        const clockwiseAngle = clockwiseLimit * Math.PI / 180;
        line(0, 0, 
             Math.cos(clockwiseAngle) * radius, 
             Math.sin(clockwiseAngle) * radius);

        // Anticlockwise limit
        const anticlockwiseAngle = -anticlockwiseLimit * Math.PI / 180;
        line(0, 0, 
             Math.cos(anticlockwiseAngle) * radius, 
             Math.sin(anticlockwiseAngle) * radius);

        // Draw limit labels
        fill(255, 100, 100);
        stroke(0);
        strokeWeight(1);
        textAlign(CENTER);
        textSize(8);

        // Clockwise label
        text(`+${clockwiseLimit}°`, 
             Math.cos(clockwiseAngle) * (radius + 20), 
             Math.sin(clockwiseAngle) * (radius + 20));

        // Anticlockwise label
        text(`-${anticlockwiseLimit}°`, 
             Math.cos(anticlockwiseAngle) * (radius + 20), 
             Math.sin(anticlockwiseAngle) * (radius + 20));
    }

    // Draw anatomical validation indicators
    drawAnatomicalValidation(selectedBone, clockwiseLimit, anticlockwiseLimit) {
        if (!this.builder.constraintSystem) return;

        try {
            // Get anatomical constraints for this bone/joint type
            const anatomicalConstraints = this.getAnatomicalConstraints(selectedBone);

            if (anatomicalConstraints) {
                const maxClockwise = anatomicalConstraints.maxClockwise || 180;
                const maxAnticlockwise = anatomicalConstraints.maxAnticlockwise || 180;

                // Check if current constraints exceed anatomical limits
                const clockwiseViolation = clockwiseLimit > maxClockwise;
                const anticlockwiseViolation = anticlockwiseLimit > maxAnticlockwise;

                if (clockwiseViolation || anticlockwiseViolation) {
                    this.drawAnatomicalViolationWarning(clockwiseViolation, anticlockwiseViolation);
                }

                // Draw anatomical limit references
                this.drawAnatomicalLimitReferences(maxClockwise, maxAnticlockwise);
            }

        } catch (error) {
            console.warn('Could not validate anatomical constraints:', error);
        }
    }

    // Get anatomical constraints for selected bone
    getAnatomicalConstraints(selectedBone) {
        if (!this.builder.constraintSystem || !this.builder.constraintSystem.getAnatomicalConstraints) {
            return null;
        }

        try {
            const chainConfig = this.builder.chainConfigs[selectedBone.chainIndex];
            const boneRole = this.determineBoneRole(selectedBone, chainConfig);

            return this.builder.constraintSystem.getAnatomicalConstraints(
                this.builder.creatureType,
                chainConfig.type,
                boneRole
            );

        } catch (error) {
            console.warn('Failed to get anatomical constraints:', error);
            return null;
        }
    }

    // Determine bone role within chain for anatomical lookup
    determineBoneRole(selectedBone, chainConfig) {
        const totalBones = this.builder.chains[selectedBone.chainIndex].numBones;
        const boneIndex = selectedBone.boneIndex;

        // Simple role determination based on position in chain
        if (boneIndex === 0) return 'proximal';
        if (boneIndex === totalBones - 1) return 'distal';
        return 'middle';
    }

    // Draw anatomical violation warning
    drawAnatomicalViolationWarning(clockwiseViolation, anticlockwiseViolation) {
        const radius = this.constraintVisualization.arcRadius;

        // Draw warning background
        fill(255, 0, 0, 50);
        noStroke();
        circle(0, 0, radius * 3);

        // Draw warning text
        fill(255, 0, 0);
        stroke(255);
        strokeWeight(1);
        textAlign(CENTER);
        textSize(10);
        textStyle(BOLD);
        text('⚠️ ANATOMICAL\nLIMIT EXCEEDED', 0, -radius * 1.8);
    }

    // Draw anatomical limit references
    drawAnatomicalLimitReferences(maxClockwise, maxAnticlockwise) {
        const radius = this.constraintVisualization.arcRadius * 0.8;

        stroke(100, 100, 100, 150);
        strokeWeight(1);
        setLineDash([2, 2]);

        // Anatomical clockwise limit
        const anatomicalClockwiseAngle = maxClockwise * Math.PI / 180;
        line(0, 0, 
             Math.cos(anatomicalClockwiseAngle) * radius, 
             Math.sin(anatomicalClockwiseAngle) * radius);

        // Anatomical anticlockwise limit
        const anatomicalAnticlockwiseAngle = -maxAnticlockwise * Math.PI / 180;
        line(0, 0, 
             Math.cos(anatomicalAnticlockwiseAngle) * radius, 
             Math.sin(anatomicalAnticlockwiseAngle) * radius);

        setLineDash([]); // Reset line dash
    }

    // Check if current bone angle violates constraints
    validateCurrentConstraints(selectedBone) {
        if (!selectedBone || !selectedBone.bone || !selectedBone.bone.joint) {
            return { valid: true, violations: [] };
        }

        const bone = selectedBone.bone;
        const joint = bone.joint;
        const start = bone.start;
        const end = bone.end;

        // Calculate current angle
        const dx = end.x - start.x;
        const dy = end.y - start.y;
        const currentAngle = Math.atan2(dy, dx) * 180 / Math.PI;

        // Check against joint constraints
        const clockwiseLimit = joint.clockwiseConstraintDegs || 45;
        const anticlockwiseLimit = joint.anticlockwiseConstraintDegs || 45;

        const violations = [];

        if (currentAngle > clockwiseLimit) {
            violations.push({
                type: 'clockwise',
                current: currentAngle,
                limit: clockwiseLimit,
                severity: 'constraint'
            });
        }

        if (currentAngle < -anticlockwiseLimit) {
            violations.push({
                type: 'anticlockwise',
                current: currentAngle,
                limit: -anticlockwiseLimit,
                severity: 'constraint'
            });
        }

        // Check against anatomical constraints if available
        const anatomicalConstraints = this.getAnatomicalConstraints(selectedBone);
        if (anatomicalConstraints) {
            const maxClockwise = anatomicalConstraints.maxClockwise || 180;
            const maxAnticlockwise = anatomicalConstraints.maxAnticlockwise || 180;

            if (currentAngle > maxClockwise) {
                violations.push({
                    type: 'anatomical-clockwise',
                    current: currentAngle,
                    limit: maxClockwise,
                    severity: 'anatomical'
                });
            }

            if (currentAngle < -maxAnticlockwise) {
                violations.push({
                    type: 'anatomical-anticlockwise',
                    current: currentAngle,
                    limit: -maxAnticlockwise,
                    severity: 'anatomical'
                });
            }
        }

        return {
            valid: violations.length === 0,
            violations: violations,
            currentAngle: currentAngle
        };
    }

    // Draw constraint violations as visual feedback
    drawConstraintViolations(selectedBone) {
        const validation = this.validateCurrentConstraints(selectedBone);

        if (!validation.valid) {
            const bone = selectedBone.bone;
            const start = bone.start;

            push();
            translate(start.x, start.y);

            // Draw violation indicators
            validation.violations.forEach((violation, index) => {
                const color = violation.severity === 'anatomical' 
                    ? this.constraintVisualization.violationColor 
                    : this.constraintVisualization.warningColor;

                stroke(...color);
                fill(...color, 100);
                strokeWeight(2);

                // Draw violation arc or indicator
                const offset = index * 15;
                circle(0, -40 - offset, 8);

                // Draw violation text
                fill(...color);
                stroke(255);
                strokeWeight(1);
                textAlign(CENTER);
                textSize(8);
                text(violation.type.replace('-', ' '), 0, -35 - offset);
            });

            pop();
        }
    }

    // Interactive constraint editing
    startConstraintEdit(selectedBone, constraintType, mouseX, mouseY) {
        if (!selectedBone || !selectedBone.bone || !selectedBone.bone.joint) {
            return false;
        }

        this.activeConstraintEdit = {
            bone: selectedBone,
            type: constraintType, // 'clockwise' or 'anticlockwise'
            startAngle: this.calculateAngleFromPosition(selectedBone.bone.getStartLocation(), mouseX, mouseY),
            startValue: constraintType === 'clockwise' 
                ? selectedBone.bone.joint.clockwiseConstraintDegs
                : selectedBone.bone.joint.anticlockwiseConstraintDegs
        };

        console.log(`Started constraint editing: ${constraintType}`);
        return true;
    }

    // Update constraint during drag
    updateConstraintEdit(mouseX, mouseY) {
        if (!this.activeConstraintEdit) return false;

        const bone = this.activeConstraintEdit.bone.bone;
        const start = bone.start;
        const currentAngle = this.calculateAngleFromPosition(start, mouseX, mouseY);
        const angleDelta = currentAngle - this.activeConstraintEdit.startAngle;

        // Calculate new constraint value
        let newValue = this.activeConstraintEdit.startValue + angleDelta * 180 / Math.PI;
        newValue = Math.max(0, Math.min(180, newValue)); // Clamp to reasonable range

        // Apply constraint
        if (this.activeConstraintEdit.type === 'clockwise') {
            bone.joint.clockwiseConstraintDegs = newValue;
        } else {
            bone.joint.anticlockwiseConstraintDegs = newValue;
        }

        // Update UI controls if they exist
        if (this.editor.skeletonControls) {
            this.editor.skeletonControls.updateControls();
        }

        return true;
    }

    // End constraint editing
    endConstraintEdit() {
        if (this.activeConstraintEdit) {
            // Record operation for undo
            if (this.editor.recordOperation) {
                this.editor.recordOperation('CONSTRAINT_MODIFY', {
                    chainIndex: this.activeConstraintEdit.bone.chainIndex,
                    boneIndex: this.activeConstraintEdit.bone.boneIndex,
                    constraintType: this.activeConstraintEdit.type,
                    newValue: this.activeConstraintEdit.type === 'clockwise'
                        ? this.activeConstraintEdit.bone.bone.joint.clockwiseConstraintDegs
                        : this.activeConstraintEdit.bone.bone.joint.anticlockwiseConstraintDegs
                });
            }

            console.log(`Finished constraint editing: ${this.activeConstraintEdit.type}`);
            this.activeConstraintEdit = null;
        }
    }

    // Calculate angle from position relative to point
    calculateAngleFromPosition(centerPoint, x, y) {
        const dx = x - centerPoint.x;
        const dy = y - centerPoint.y;
        return Math.atan2(dy, dx);
    }

    // Apply anatomical constraint presets
    applyAnatomicalPreset(selectedBone, presetName) {
        if (!selectedBone || !selectedBone.bone || !selectedBone.bone.joint) {
            return false;
        }

        const anatomicalConstraints = this.getAnatomicalConstraints(selectedBone);
        if (!anatomicalConstraints) {
            console.warn('No anatomical constraints available for preset application');
            return false;
        }

        const joint = selectedBone.bone.joint;

        switch (presetName) {
            case 'anatomical-max':
                joint.clockwiseConstraintDegs = anatomicalConstraints.maxClockwise || 90;
                joint.anticlockwiseConstraintDegs = anatomicalConstraints.maxAnticlockwise || 90;
                break;

            case 'conservative':
                joint.clockwiseConstraintDegs = (anatomicalConstraints.maxClockwise || 90) * 0.7;
                joint.anticlockwiseConstraintDegs = (anatomicalConstraints.maxAnticlockwise || 90) * 0.7;
                break;

            case 'rigid':
                joint.clockwiseConstraintDegs = 15;
                joint.anticlockwiseConstraintDegs = 15;
                break;

            case 'flexible':
                joint.clockwiseConstraintDegs = Math.min(120, anatomicalConstraints.maxClockwise || 120);
                joint.anticlockwiseConstraintDegs = Math.min(120, anatomicalConstraints.maxAnticlockwise || 120);
                break;

            default:
                console.warn(`Unknown constraint preset: ${presetName}`);
                return false;
        }

        console.log(`Applied anatomical preset: ${presetName}`);
        return true;
    }

    // Highlight selected joint for constraint editing
    drawJointHighlight(selectedJoint) {
        if (!selectedJoint || !selectedJoint.joint) return;

        // This would be similar to bone highlighting but specific to joints
        // Implementation depends on how joints are represented in the FIK.js system
        console.log('Drawing joint highlight for constraint editing');
    }

    // Get constraint editing status
    getConstraintEditingStatus() {
        return {
            active: this.activeConstraintEdit !== null,
            type: this.activeConstraintEdit?.type || null,
            bone: this.activeConstraintEdit?.bone || null
        };
    }

    // Cleanup
    cleanup() {
        this.endConstraintEdit();
        this.activeConstraintEdit = null;
        this.constraintDragState = null;
    }
}

class EditorMode {
    constructor(builder) {
        this.builder = builder;
        this.active = false;
        this.currentLayer = 'skeleton';
        this.selectedChain = null;

        // SKELETON EDITING EXTENSIONS - Multi-level selection system
        this.selectionMode = 'chain'; // 'chain', 'bone', 'joint'
        this.selectedBone = null; // { chainIndex, boneIndex, bone }
        this.selectedJoint = null; // { chainIndex, boneIndex, joint }

        // SKELETON EDITING EXTENSIONS - Editing modes and states  
        this.editingMode = 'select'; // 'select', 'move', 'rotate', 'scale', 'add', 'delete'
        this.ikTestMode = false;
        this.dragState = null; // { type, startPos, currentPos, target }

        // UI containers - create but hide initially
        this.ui = {
            sidebar: null,
            toolbar: null,
            modal: null
        };

        // State management
        this.savedBuilderState = null;
        this.performanceMonitor = {
            lastToggle: 0,
            frameSkips: 0,
            ikSolveRate: 30, // target fps for IK solving
            selectionResponseMax: 50, // max ms for selection response
            lastIKUpdate: 0
        };

        // SKELETON EDITING EXTENSIONS - Operation history for undo/redo
        this.operationHistory = [];
        this.historyIndex = -1;
        this.maxHistorySize = 50;

        this.initializeSkeletonEditing();
        this.setupUI();
    }

    // SKELETON EDITING EXTENSIONS - Initialize skeleton editing components
    initializeSkeletonEditing() {
        // Initialize BoneManipulator for individual bone selection and manipulation
        this.boneManipulator = new BoneManipulator(this.builder);

        // TASK 4: Initialize Template Palette System
        this.templatePalette = new TemplatePalette(this.builder, this);

        // TASK 5: Initialize Advanced UI Controls
        this.skeletonControls = new SkeletonControls(this.builder, this);

        // TASK 6: Initialize Joint Constraint Editor
        this.constraintEditor = new ConstraintEditor(this.builder, this);

        // TASK 7: Initialize ConfigManager for save/load functionality
        this.configManager = new ConfigManager(this.builder, this);

        // TASK 9: Initialize OperationHistory for undo/redo functionality
        this.operationHistory = new OperationHistory(this.builder, this);

        // TASK 4: Initialize SidebarUI for modular component system
        console.log('📋 Creating SidebarUI...');
        console.log('📋 SidebarUI class available:', typeof SidebarUI);

        if (typeof SidebarUI !== 'undefined') {
            this.sidebarUI = new SidebarUI(this.builder, this);
            console.log('📋 SidebarUI created:', this.sidebarUI);
        } else {
            console.error('❌ SidebarUI class is not defined, using fallback');
            this.sidebarUI = {
                initialize: () => console.log('📋 SidebarUI fallback initialize'),
                show: () => console.log('📋 SidebarUI fallback show'),
                hide: () => console.log('📋 SidebarUI fallback hide'),
                updateAll: () => console.log('📋 SidebarUI fallback updateAll'),
                cleanup: () => console.log('📋 SidebarUI fallback cleanup')
            };
        }

        console.log('Skeleton editing foundation initialized with BoneManipulator, TemplatePalette, SkeletonControls, ConstraintEditor, OperationHistory, and SidebarUI');
    }

    setupUI() {
        // Initialize the new modular SidebarUI
        console.log('🔧 Setting up UI, SidebarUI is:', this.sidebarUI);
        if (this.sidebarUI) {
            this.sidebarUI.initialize();
        } else {
            console.error('❌ SidebarUI is not initialized!');
        }

        // Create toolbar container (keeping existing toolbar for now)
        if (!this.ui.toolbar) {
            this.ui.toolbar = createDiv();
            this.ui.toolbar.id('editor-toolbar');
            this.ui.toolbar.position(250, 0);
            this.ui.toolbar.style(`
                width: calc(100vw - 250px); 
                height: 60px; 
                background: #e8e8e8; 
                position: fixed; 
                z-index: 1000; 
                border-bottom: 2px solid #ddd;
                display: none;
                padding: 10px;
                font-family: Arial, sans-serif;
                box-shadow: 0 2px 5px rgba(0,0,0,0.1);
            `);

            // Add basic toolbar content
            this.ui.toolbar.html(`
                <h3 style="margin: 0; display: inline-block; color: #333;">Madhuban Creature Editor</h3>
                <span style="float: right; margin-top: 5px; color: #666; font-size: 14px;">Layer: Skeleton | Press E to exit</span>
            `);
        }
    }

    show() {
        console.time('editor-show');
        this.active = true;
        this.performanceMonitor.lastToggle = Date.now();

        // Save builder state
        this.savedBuilderState = {
            locomotion: this.builder.activeLocomotion,
            renderMode: this.builder.renderMode,
            mouseTarget: new FIK.V2(this.builder.mouseTarget.x, this.builder.mouseTarget.y)
        };

        // CRITICAL: Enable editor mode in builder to freeze creature movement
        this.builder.editorActive = true;

        // Pause locomotion and set render mode
        this.builder.activeLocomotion = null;
        this.builder.renderMode = 'skeleton';

        // Show UI
        this.sidebarUI.show();
        if (this.ui.toolbar) this.ui.toolbar.style('display: block;');

        console.log('✅ Editor mode activated - creature movement frozen for selection');
        console.timeEnd('editor-show');
    }

    hide() {
        console.time('editor-hide');
        this.active = false;

        // CRITICAL: Disable editor mode in builder to restore creature movement
        this.builder.editorActive = false;

        // Restore builder state
        if (this.savedBuilderState) {
            this.builder.activeLocomotion = this.savedBuilderState.locomotion;
            this.builder.renderMode = this.savedBuilderState.renderMode;
            // Restore mouse target if needed
            if (this.savedBuilderState.mouseTarget) {
                this.builder.mouseTarget.set(
                    this.savedBuilderState.mouseTarget.x, 
                    this.savedBuilderState.mouseTarget.y
                );
            }
        }

        // Hide UI
        this.sidebarUI.hide();
        if (this.ui.toolbar) this.ui.toolbar.style('display: none;');

        // Clear selection
        this.selectedChain = null;
        this.clearSelection();

        console.log('✅ Editor mode deactivated - creature movement restored');
        console.timeEnd('editor-hide');
    }

    update() {
        if (!this.active) return;

        // Throttle expensive operations to maintain performance
        if (frameCount % 2 === 0) {
            this.updateUI();
        }

        // Performance monitoring
        if (frameCount % 60 === 0) { // Check once per second
            this.monitorPerformance();
        }
    }

