    setLayer(layerName) {
        this.currentLayer = layerName;
        this.sidebarUI.updateAll();
        console.log(`Editor layer changed to: ${layerName}`);
    }

    draw() {
        if (!this.active) return;

        // Draw selection highlighting
        this.drawSelectionHighlight();

        // Draw IK test mode visualization
        if (this.ikTestMode) {
            this.drawIKTestMode();
        }

        // Draw editor-specific overlays
        this.drawEditingOverlay();
    }

    // SKELETON EDITING EXTENSIONS - Enhanced selection highlighting
    drawSelectionHighlight() {
        // Draw chain highlighting if one is selected
        if (this.selectedChain !== null) {
            this.drawChainHighlight();
        }

        // Draw bone highlighting if one is selected (will be implemented in Task 2)
        if (this.selectedBone && this.boneManipulator) {
            this.boneManipulator.drawBoneHighlight(this.selectedBone);
        }

        // TASK 6: Draw joint highlighting and constraint visualization
        if (this.selectedJoint && this.constraintEditor) {
            this.constraintEditor.drawJointHighlight(this.selectedJoint);
        }

        // TASK 6: Draw constraint visualization for selected bone with joint
        if (this.selectedBone && this.selectedBone.bone && this.selectedBone.bone.joint && this.constraintEditor) {
            this.constraintEditor.drawJointConstraints(this.selectedBone);
        }
    }

    // SKELETON EDITING EXTENSIONS - Enhanced IK Test Mode visualization
    drawIKTestMode() {
        if (!this.ikTestMode) return;

        // Draw enhanced reachable areas and end-effector targets
        this.builder.chains.forEach((chain, index) => {
            if (chain.numBones === 0) return;

            const base = chain.bones[0].start;
            const effector = chain.bones[chain.numBones - 1].end;

            // Calculate chain length for reachable area
            let chainLength = 0;
            for (let i = 0; i < chain.numBones; i++) {
                chainLength += chain.bones[i].getLength();
            }

            push();

            // Enhanced reachable area visualization
            const isSelected = this.selectedChain === index;

            // Draw outer reachable area (full extension)
            noFill();
            stroke(100, 255, 100, isSelected ? 150 : 80);
            strokeWeight(isSelected ? 2 : 1);
            circle(base.x, base.y, chainLength * 2);

            // Draw inner dead zone (minimum reach)
            if (chain.numBones > 1) {
                const minReach = Math.abs(chainLength - chain.bones[0].getLength() * 2);
                stroke(255, 100, 100, isSelected ? 100 : 50);
                strokeWeight(1);
                circle(base.x, base.y, minReach * 2);
            }

            // Draw chain base indicator
            fill(isSelected ? 255 : 200, isSelected ? 255 : 200, 100, 200);
            noStroke();
            circle(base.x, base.y, 6);

            // Enhanced end-effector visualization
            const hoverDistance = dist(mouseX, mouseY, effector.x, effector.y);
            const isHovered = hoverDistance < 15;

            // End-effector with hover feedback
            fill(255, 100, 100, isSelected || isHovered ? 255 : 180);
            noStroke();
            circle(effector.x, effector.y, isSelected || isHovered ? 12 : 8);

            // Add selection ring for selected chain
            if (isSelected) {
                noFill();
                stroke(255, 255, 0, 200);
                strokeWeight(2);
                circle(effector.x, effector.y, 18);
            }

            // Hover ring for interactive feedback
            if (isHovered && !isSelected) {
                noFill();
                stroke(255, 255, 255, 150);
                strokeWeight(1);
                circle(effector.x, effector.y, 15);
            }

            // Chain information label with enhanced styling
            fill(255, 255, 255, 200);
            stroke(0, 0, 0, 100);
            strokeWeight(1);
            textAlign(CENTER);
            textSize(10);
            textStyle(BOLD);
            text(`Chain ${index}`, effector.x, effector.y + 25);

            // Add bone count for detailed info
            if (isSelected || isHovered) {
                textSize(8);
                textStyle(NORMAL);
                fill(200, 200, 200, 180);
                text(`${chain.numBones} bones`, effector.x, effector.y + 35);
                text(`${chainLength.toFixed(0)}px reach`, effector.x, effector.y + 45);
            }

            // Draw constraint visualization for selected chain
            if (isSelected) {
                this.drawChainConstraints(chain, index);
            }

            pop();
        });

        // Draw IK target feedback if dragging
        this.drawIKTargetFeedback();

        // Enhanced IK test mode indicator with status
        push();
        fill(255, 100, 100, 200);
        stroke(0, 0, 0, 100);
        strokeWeight(1);
        textAlign(LEFT);
        textSize(16);
        textStyle(BOLD);
        text('🎯 IK TEST MODE', 260, 30);

        // Performance indicator
        textSize(12);
        textStyle(NORMAL);
        fill(200, 200, 200, 180);
        text(`FPS: ${frameRate().toFixed(1)} | Drag end-effectors to test poses`, 260, 45);

        // Selected chain info
        if (this.selectedChain !== null && this.selectedChain < this.builder.chains.length) {
            const chainConfig = this.builder.chainConfigs[this.selectedChain];
            textSize(11);
            fill(255, 255, 100, 200);
            text(`Selected: ${chainConfig.role} (Chain ${this.selectedChain})`, 260, 60);
        }

        pop();
    }

    // SKELETON EDITING EXTENSIONS - Draw constraint visualization for chain
    drawChainConstraints(chain, chainIndex) {
        if (!chain || chain.numBones === 0) return;

        // Draw constraint arcs for joints
        for (let i = 1; i < chain.numBones; i++) {
            const bone = chain.bones[i];
            const prevBone = chain.bones[i - 1];

            if (bone.joint) {
                const jointPos = prevBone.end;
                const constraintRadius = 30;

                push();
                translate(jointPos.x, jointPos.y);

                // Get bone direction for constraint arc positioning
                const boneAngle = atan2(bone.end.y - bone.start.y, bone.end.x - bone.start.x);

                // Draw constraint arc
                noFill();
                stroke(255, 200, 100, 120);
                strokeWeight(2);

                const clockwiseLimit = radians(bone.joint.clockwiseConstraintDegs || 45);
                const anticlockwiseLimit = radians(bone.joint.anticlockwiseConstraintDegs || 45);

                arc(0, 0, constraintRadius, constraintRadius, 
                    boneAngle - anticlockwiseLimit, 
                    boneAngle + clockwiseLimit);

                // Draw constraint limit lines
                stroke(255, 150, 100, 80);
                strokeWeight(1);
                const limitLength = constraintRadius / 2;

                // Clockwise limit
                line(0, 0, 
                     cos(boneAngle + clockwiseLimit) * limitLength,
                     sin(boneAngle + clockwiseLimit) * limitLength);

                // Anticlockwise limit
                line(0, 0,
                     cos(boneAngle - anticlockwiseLimit) * limitLength,
                     sin(boneAngle - anticlockwiseLimit) * limitLength);

                pop();
            }
        }
    }

    // SKELETON EDITING EXTENSIONS - Draw IK target feedback during dragging
    drawIKTargetFeedback() {
        if (!this.ikTargetState || !this.ikTestMode) return;

        // Draw target feedback for each chain being manipulated
        Object.keys(this.ikTargetState).forEach(chainIndex => {
            const state = this.ikTargetState[chainIndex];
            if (!state || !state.target) return;

            const target = state.target;

            push();

            // Target indicator with status coloring
            let targetColor, targetSize;
            if (state.inDeadZone) {
                targetColor = [255, 100, 255]; // Magenta for dead zone
                targetSize = 16;
            } else if (!state.reachable) {
                targetColor = [255, 50, 50]; // Red for unreachable
                targetSize = 12;
            } else {
                targetColor = [100, 255, 100]; // Green for reachable
                targetSize = 10;
            }

            // Draw target with pulsing effect
            const pulse = sin(frameCount * 0.2) * 0.3 + 0.7;
            fill(targetColor[0], targetColor[1], targetColor[2], 200 * pulse);
            noStroke();
            circle(target.x, target.y, targetSize);

            // Draw crosshair for precise targeting
            stroke(targetColor[0], targetColor[1], targetColor[2], 150);
            strokeWeight(2);
            line(target.x - 8, target.y, target.x + 8, target.y);
            line(target.x, target.y - 8, target.x, target.y + 8);

            // Status text near target
            fill(255, 255, 255, 200);
            stroke(0, 0, 0, 100);
            strokeWeight(1);
            textAlign(CENTER);
            textSize(9);
            textStyle(NORMAL);

            let statusText = '';
            if (state.inDeadZone) {
                statusText = 'DEAD ZONE';
            } else if (!state.reachable) {
                statusText = `OUT OF REACH (+${(state.distance - state.maxReach).toFixed(0)}px)`;
            } else {
                statusText = `${(state.maxReach - state.distance).toFixed(0)}px available`;
            }

            text(statusText, target.x, target.y - 20);

            pop();
        });
    }

    drawChainHighlight() {
        if (this.selectedChain >= this.builder.chains.length) return;

        const chain = this.builder.chains[this.selectedChain];
        push();
        stroke(255, 255, 0); // Yellow highlight
        strokeWeight(4);
        noFill();

        // Draw outline around chain
        for (let i = 0; i < chain.numBones; i++) {
            const bone = chain.bones[i];
            const start = bone.start;
            const end = bone.end;
            line(start.x, start.y, end.x, end.y);
        }
        pop();
    }

    drawEditingOverlay() {
        // Draw grid in background for reference
        push();
        stroke(200, 200, 200, 100);
        strokeWeight(1);

        const gridSize = 20;
        for (let x = 250; x < width; x += gridSize) { // Start after sidebar
            line(x, 60, x, height); // Start below toolbar
        }
        for (let y = 60; y < height; y += gridSize) {
            line(250, y, width, y);
        }
        pop();

        // Draw canvas boundaries
        push();
        stroke(100, 100, 100, 150);
        strokeWeight(2);
        noFill();
        rect(250, 60, width - 250, height - 60);
        pop();
    }

    handleMouseClick() {
        if (!this.active) return false;

        // Check if click is in canvas area (not on UI)
        if (mouseX < 250 || mouseY < 60) return false;

        // SKELETON EDITING EXTENSIONS - Multi-level selection handling
        const selectionResult = this.handleSkeletonSelection(mouseX, mouseY);
        if (selectionResult) {
            this.sidebarUI.updateAll();
            // TASK 5: Update controls when selection changes
            if (this.skeletonControls) {
                this.skeletonControls.updateControls();
            }
            return true;
        }

        // Click on empty space deselects all
        this.clearSelection();
        this.sidebarUI.updateAll();
        // TASK 5: Hide controls when nothing is selected
        if (this.skeletonControls) {
            this.skeletonControls.hideControls();
        }
        return true;
    }

    // SKELETON EDITING EXTENSIONS - Multi-level selection system
    handleSkeletonSelection(mouseX, mouseY) {
        const startTime = performance.now();

        // First try bone-level selection if in bone mode
        if (this.selectionMode === 'bone' && this.boneManipulator) {
            const boneResult = this.boneManipulator.selectBone(mouseX, mouseY);
            if (boneResult) {
                this.selectedBone = boneResult;
                this.selectedChain = boneResult.chainIndex;
                this.selectedJoint = null;

                // Record selection performance
                const selectionTime = performance.now() - startTime;
                if (selectionTime > this.performanceMonitor.selectionResponseMax) {
                    console.warn(`Bone selection took ${selectionTime.toFixed(1)}ms`);
                }
                return true;
            }
        }

        // Try chain-level selection (existing logic)
        for (let i = 0; i < this.builder.chains.length; i++) {
            if (this.isPointNearChain(mouseX, mouseY, this.builder.chains[i])) {
                this.selectedChain = i;
                this.selectedBone = null;
                this.selectedJoint = null;
                return true;
            }
        }

        return false;
    }

    // SKELETON EDITING EXTENSIONS - Clear all selections
    clearSelection() {
        this.selectedChain = null;
        this.selectedBone = null;
        this.selectedJoint = null;
    }

    // SKELETON EDITING EXTENSIONS - Toggle IK Test Mode
    toggleIKTestMode() {
        this.ikTestMode = !this.ikTestMode;

        if (this.ikTestMode) {
            console.log('IK Test Mode: ENABLED - Drag end-effectors to test poses');
            // Optimize all chains for real-time IK solving
            this.optimizeChainsForIK();
        } else {
            console.log('IK Test Mode: DISABLED');
            // Restore normal precision settings
            this.restoreNormalChainPrecision();
        }

        this.sidebarUI.updateAll();
        return this.ikTestMode;
    }

    // SKELETON EDITING EXTENSIONS - Optimize chains for real-time IK
    optimizeChainsForIK() {
        this.builder.chains.forEach(chain => {
            if (chain.setMaxIterationAttempts) {
                chain.setMaxIterationAttempts(6); // vs default 15
            }
            if (chain.setSolveDistanceThreshold) {
                chain.setSolveDistanceThreshold(2.5); // vs default 1.0
            }
            if (chain.setMinIterationChange) {
                chain.setMinIterationChange(0.08); // vs default 0.01
            }
        });
    }

    // SKELETON EDITING EXTENSIONS - Restore normal chain precision
    restoreNormalChainPrecision() {
        this.builder.chains.forEach(chain => {
            if (chain.setMaxIterationAttempts) {
                chain.setMaxIterationAttempts(15); // default
            }
            if (chain.setSolveDistanceThreshold) {
                chain.setSolveDistanceThreshold(1.0); // default
            }
            if (chain.setMinIterationChange) {
                chain.setMinIterationChange(0.01); // default
            }
        });
    }

    // SKELETON EDITING EXTENSIONS - Handle mouse dragging for bone manipulation
    handleMouseDrag() {
        if (!this.active) return false;

        // IK Test Mode end-effector dragging
        if (this.ikTestMode && this.selectedChain !== null) {
            return this.handleIKDrag(this.selectedChain, mouseX, mouseY);
        }

        // Bone manipulation dragging (will be implemented in Task 3)
        if (this.selectedBone && this.boneManipulator) {
            return this.boneManipulator.handleBoneDrag(this.selectedBone, mouseX, mouseY, this.editingMode);
        }

        return false;
    }

    // SKELETON EDITING EXTENSIONS - Enhanced IK dragging with constraint validation
    handleIKDrag(chainIndex, targetX, targetY) {
        if (chainIndex >= this.builder.chains.length) return false;

        // Performance optimization - throttle IK updates
        const now = performance.now();
        if (now - this.performanceMonitor.lastIKUpdate < (1000 / this.performanceMonitor.ikSolveRate)) {
            return false;
        }

        const chain = this.builder.chains[chainIndex];
        const target = new FIK.V2(targetX, targetY);
        const base = chain.bones[0].start;

        // Calculate distance to validate reachability
        const distanceToTarget = base.distanceTo(target);
        let chainLength = 0;
        for (let i = 0; i < chain.numBones; i++) {
            chainLength += chain.bones[i].getLength();
        }

        // Visual feedback for reachability
        const isReachable = distanceToTarget <= chainLength;
        const isInDeadZone = chain.numBones > 1 && 
            distanceToTarget < Math.abs(chainLength - chain.bones[0].getLength() * 2);

        // Store target state for visual feedback
        if (!this.ikTargetState) this.ikTargetState = {};
        this.ikTargetState[chainIndex] = {
            target: target,
            reachable: isReachable,
            inDeadZone: isInDeadZone,
            distance: distanceToTarget,
            maxReach: chainLength
        };

        try {
            // Attempt IK solve with performance monitoring
            const solveStart = performance.now();

            if (isReachable && !isInDeadZone) {
                chain.solveForTarget(target);
            } else if (isReachable) {
                // Target in dead zone - solve to closest valid position
                const direction = target.minus(base).normalize();
                const minReach = Math.abs(chainLength - chain.bones[0].getLength() * 2);
                const adjustedTarget = base.plus(direction.multiply(minReach + 5));
                chain.solveForTarget(adjustedTarget);
            } else {
                // Target unreachable - solve to maximum reach in target direction
                const direction = target.minus(base).normalize();
                const maxTarget = base.plus(direction.multiply(chainLength - 1));
                chain.solveForTarget(maxTarget);
            }

            // Performance monitoring
            const solveTime = performance.now() - solveStart;
            if (solveTime > 16.67) { // More than one frame at 60fps
                console.warn(`IK solve took ${solveTime.toFixed(1)}ms for chain ${chainIndex}`);
            }

            this.performanceMonitor.lastIKUpdate = now;
            return true;

        } catch (error) {
            console.error(`IK solve error for chain ${chainIndex}:`, error);
            return false;
        }
    }

    // SKELETON EDITING EXTENSIONS - Switch selection mode
    setSelectionMode(mode) {
        if (['chain', 'bone', 'joint'].includes(mode)) {
            this.selectionMode = mode;
            this.clearSelection();
            this.sidebarUI.updateAll();
            console.log(`Selection mode: ${mode}`);
        }
    }

    // SKELETON EDITING EXTENSIONS - Switch editing mode  
    setEditingMode(mode) {
        if (['select', 'move', 'rotate', 'scale', 'add', 'delete'].includes(mode)) {
            this.editingMode = mode;
            console.log(`Editing mode: ${mode}`);
        }
    }

    isPointNearChain(px, py, chain) {
        const threshold = 15; // Generous click threshold

        for (let i = 0; i < chain.numBones; i++) {
            const bone = chain.bones[i];
            const start = bone.start;
            const end = bone.end;

            // Calculate distance from point to line segment
            const dist = this.pointToLineDistance(px, py, start.x, start.y, end.x, end.y);
            if (dist < threshold) return true;
        }
        return false;
    }

    pointToLineDistance(px, py, x1, y1, x2, y2) {
        const A = px - x1;
        const B = py - y1;
        const C = x2 - x1;
        const D = y2 - y1;

        const dot = A * C + B * D;
        const lenSq = C * C + D * D;

        if (lenSq === 0) return dist(px, py, x1, y1);

        let param = dot / lenSq;
        param = constrain(param, 0, 1);

        const xx = x1 + param * C;
        const yy = y1 + param * D;

        return dist(px, py, xx, yy);
    }

    monitorPerformance() {
        // Simple performance monitoring
        const currentTime = Date.now();
        if (this.performanceMonitor.lastToggle > 0) {
            const timeSinceToggle = currentTime - this.performanceMonitor.lastToggle;
            if (frameRate() < 50) {
                this.performanceMonitor.frameSkips++;
                console.warn(`Editor performance warning: ${frameRate().toFixed(1)}fps`);
            }
        }
    }

    // SAVE/LOAD FUNCTIONALITY (PRP1-7)
    saveCreatureConfig() {
        try {
            const format = document.getElementById('editor-export-format')?.value || 'complete';
            const filename = `${this.builder.creatureType}-${format}-${Date.now()}.json`;

            console.log(`💾 Saving creature configuration as ${format}...`);
            this.configManager.downloadConfig(filename, format);

            // Show success message temporarily
            this.showTemporaryMessage('Configuration saved successfully!', 'success');

        } catch (error) {
            console.error('❌ Failed to save configuration:', error);
            this.showTemporaryMessage('Failed to save configuration. Check console for details.', 'error');
        }
    }

    loadCreatureConfig() {
        // Trigger file upload dialog
        const fileInput = document.getElementById('editor-config-upload');
        if (fileInput) {
            fileInput.click();
        }
    }

    async handleConfigUpload(fileInput) {
        try {
            console.log('📁 Loading creature configuration...');
            const success = await this.configManager.uploadConfig(fileInput);

            if (success) {
                this.showTemporaryMessage('Configuration loaded successfully!', 'success');

                // Clear file input for future uploads
                fileInput.value = '';
            }

        } catch (error) {
            console.error('❌ Failed to load configuration:', error);
            this.showTemporaryMessage(`Failed to load configuration: ${error.message}`, 'error');

            // Clear file input
            fileInput.value = '';
        }
    }

    exportCreatureConfig() {
        try {
            const format = document.getElementById('editor-export-format')?.value || 'complete';
            const config = this.configManager.exportConfig(format);

            console.log('📋 Configuration exported to console:');
            console.log(JSON.stringify(config, null, 2));

            // Copy to clipboard if possible
            if (navigator.clipboard) {
                navigator.clipboard.writeText(JSON.stringify(config, null, 2))
                    .then(() => {
                        this.showTemporaryMessage('Configuration copied to clipboard!', 'success');
                    })
                    .catch(() => {
                        this.showTemporaryMessage('Configuration exported to console.', 'info');
                    });
            } else {
                this.showTemporaryMessage('Configuration exported to console.', 'info');
            }

        } catch (error) {
            console.error('❌ Failed to export configuration:', error);
            this.showTemporaryMessage('Failed to export configuration. Check console for details.', 'error');
        }
    }

    // Show temporary message to user
    showTemporaryMessage(message, type = 'info') {
        // Create temporary message div
        const messageDiv = createDiv();
        messageDiv.style(`
            position: fixed;
            top: 70px;
            left: 260px;
            padding: 10px 15px;
            border-radius: 5px;
            font-size: 12px;
            font-weight: bold;
            z-index: 1001;
            ${type === 'success' ? 'background: #d4edda; color: #155724; border: 1px solid #c3e6cb;' : ''}
            ${type === 'error' ? 'background: #f8d7da; color: #721c24; border: 1px solid #f5c6cb;' : ''}
            ${type === 'info' ? 'background: #d1ecf1; color: #0c5460; border: 1px solid #bee5eb;' : ''}
        `);
        messageDiv.html(message);

        // Remove after 3 seconds
        setTimeout(() => {
            if (messageDiv.elt && messageDiv.elt.parentNode) {
                messageDiv.remove();
            }
        }, 3000);
    }

    // UNDO/REDO FUNCTIONALITY (PRP2-9)
    undoOperation() {
        if (!this.operationHistory || !this.operationHistory.canUndo()) {
            console.warn('⚠️ Cannot undo: no operations available');
            return false;
        }

        try {
            const success = this.operationHistory.undo();
            if (success) {
                this.showTemporaryMessage('Operation undone successfully', 'info');
                console.log('↩️ Undo completed');
            } else {
                this.showTemporaryMessage('Failed to undo operation', 'error');
            }
            return success;
        } catch (error) {
            console.error('❌ Error during undo:', error);
            this.showTemporaryMessage('Error during undo operation', 'error');
            return false;
        }
    }

    redoOperation() {
        if (!this.operationHistory || !this.operationHistory.canRedo()) {
            console.warn('⚠️ Cannot redo: no operations available');
            return false;
        }

        try {
            const success = this.operationHistory.redo();
            if (success) {
                this.showTemporaryMessage('Operation redone successfully', 'info');
                console.log('↪️ Redo completed');
            } else {
                this.showTemporaryMessage('Failed to redo operation', 'error');
            }
            return success;
        } catch (error) {
            console.error('❌ Error during redo:', error);
            this.showTemporaryMessage('Error during redo operation', 'error');
            return false;
        }
    }

    // Record operation for undo/redo system
    recordOperation(type, description, beforeState, afterState) {
        if (!this.operationHistory) return null;

        return this.operationHistory.recordOperation(type, {
            description: description,
            timestamp: Date.now()
        }, beforeState, afterState);
    }

    // Keyboard shortcuts for undo/redo
    handleKeyboardShortcuts(event) {
        if (!this.active) return false;

        // Ctrl+Z for undo
        if (event.ctrlKey && event.key === 'z' && !event.shiftKey) {
            event.preventDefault();
            this.undoOperation();
            return true;
        }

        // Ctrl+Y or Ctrl+Shift+Z for redo
        if (event.ctrlKey && (event.key === 'y' || (event.key === 'z' && event.shiftKey))) {
            event.preventDefault();
            this.redoOperation();
            return true;
        }

        return false;
    }

    cleanup() {
        // Cleanup ConfigManager
        if (this.configManager) {
            this.configManager = null;
        }

        // Cleanup OperationHistory
        if (this.operationHistory) {
            this.operationHistory.cleanup();
            this.operationHistory = null;
        }

        // Cleanup SidebarUI
        if (this.sidebarUI) {
            this.sidebarUI.cleanup();
            this.sidebarUI = null;
        }

        // Cleanup template palette
        if (this.templatePalette) {
            this.templatePalette.cleanup();
            this.templatePalette = null;
        }

        // Cleanup skeleton controls
        if (this.skeletonControls) {
            this.skeletonControls.cleanup();
            this.skeletonControls = null;
        }

        // Cleanup constraint editor
        if (this.constraintEditor) {
            this.constraintEditor.cleanup();
            this.constraintEditor = null;
        }

        // Remove DOM elements
        if (this.ui.sidebar) {
            this.ui.sidebar.remove();
            this.ui.sidebar = null;
        }
        if (this.ui.toolbar) {
            this.ui.toolbar.remove();
            this.ui.toolbar = null;
        }
        if (this.ui.modal) {
            this.ui.modal.remove();
            this.ui.modal = null;
        }

        this.active = false;
        this.selectedChain = null;
        this.clearSelection();
    }
}

/**
 * Configuration Manager for JSON Import/Export (PRP1-7)
 * 
 * Provides save/load functionality for creature configurations with editor metadata.
 * Compatible with existing ModularCreatureBuilder system and supports modified skeletons.
 */

class ConfigManager {
    constructor(builder, editor) {
        this.builder = builder;
        this.editor = editor;

        // Configuration version for backward compatibility
        this.configVersion = '1.0';

        // Supported export formats
        this.exportFormats = {
            'complete': 'Complete creature with editor modifications',
            'skeleton': 'Skeleton configuration only',
            'base': 'Base creature template without modifications'
        };

        console.log('ConfigManager initialized for JSON import/export');
    }

    /**
     * Export current creature configuration to JSON
     * @param {string} format - Export format ('complete', 'skeleton', 'base')
     * @param {Object} options - Export options
     * @returns {Object} Serializable configuration object
     */
    exportConfig(format = 'complete', options = {}) {
        console.time('config-export');

        try {
            const config = {
                // Metadata
                version: this.configVersion,
                exportDate: new Date().toISOString(),
                format: format,

                // Core creature data
                creatureType: this.builder.creatureType,
                creatureConfig: this.deepClone(this.builder.creatureConfig),

                // Chain configurations
                chainConfigs: this.serializeChainConfigs(),

                // Locomotion data
                locomotion: this.serializeLocomotion(),

                // Editor metadata
                editorMetadata: this.buildEditorMetadata(),

                // Export options
                options: options
            };

            // Apply format-specific filtering
            switch (format) {
                case 'skeleton':
                    delete config.locomotion;
                    config.chainConfigs = config.chainConfigs.map(chain => ({
                        ...chain,
                        locomotionRole: undefined
                    }));
                    break;

                case 'base':
                    delete config.editorMetadata;
                    break;
            }

            console.timeEnd('config-export');
            console.log(`✅ Exported ${format} configuration for ${this.builder.creatureType}`);

            return config;

        } catch (error) {
            console.error('❌ Failed to export configuration:', error);
            throw new Error(`Configuration export failed: ${error.message}`);
        }
    }

    /**
     * Import creature configuration from JSON
     * @param {Object} config - Configuration object
     * @param {Object} options - Import options
     * @returns {boolean} Success status
     */
    importConfig(config, options = {}) {
        console.time('config-import');

        try {
            // Validate configuration
            if (!this.validateConfig(config)) {
                throw new Error('Invalid configuration format');
            }

            // Check version compatibility
            if (!this.isVersionCompatible(config.version)) {
                console.warn(`⚠️ Configuration version ${config.version} may not be fully compatible`);
            }

            // Clear current creature
            this.builder.clearCreature();

            // Set basic creature properties
            this.builder.creatureType = config.creatureType;
            this.builder.creatureConfig = this.deepClone(config.creatureConfig);

            // Import chains
            this.importChains(config.chainConfigs);

            // Import locomotion
            if (config.locomotion) {
                this.importLocomotion(config.locomotion);
            }

            // Apply editor metadata if present
            if (config.editorMetadata) {
                this.applyEditorMetadata(config.editorMetadata);
            }

            // Update editor UI if active
            if (this.editor && this.editor.active) {
                this.editor.updateSidebar();
            }

            console.timeEnd('config-import');
            console.log(`✅ Imported ${config.format || 'complete'} configuration for ${config.creatureType}`);

            return true;

        } catch (error) {
            console.error('❌ Failed to import configuration:', error);

            // Attempt to restore a basic creature
            this.restoreBasicCreature();

            throw new Error(`Configuration import failed: ${error.message}`);
        }
    }

    /**
     * Serialize chain configurations with current state
     */
    serializeChainConfigs() {
        return this.builder.chainConfigs.map((config, index) => {
            const chain = this.builder.chains[index];
            const serializedConfig = this.deepClone(config);

            // Add current chain state if editor is active
            if (this.editor && this.editor.active && chain) {
                serializedConfig.currentState = this.serializeChainState(chain);
            }

            return serializedConfig;
        });
    }

    /**
     * Serialize current chain state (bone positions, constraints)
     */
    serializeChainState(chain) {
        const bones = [];

        for (let i = 0; i < chain.numBones; i++) {
            const bone = chain.bones[i];
            const start = bone.start;
            const end = bone.end;

            bones.push({
                index: i,
                length: bone.getLength(),
                startX: start.x,
                startY: start.y,
                endX: end.x,
                endY: end.y,
                constraints: bone.joint ? {
                    clockwise: bone.joint.clockwiseConstraintDegs || 45,
                    anticlockwise: bone.joint.anticlockwiseConstraintDegs || 45
                } : null
            });
        }

        return {
            bones: bones,
            baseMode: chain.getFixedBaseMode(),
            maxIterations: chain.maxIterationAttempts || 15,
            solveThreshold: chain.solveDistanceThreshold || 1.0
        };
    }

    /**
     * Serialize locomotion configuration
     */
    serializeLocomotion() {
        if (!this.builder.activeLocomotion) return null;

        return {
            type: this.builder.activeLocomotion.type || 'unknown',
            parameters: this.builder.activeLocomotion.parameters || {},
            state: this.builder.activeLocomotion.getState ? 
                this.builder.activeLocomotion.getState() : {}
        };
    }

    /**
     * Build editor metadata for modified skeletons
     */
    buildEditorMetadata() {
        const metadata = {
            lastModified: new Date().toISOString(),
            editorVersion: '1.0',
            modifications: []
        };

        // Add operation history if available
        if (this.editor && this.editor.operationHistory) {
            metadata.operationHistory = this.editor.operationHistory.slice(-50); // Last 50 operations
        }

        // Add selection state
        if (this.editor) {
            metadata.editorState = {
                selectionMode: this.editor.selectionMode,
                editingMode: this.editor.editingMode,
                currentLayer: this.editor.currentLayer
            };
        }

        return metadata;
    }

    /**
     * Import chains from configuration
     */
    importChains(chainConfigs) {
        chainConfigs.forEach((config, index) => {
            try {
                // Create chain from configuration
                const chain = this.builder.createChainFromConfig(config);

                // Apply current state if available
                if (config.currentState) {
                    this.applyChainState(chain, config.currentState);
                }

            } catch (error) {
                console.warn(`⚠️ Failed to import chain ${index}: ${error.message}`);
            }
        });
    }

    /**
     * Import locomotion configuration
     */
    importLocomotion(locomotionConfig) {
        try {
            if (this.builder.locomotionSystem && locomotionConfig.type) {
                this.builder.activeLocomotion = this.builder.locomotionSystem.createPattern(
                    locomotionConfig.type,
                    locomotionConfig.parameters
                );

                // Apply saved state if available
                if (locomotionConfig.state && this.builder.activeLocomotion.setState) {
                    this.builder.activeLocomotion.setState(locomotionConfig.state);
                }
            }
        } catch (error) {
            console.warn(`⚠️ Failed to import locomotion: ${error.message}`);
        }
    }

    /**
     * Apply editor metadata to restore editor state
     */
    applyEditorMetadata(metadata) {
        if (!this.editor) return;

        try {
            // Restore editor state
            if (metadata.editorState) {
                this.editor.selectionMode = metadata.editorState.selectionMode || 'chain';
                this.editor.editingMode = metadata.editorState.editingMode || 'select';
                this.editor.currentLayer = metadata.editorState.currentLayer || 'skeleton';
            }

            // Restore operation history if available
            if (metadata.operationHistory && this.editor.operationHistory) {
                this.editor.operationHistory = metadata.operationHistory;
                this.editor.historyIndex = metadata.operationHistory.length - 1;
            }

        } catch (error) {
            console.warn(`⚠️ Failed to apply editor metadata: ${error.message}`);
        }
    }

    /**
     * Apply serialized chain state to chain
     */
    applyChainState(chain, state) {
        try {
            // Apply bone positions and constraints
            state.bones.forEach((boneState, index) => {
                if (index < chain.numBones) {
                    const bone = chain.bones[index];

                    // Apply bone constraints
                    if (boneState.constraints && bone.joint) {
                        bone.joint.clockwiseConstraintDegs = boneState.constraints.clockwise;
                        bone.joint.anticlockwiseConstraintDegs = boneState.constraints.anticlockwise;
                    }
                }
            });

            // Apply chain settings
            if (state.maxIterations && chain.setMaxIterationAttempts) {
                chain.setMaxIterationAttempts(state.maxIterations);
            }

            if (state.solveThreshold && chain.setSolveDistanceThreshold) {
                chain.setSolveDistanceThreshold(state.solveThreshold);
            }

        } catch (error) {
            console.warn(`⚠️ Failed to apply chain state: ${error.message}`);
        }
    }

    /**
     * Validate configuration format
     */
    validateConfig(config) {
        if (!config || typeof config !== 'object') return false;

        // Required fields
        const requiredFields = ['version', 'creatureType', 'chainConfigs'];
        for (const field of requiredFields) {
            if (!(field in config)) {
                console.error(`❌ Missing required field: ${field}`);
                return false;
            }
        }

        // Validate chain configs
        if (!Array.isArray(config.chainConfigs)) {
            console.error(`❌ Invalid chainConfigs format`);
            return false;
        }

        // Validate creature type
        const validCreatureTypes = ['fish', 'crane', 'horse', 'lizard'];
        if (!validCreatureTypes.includes(config.creatureType)) {
            console.warn(`⚠️ Unknown creature type: ${config.creatureType}`);
        }

        return true;
    }

    /**
     * Check version compatibility
     */
    isVersionCompatible(version) {
        // Simple version compatibility check
        const major = parseFloat(version);
        const currentMajor = parseFloat(this.configVersion);

        return major <= currentMajor;
    }

    /**
     * Restore basic creature on import failure
     */
    restoreBasicCreature() {
        try {
            console.log('🔄 Restoring basic horse creature after import failure');
            this.builder.buildHorse();
        } catch (error) {
            console.error('❌ Failed to restore basic creature:', error);
        }
    }

    /**
     * Download configuration as JSON file
     */
    downloadConfig(filename, format = 'complete') {
        try {
            const config = this.exportConfig(format);
            const jsonString = JSON.stringify(config, null, 2);

            // Create download link
            const blob = new Blob([jsonString], { type: 'application/json' });
            const url = URL.createObjectURL(blob);

            const link = document.createElement('a');
            link.href = url;
            link.download = filename || `${config.creatureType}-${format}-${Date.now()}.json`;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);

            URL.revokeObjectURL(url);

            console.log(`✅ Downloaded configuration: ${link.download}`);

        } catch (error) {
            console.error('❌ Failed to download configuration:', error);
            alert('Failed to download configuration. Check console for details.');
        }
    }

    /**
     * Upload configuration from JSON file
     */
    uploadConfig(fileInput) {
        return new Promise((resolve, reject) => {
            const file = fileInput.files[0];
            if (!file) {
                reject(new Error('No file selected'));
                return;
            }

            const reader = new FileReader();
            reader.onload = (e) => {
                try {
                    const config = JSON.parse(e.target.result);
                    const success = this.importConfig(config);
                    resolve(success);
                } catch (error) {
                    reject(error);
                }
            };

            reader.onerror = () => reject(new Error('Failed to read file'));
            reader.readAsText(file);
        });
    }

    /**
     * Deep clone object utility
     */
    deepClone(obj) {
        if (obj === null || typeof obj !== 'object') return obj;
        if (obj instanceof Date) return new Date(obj.getTime());
        if (obj instanceof Array) return obj.map(item => this.deepClone(item));

        const cloned = {};
        for (const key in obj) {
            if (obj.hasOwnProperty(key)) {
                cloned[key] = this.deepClone(obj[key]);
            }
        }
        return cloned;
    }

    /**
     * Get configuration summary for display
     */
    getConfigSummary(config) {
        if (!config) return 'No configuration';

        return {
            type: config.creatureType,
            format: config.format || 'complete',
            chains: config.chainConfigs ? config.chainConfigs.length : 0,
            hasEditor: !!config.editorMetadata,
            hasLocomotion: !!config.locomotion,
            exportDate: config.exportDate
        };
    }
}

/**
 * Editor System for Madhuban Creature Editor
 * Main orchestrator replacing dual editor architecture
 * Provides unified, intuitive visual design interface
 */

class EditorSystem {
    constructor(builder) {
        this.builder = builder;
        this.active = false;

        // Performance monitoring
        this.performanceMonitor = {
            lastToggle: 0,
            frameSkips: 0,
            updateThrottle: 16, // ~60fps target
            lastUpdate: 0
        };

        // State management
        this.savedBuilderState = null;

        // UI containers
        this.ui = {
            toolbar: null,
            sidebar: null,
            overlay: null
        };

        // Sidebar tabs and panels
        this.sidebarTabs = {
            container: null,
            buttons: {},
            panels: {}
        };

        // Sub-components - initialize after UI setup
        this.templateSelector = null;
        this.skeletonEditor = null;
        this.propertyPanel = null;
        this.configManager = null;
        this.operationHistory = null;

        // Component initialization
        this.initializeComponents();
        this.setupUI();

        console.log('✅ EditorSystem initialized with unified architecture');
    }

    /**
     * Initialize all sub-components
     */
    initializeComponents() {
        try {
            // Initialize preserved components
            this.configManager = new ConfigManager(this.builder);
            this.operationHistory = new OperationHistory();

            // Initialize new components  
            this.templateSelector = new TemplateSelector(this, this.builder);
            this.skeletonEditor = new SkeletonEditor(this, this.builder);
            this.propertyPanel = new PropertyPanel(this, this.builder);

            // Set up component callbacks
            this.setupComponentCallbacks();

            console.log('✅ All editor components initialized');
        } catch (error) {
            console.error('❌ Failed to initialize editor components:', error);
            this.handleComponentError(error);
        }
    }

    /**
     * Setup inter-component communication
     */
    setupComponentCallbacks() {
        // Template selector callback
        if (this.templateSelector) {
            this.templateSelector.onTemplateLoaded = (templateKey, template) => {
                console.log(`🎯 Template ${templateKey} loaded`);
                this.propertyPanel.updateContext('template', { templateKey, template });
            };
        }

        // Skeleton editor callbacks would be set up here
        // Property panel callbacks would be set up here
    }

    /**
     * Create main UI containers
     */
    setupUI() {
        // Create toolbar (60px height as per spec)
        this.createToolbar();

        // Create sidebar (200px width as per spec)
        this.createSidebar();

        // Initially hidden
        this.hideUI();

        console.log('🎨 Editor UI containers created');
    }

    /**
     * Create top toolbar
     */
    createToolbar() {
        if (this.ui.toolbar) {
            this.ui.toolbar.remove();
        }

        this.ui.toolbar = createDiv();
        this.ui.toolbar.id('madhuban-editor-toolbar');
        this.ui.toolbar.position(0, 0);
        this.ui.toolbar.style(`
            width: 100vw;
            height: 60px;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            position: fixed;
            z-index: 1000;
            border-bottom: 2px solid #5a67d8;
            display: none;
            padding: 0 20px;
            box-sizing: border-box;
            box-shadow: 0 2px 8px rgba(0,0,0,0.15);
        `);

        // Toolbar content container
        const toolbarContent = createDiv();
        toolbarContent.parent(this.ui.toolbar);
        toolbarContent.style(`
            display: flex;
            align-items: center;
            justify-content: space-between;
            height: 100%;
            color: white;
        `);

        // Left side - Title and mode indicator
        const leftSection = createDiv();
        leftSection.parent(toolbarContent);
        leftSection.style('display: flex; align-items: center;');

        const title = createDiv('🎨 Madhuban Creature Editor');
        title.parent(leftSection);
        title.style(`
            font-size: 18px;
            font-weight: bold;
            margin-right: 20px;
        `);

        this.modeIndicator = createDiv('Skeleton Mode');
        this.modeIndicator.parent(leftSection);
        this.modeIndicator.style(`
            background: rgba(255,255,255,0.2);
            padding: 4px 12px;
            border-radius: 16px;
            font-size: 12px;
        `);

        // Right side - Actions and exit
        const rightSection = createDiv();
        rightSection.parent(toolbarContent);
        rightSection.style('display: flex; align-items: center; gap: 10px;');

        // Sidebar toggle button (hide/show clutter)
        this.sidebarToggleButton = createButton('☰ Panels');
        this.sidebarToggleButton.parent(rightSection);
        this.sidebarToggleButton.style(`
            background: rgba(255,255,255,0.2);
            border: 1px solid rgba(255,255,255,0.3);
            color: white;
            padding: 6px 12px;
            border-radius: 4px;
            cursor: pointer;
            font-size: 12px;
        `);
        this.sidebarToggleButton.mousePressed(() => {
            const isVisible = this.ui.sidebar?.style('display') !== 'none';
            this.ui.sidebar?.style('display', isVisible ? 'none' : 'block');
        });

        // Save button
        this.saveButton = createButton('💾 Save');
        this.saveButton.parent(rightSection);
        this.saveButton.style(`
            background: rgba(255,255,255,0.2);
            border: 1px solid rgba(255,255,255,0.3);
            color: white;
            padding: 6px 12px;
            border-radius: 4px;
            cursor: pointer;
            font-size: 12px;
        `);
        this.saveButton.mousePressed(() => this.handleSave());

        // Export button
        this.exportButton = createButton('📤 Export');
        this.exportButton.parent(rightSection);
        this.exportButton.style(`
            background: rgba(255,255,255,0.2);
            border: 1px solid rgba(255,255,255,0.3);
            color: white;
            padding: 6px 12px;
            border-radius: 4px;
            cursor: pointer;
            font-size: 12px;
        `);
        this.exportButton.mousePressed(() => this.handleExport());

        // Exit button
        this.exitButton = createButton('❌ Exit (E)');
        this.exitButton.parent(rightSection);
        this.exitButton.style(`
            background: rgba(255,100,100,0.8);
            border: 1px solid rgba(255,255,255,0.3);
            color: white;
            padding: 6px 12px;
            border-radius: 4px;
            cursor: pointer;
            font-size: 12px;
            font-weight: bold;
        `);
        this.exitButton.mousePressed(() => this.hide());
    }

    /**
     * Create left sidebar
     */
    createSidebar() {
        if (this.ui.sidebar) {
            this.ui.sidebar.remove();
        }

        this.ui.sidebar = createDiv();
        this.ui.sidebar.id('madhuban-editor-sidebar');
        this.ui.sidebar.position(0, 60); // Below toolbar
        this.ui.sidebar.style(`
            width: 200px;
            height: calc(100vh - 60px);
            background: #f8f9fa;
            position: fixed;
            z-index: 999;
            border-right: 2px solid #dee2e6;
            display: none;
            overflow-y: auto;
            padding: 0;
            box-sizing: border-box;
        `);

        // Tabs header
        this.sidebarTabs.container = createDiv();
        this.sidebarTabs.container.parent(this.ui.sidebar);
        this.sidebarTabs.container.style(`
            display: flex;
            position: sticky;
            top: 0;
            background: #ffffff;
            border-bottom: 1px solid #e2e8f0;
            z-index: 1;
        `);

        const templatesTabBtn = createButton('Templates');
        templatesTabBtn.parent(this.sidebarTabs.container);
        templatesTabBtn.style(`
            flex: 1;
            padding: 10px 8px;
            border: none;
            background: #ffffff;
            cursor: pointer;
            font-size: 12px;
            border-right: 1px solid #e2e8f0;
        `);
        const propertiesTabBtn = createButton('Properties');
        propertiesTabBtn.parent(this.sidebarTabs.container);
        propertiesTabBtn.style(`
            flex: 1;
            padding: 10px 8px;
            border: none;
            background: #f3f4f6;
            cursor: pointer;
            font-size: 12px;
        `);
        this.sidebarTabs.buttons = { templates: templatesTabBtn, properties: propertiesTabBtn };

        // Panels
        const templatesPanel = createDiv();
        templatesPanel.parent(this.ui.sidebar);
        templatesPanel.style('padding: 10px;');
        const propertiesPanel = createDiv();
        propertiesPanel.parent(this.ui.sidebar);
        propertiesPanel.style('padding: 10px; display: none;');
        this.sidebarTabs.panels = { templates: templatesPanel, properties: propertiesPanel };

        // Tab switching
        templatesTabBtn.mousePressed(() => this.switchSidebarTab('templates'));
        propertiesTabBtn.mousePressed(() => this.switchSidebarTab('properties'));

        // Initialize component UIs inside panels
        this.initializeComponentUIs();
    }

    /**
     * Initialize UI for all components
     */
    initializeComponentUIs() {
        if (!this.ui.sidebar) return;

        try {
            // Template selector in Templates panel
            if (this.templateSelector && this.sidebarTabs.panels.templates) {
                this.templateSelector.setupUI(this.sidebarTabs.panels.templates);
            }
            // Property panel in Properties panel
            if (this.propertyPanel && this.sidebarTabs.panels.properties) {
                this.propertyPanel.setupUI(this.sidebarTabs.panels.properties);
            }

            console.log('🎨 Component UIs initialized in sidebar');
        } catch (error) {
            console.error('❌ Failed to initialize component UIs:', error);
        }
    }

    /**
     * Switch sidebar tab between 'templates' and 'properties'
     */
    switchSidebarTab(tab) {
        const valid = ['templates', 'properties'];
        if (!valid.includes(tab)) return;
        const other = tab === 'templates' ? 'properties' : 'templates';

        // Panels visibility
        this.sidebarTabs.panels[tab]?.style('display', 'block');
        this.sidebarTabs.panels[other]?.style('display', 'none');

        // Button styles
        if (tab === 'templates') {
            this.sidebarTabs.buttons.templates?.style('background', '#ffffff');
            this.sidebarTabs.buttons.properties?.style('background', '#f3f4f6');
        } else {
            this.sidebarTabs.buttons.templates?.style('background', '#f3f4f6');
            this.sidebarTabs.buttons.properties?.style('background', '#ffffff');
        }
    }

    /**
     * Show editor (enter editor mode)
     * Performance target: <100ms
     */
    show() {
        const startTime = performance.now();
        console.time('editor-show');

        try {
            // Save builder state
            this.saveBuilderState();

            // Set editor active
            this.active = true;
            this.builder.editorActive = true;

            // Pause builder systems
            this.builder.pauseForEditor();

            // Show UI
            this.showUI();

            // Update mode indicator
            this.updateModeIndicator();

            // Initialize template selector with current creature
            this.initializeCurrentTemplate();

            // Record performance
            const showTime = performance.now() - startTime;
            this.performanceMonitor.lastToggle = showTime;

            console.timeEnd('editor-show');

            if (showTime > 100) {
                console.warn(`⚠️ Editor show took ${showTime.toFixed(1)}ms (target: <100ms)`);
            } else {
                console.log(`✅ Editor shown in ${showTime.toFixed(1)}ms`);
            }

        } catch (error) {
            console.error('❌ Failed to show editor:', error);
            this.handleShowError(error);
        }
    }

    /**
     * Hide editor (exit editor mode)
     */
    hide() {
        const startTime = performance.now();
        console.time('editor-hide');

        try {
            // Set editor inactive
            this.active = false;
            this.builder.editorActive = false;

            // Hide UI
            this.hideUI();

            // Restore builder state
            this.restoreBuilderState();

            // Resume builder systems
            this.builder.resumeFromEditor();

            // Clear selections
            if (this.skeletonEditor) {
                this.skeletonEditor.clearSelection();
            }

            const hideTime = performance.now() - startTime;
            console.timeEnd('editor-hide');
            console.log(`✅ Editor hidden in ${hideTime.toFixed(1)}ms`);

        } catch (error) {
            console.error('❌ Failed to hide editor:', error);
            this.handleHideError(error);
        }
    }

    /**
     * Save current builder state
     */
    saveBuilderState() {
        this.savedBuilderState = {
            locomotion: this.builder.activeLocomotion,
            renderMode: this.builder.renderMode,
            mouseTarget: {
                x: this.builder.mouseTarget.x,
                y: this.builder.mouseTarget.y
            }
        };
    }

    /**
     * Restore saved builder state
     */
    restoreBuilderState() {
        if (this.savedBuilderState) {
            this.builder.activeLocomotion = this.savedBuilderState.locomotion;
            this.builder.renderMode = this.savedBuilderState.renderMode;
            this.builder.mouseTarget.x = this.savedBuilderState.mouseTarget.x;
            this.builder.mouseTarget.y = this.savedBuilderState.mouseTarget.y;
        }
    }

    /**
     * Show all UI elements
     */
    showUI() {
        if (this.ui.toolbar) {
            this.ui.toolbar.style('display', 'block');
        }
        if (this.ui.sidebar) {
            this.ui.sidebar.style('display', 'block');
        }
    }

    /**
     * Hide all UI elements
     */
    hideUI() {
        if (this.ui.toolbar) {
            this.ui.toolbar.style('display', 'none');
        }
        if (this.ui.sidebar) {
            this.ui.sidebar.style('display', 'none');
        }
    }

    /**
     * Update mode indicator in toolbar
     */
    updateModeIndicator() {
        if (this.modeIndicator) {
            let mode = 'Skeleton Mode';
            if (this.skeletonEditor && this.skeletonEditor.ikTestMode) {
                mode = 'IK Test Mode';
            }
            this.modeIndicator.html(mode);
        }
    }

    /**
     * Initialize template selector with current creature
     */
    initializeCurrentTemplate() {
        if (this.templateSelector && this.builder.creatureType) {
            const templateMap = {
                'horse': 'horse',
                'fish': 'fish',
                'lizard': 'lizard',
                'crane': 'biped'
            };

            const templateKey = templateMap[this.builder.creatureType];
            if (templateKey) {
                this.templateSelector.selectTemplate(templateKey);
            }
        }
    }

    /**
     * Main update loop (called from sketch.js)
     */
    update() {
        if (!this.active) return;

        // Throttle expensive operations
        const now = performance.now();
        if (now - this.performanceMonitor.lastUpdate < this.performanceMonitor.updateThrottle) {
            return;
        }
        this.performanceMonitor.lastUpdate = now;

        try {
            // Update components
            if (this.skeletonEditor) {
                this.skeletonEditor.update();
            }

            // Update mode indicator
            this.updateModeIndicator();

        } catch (error) {
            console.error('❌ Editor update error:', error);
        }
    }

    /**
     * Main draw loop (called from sketch.js)
     */
    draw() {
        if (!this.active) return;

        try {
            // Draw skeleton editor overlay
            if (this.skeletonEditor) {
                this.skeletonEditor.draw();
            }

            // Draw canvas adjustment for UI
            this.drawCanvasAdjustment();

        } catch (error) {
            console.error('❌ Editor draw error:', error);
        }
    }

    /**
     * Draw canvas background adjustment for UI elements
     */
    drawCanvasAdjustment() {
        push();

        // Darken areas under UI elements
        fill(0, 0, 0, 20);
        noStroke();

        // Toolbar area
        rect(0, 0, width, 60);

        // Sidebar area
        rect(0, 60, 200, height - 60);

        pop();
    }

    /**
     * Handle mouse clicks (called from sketch.js)
     */
    handleMouseClick(mouseX, mouseY) {
        if (!this.active) return false;

        try {
            // Let skeleton editor handle canvas clicks
            if (this.skeletonEditor) {
                return this.skeletonEditor.handleMouseClick(mouseX, mouseY);
            }

        } catch (error) {
            console.error('❌ Editor mouse click error:', error);
        }

        return false;
    }

    /**
     * Handle mouse dragging (called from sketch.js if needed)
     */
    handleMouseDrag(mouseX, mouseY) {
        if (!this.active) return false;

        try {
            if (this.skeletonEditor) {
                return this.skeletonEditor.handleMouseDrag(mouseX, mouseY);
            }

        } catch (error) {
            console.error('❌ Editor mouse drag error:', error);
        }

        return false;
    }

    /**
     * Handle keyboard shortcuts
     */
    handleKeyboard(keyEvent) {
        if (!this.active) return false;

        try {
            const key = keyEvent.key ? keyEvent.key.toLowerCase() : '';

            // IK test mode toggle
            if (key === 'i' && this.skeletonEditor) {
                this.skeletonEditor.toggleIKTestMode();
                return true;
            }

            // Save shortcut
            if (keyEvent.ctrlKey && key === 's') {
                this.handleSave();
                return true;
            }

            // Export shortcut
            if (keyEvent.ctrlKey && key === 'e') {
                this.handleExport();
                return true;
            }

        } catch (error) {
            console.error('❌ Editor keyboard error:', error);
        }

        return false;
    }

    // Action handlers

    handleSave() {
        try {
            if (this.configManager) {
                const config = this.configManager.exportConfig();
                console.log('💾 Configuration saved:', config);

                // Visual feedback
                this.showNotification('Saved!', 2000);
            }
        } catch (error) {
            console.error('❌ Save failed:', error);
            this.showNotification('Save failed!', 3000, 'error');
        }
    }

    handleExport() {
        try {
            if (this.configManager) {
                this.configManager.exportToFile();
                this.showNotification('Exported!', 2000);
            }
        } catch (error) {
            console.error('❌ Export failed:', error);
            this.showNotification('Export failed!', 3000, 'error');
        }
    }

    /**
     * Show temporary notification
     */
    showNotification(message, duration = 2000, type = 'success') {
        // Simple notification system
        const notification = createDiv(message);
        notification.position(width - 200, 70);
        notification.style(`
            background: ${type === 'error' ? '#ff4757' : '#2ed573'};
            color: white;
            padding: 8px 12px;
            border-radius: 4px;
            font-size: 12px;
            z-index: 1001;
            position: fixed;
        `);

        setTimeout(() => {
            notification.remove();
        }, duration);
    }

    // Error handling

    handleComponentError(error) {
        console.error('Component initialization error, using fallback:', error);
        // Could implement fallback components here
    }

    handleShowError(error) {
        console.error('Show error, attempting recovery:', error);
        this.active = false;
        this.hideUI();
    }

    handleHideError(error) {
        console.error('Hide error, forcing cleanup:', error);
        this.active = false;
        this.hideUI();
        this.restoreBuilderState();
    }

    /**
     * Get current editor state
     */
    getState() {
        return {
            active: this.active,
            selection: this.skeletonEditor ? this.skeletonEditor.getSelection() : null,
            template: this.templateSelector ? this.templateSelector.getSelectedTemplate() : null,
            performance: this.performanceMonitor
        };
    }

    /**
     * Clean up all resources
     */
    cleanup() {
        console.log('🧹 Cleaning up EditorSystem...');

        try {
            // Hide UI
            this.hideUI();

            // Cleanup components
            if (this.templateSelector) {
                this.templateSelector.destroy();
                this.templateSelector = null;
            }

            if (this.skeletonEditor) {
                this.skeletonEditor.destroy();
                this.skeletonEditor = null;
            }

            if (this.propertyPanel) {
                this.propertyPanel.destroy();
                this.propertyPanel = null;
            }

            // Remove UI elements
            if (this.ui.toolbar) {
                this.ui.toolbar.remove();
                this.ui.toolbar = null;
            }

            if (this.ui.sidebar) {
                this.ui.sidebar.remove();
                this.ui.sidebar = null;
            }

            // Reset builder state
            this.builder.editorActive = false;

            console.log('✅ EditorSystem cleanup complete');

        } catch (error) {
            console.error('❌ Cleanup error:', error);
        }
    }

    /**
     * Destroy the editor system
     */
    destroy() {
        this.cleanup();
    }
}

/**
 * OperationHistory - Comprehensive undo/redo system for skeleton editing
 * 
 * Tracks all skeleton modifications and provides reliable state restoration
 * with memory management and performance optimization.
 */

class OperationHistory {
    constructor(builder, editor) {
        this.builder = builder;
        this.editor = editor;

        // History management
        this.operations = [];
        this.currentIndex = -1;
        this.maxHistorySize = 50;

        // Performance optimization
        this.batchingEnabled = false;
        this.batchedOperations = [];
        this.compressionThreshold = 10;

        // State management
        this.lastSaveIndex = -1;
        this.memoryUsage = 0;
        this.maxMemoryMB = 50; // 50MB limit for operation history

        console.log('🔄 OperationHistory initialized with max', this.maxHistorySize, 'operations');
    }

    /**
     * Record a new operation in the history
     * @param {string} type - Operation type (move, rotate, scale, add, delete, etc.)
     * @param {Object} data - Operation-specific data
     * @param {Object} beforeState - State before the operation
     * @param {Object} afterState - State after the operation
     */
    recordOperation(type, data, beforeState, afterState) {
        try {
            // Create operation record
            const operation = {
                id: this.generateOperationId(),
                type: type,
                timestamp: Date.now(),
                data: data,
                beforeState: this.compressState(beforeState),
                afterState: this.compressState(afterState),
                memorySize: this.calculateStateSize(beforeState) + this.calculateStateSize(afterState)
            };

            // Handle batching if enabled
            if (this.batchingEnabled) {
                this.batchedOperations.push(operation);
                return operation.id;
            }

            // Clear any operations after current index (when user made changes after undo)
            if (this.currentIndex < this.operations.length - 1) {
                this.operations.splice(this.currentIndex + 1);
            }

            // Add new operation
            this.operations.push(operation);
            this.currentIndex++;

            // Update memory usage
            this.memoryUsage += operation.memorySize;

            // Manage history size and memory
            this.manageHistorySize();

            console.log(`📝 Recorded ${type} operation:`, operation.id);
            return operation.id;

        } catch (error) {
            console.error('❌ Failed to record operation:', error);
            return null;
        }
    }

    /**
     * Undo the last operation
     */
    undo() {
        if (!this.canUndo()) {
            console.warn('⚠️ Cannot undo: no operations in history');
            return false;
        }

        try {
            const operation = this.operations[this.currentIndex];

            console.log(`↩️ Undoing ${operation.type} operation:`, operation.id);

            // Restore previous state
            this.restoreState(operation.beforeState);

            // Move index backwards
            this.currentIndex--;

            // Update UI
            this.updateUndoRedoUI();

            return true;

        } catch (error) {
            console.error('❌ Failed to undo operation:', error);
            return false;
        }
    }

    /**
     * Redo the next operation
     */
    redo() {
        if (!this.canRedo()) {
            console.warn('⚠️ Cannot redo: no forward operations available');
            return false;
        }

        try {
            // Move index forward first
            this.currentIndex++;
            const operation = this.operations[this.currentIndex];

            console.log(`↪️ Redoing ${operation.type} operation:`, operation.id);

            // Restore next state
            this.restoreState(operation.afterState);

            // Update UI
            this.updateUndoRedoUI();

            return true;

        } catch (error) {
            console.error('❌ Failed to redo operation:', error);
            this.currentIndex--; // Restore index on failure
            return false;
        }
    }

    /**
     * Check if undo is possible
     */
    canUndo() {
        return this.currentIndex >= 0;
    }

    /**
     * Check if redo is possible
     */
    canRedo() {
        return this.currentIndex < this.operations.length - 1;
    }

    /**
     * Start batching operations for compound actions
     */
    startBatch(batchName = 'Compound Operation') {
        this.batchingEnabled = true;
        this.batchedOperations = [];
        this.currentBatchName = batchName;
        console.log(`🔄 Started operation batch: ${batchName}`);
    }

    /**
     * End batching and record as single compound operation
     */
    endBatch() {
        if (!this.batchingEnabled || this.batchedOperations.length === 0) {
            this.batchingEnabled = false;
            return null;
        }

        try {
            // Create compound operation
            const compoundOperation = {
                id: this.generateOperationId(),
                type: 'compound',
                name: this.currentBatchName,
                timestamp: Date.now(),
                operations: [...this.batchedOperations],
                beforeState: this.batchedOperations[0].beforeState,
                afterState: this.batchedOperations[this.batchedOperations.length - 1].afterState,
                memorySize: this.batchedOperations.reduce((sum, op) => sum + op.memorySize, 0)
            };

            // Add to history
            if (this.currentIndex < this.operations.length - 1) {
                this.operations.splice(this.currentIndex + 1);
            }

            this.operations.push(compoundOperation);
            this.currentIndex++;
            this.memoryUsage += compoundOperation.memorySize;

            // Cleanup
            this.batchingEnabled = false;
            this.batchedOperations = [];
            this.currentBatchName = null;

            this.manageHistorySize();

            console.log(`📦 Recorded compound operation: ${compoundOperation.name}`, compoundOperation.id);
            return compoundOperation.id;

        } catch (error) {
            console.error('❌ Failed to create compound operation:', error);
            this.batchingEnabled = false;
            this.batchedOperations = [];
            return null;
        }
    }

    /**
     * Capture current state of the builder for restoration
     */
    captureState() {
        try {
            const state = {
                chains: [],
                chainConfigs: [...this.builder.chainConfigs],
                creatureType: this.builder.creatureType,
                bodyPosition: {
                    x: this.builder.bodyPosition.x,
                    y: this.builder.bodyPosition.y
                },
                renderMode: this.builder.renderMode
            };

            // Capture chain states with bone positions
            this.builder.chains.forEach((chain, index) => {
                const chainState = {
                    bones: [],
                    baseMode: chain.getFixedBaseMode ? chain.getFixedBaseMode() : 'fixed'
                };

                for (let i = 0; i < chain.numBones; i++) {
                    const bone = chain.bones[i];
                    chainState.bones.push({
                        startX: bone.start.x,
                        startY: bone.start.y,
                        endX: bone.end.x,
                        endY: bone.end.y,
                        length: bone.getLength(),
                        constraints: bone.joint ? {
                            clockwise: bone.joint.clockwiseConstraintDegs,
                            anticlockwise: bone.joint.anticlockwiseConstraintDegs
                        } : null
                    });
                }

                state.chains.push(chainState);
            });

            return state;

        } catch (error) {
            console.error('❌ Failed to capture state:', error);
            return null;
        }
    }

    /**
     * Restore builder state from captured data
     */
    restoreState(state) {
        if (!state) {
            console.error('❌ Cannot restore: invalid state data');
            return false;
        }

        try {
            // Restore basic properties
            this.builder.creatureType = state.creatureType;
            this.builder.renderMode = state.renderMode;
            this.builder.bodyPosition.set(state.bodyPosition.x, state.bodyPosition.y);

            // Clear current chains
            this.builder.chains = [];
            this.builder.chainConfigs = [...state.chainConfigs];

            // Restore chains
            state.chains.forEach((chainState, index) => {
                if (index < state.chainConfigs.length) {
                    const config = state.chainConfigs[index];

                    // Recreate chain using builder
                    const newChain = this.builder.createChainFromConfig({
                        role: config.role,
                        type: config.type,
                        bones: chainState.bones.map(bone => ({
                            length: bone.length,
                            constraints: bone.constraints
                        })),
                        attachment: config.attachment,
                        parentChainIndex: config.parentChainIndex,
                        attachmentIndex: config.attachmentIndex
                    });

                    // Restore bone positions
                    if (newChain && chainState.bones.length > 0) {
                        chainState.bones.forEach((boneState, boneIndex) => {
                            if (boneIndex < newChain.numBones) {
                                const bone = newChain.bones[boneIndex];
                                bone.start.set(boneState.startX, boneState.startY);
                                bone.end.set(boneState.endX, boneState.endY);
                            }
                        });
                    }
                }
            });

            // Clear editor selection
            this.editor.clearSelection();
            this.editor.updateSidebar();

            console.log('✅ State restored successfully');
            return true;

        } catch (error) {
            console.error('❌ Failed to restore state:', error);
            return false;
        }
    }

    /**
     * Compress state data to reduce memory usage
     */
    compressState(state) {
        if (!state) return null;

        // For now, just return the state as-is
        // Future enhancement: implement JSON compression
        return state;
    }

    /**
     * Calculate approximate memory size of state data
     */
    calculateStateSize(state) {
        if (!state) return 0;

        try {
            return JSON.stringify(state).length * 2; // Rough estimate in bytes
        } catch (error) {
            return 1000; // Default estimate
        }
    }

    /**
     * Manage history size to prevent memory overflow
     */
    manageHistorySize() {
        // Remove oldest operations if exceeding limits
        while (this.operations.length > this.maxHistorySize || 
               this.memoryUsage > this.maxMemoryMB * 1024 * 1024) {

            if (this.operations.length === 0) break;

            const removedOp = this.operations.shift();
            this.memoryUsage -= removedOp.memorySize;
            this.currentIndex--;

            if (this.lastSaveIndex >= 0) {
                this.lastSaveIndex--;
            }
        }
    }

    /**
     * Generate unique operation ID
     */
    generateOperationId() {
        return `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    }

    /**
     * Update undo/redo UI controls
     */
    updateUndoRedoUI() {
        // This will be called to update UI button states
        // Implementation depends on how UI is structured
        if (this.editor && this.editor.sidebarUI) {
            this.editor.sidebarUI.updateAll();
        }
    }

    /**
     * Clear all history
     */
    clearHistory() {
        this.operations = [];
        this.currentIndex = -1;
        this.memoryUsage = 0;
        this.lastSaveIndex = -1;

        console.log('🗑️ Operation history cleared');
    }

    /**
     * Get history status for debugging
     */
    getStatus() {
        return {
            operationCount: this.operations.length,
            currentIndex: this.currentIndex,
            memoryUsageMB: (this.memoryUsage / (1024 * 1024)).toFixed(2),
            canUndo: this.canUndo(),
            canRedo: this.canRedo(),
            batchingEnabled: this.batchingEnabled
        };
    }

    /**
     * Cleanup resources
     */
    cleanup() {
        this.clearHistory();
        this.builder = null;
        this.editor = null;

        console.log('🧹 OperationHistory cleaned up');
    }
}

/**
 * Property Panel for Madhuban Creature Editor
 * Context-sensitive property editing interface with progressive disclosure
 */

class PropertyPanel {
    constructor(editorSystem, builder) {
        this.editorSystem = editorSystem;
        this.builder = builder;
        this.container = null;

        // Current context and data
        this.currentContext = 'none'; // 'none', 'chain', 'bone', 'template'
        this.currentData = null;

        // UI component references
        this.sections = {};
        this.controls = {};

        // Update throttling
        this.updateThrottle = 50; // 20fps for property updates
        this.lastUpdate = 0;

        console.log('PropertyPanel initialized');
    }

    /**
     * Setup the property panel UI
     * @param {p5.Element} parent - Parent container
     */
    setupUI(parent) {
        // Create main container
        this.container = createDiv();
        this.container.parent(parent);
        this.container.class('property-panel');
        this.container.style(`
            padding: 12px;
            background: #f9f9f9;
            border-radius: 6px;
            border: 1px solid #ddd;
            max-height: calc(100vh - 200px);
            overflow-y: auto;
        `);

        // Create header
        this.header = createDiv('Properties');
        this.header.parent(this.container);
        this.header.style(`
            font-weight: bold;
            font-size: 14px;
            margin-bottom: 12px;
            color: #333;
        `);

        // Create content area
        this.contentArea = createDiv();
        this.contentArea.parent(this.container);
        this.contentArea.class('property-content');

        // Initialize with default content
        this.updateContext('none', {});
    }

    /**
     * Update the property panel context based on current selection
     * @param {string} type - Context type: 'none', 'chain', 'bone', 'template'
     * @param {Object} data - Context-specific data
     */
    updateContext(type, data) {
        // Throttle updates for performance
        const now = performance.now();
        if (now - this.lastUpdate < this.updateThrottle) {
            return;
        }
        this.lastUpdate = now;

        // Clear previous content
        this.clearContent();

        // Store current context
        this.currentContext = type;
        this.currentData = data;

        // Create context-specific content
        switch (type) {
            case 'template':
                this.showTemplateProperties();
                break;
            case 'chain':
                this.showChainProperties(data);
                break;
            case 'bone':
                this.showBoneProperties(data);
                break;
            case 'none':
            default:
                this.showDefaultProperties();
                break;
        }
    }

    /**
     * Clear all property content
     */
    clearContent() {
        // Destroy existing sections and controls
        Object.values(this.sections).forEach(section => {
            if (section && section.destroy) {
                section.destroy();
            }
        });

        Object.values(this.controls).forEach(control => {
            if (control && control.destroy) {
                control.destroy();
            }
        });

        this.sections = {};
        this.controls = {};

        // Clear content area
        if (this.contentArea) {
            this.contentArea.html('');
        }
    }

    /**
     * Show default properties when nothing is selected
     */
    showDefaultProperties() {
        // Template selection section
        this.sections.templates = new CollapsibleSection(this.contentArea, 'Templates', true);

        const templateContent = `
            <div style="text-align: center; padding: 16px;">
                <div style="font-size: 12px; color: #666; margin-bottom: 12px;">
                    Select a template or click on skeleton elements to edit properties
                </div>
            </div>
        `;
        this.sections.templates.setContent(templateContent);

        // General settings section
        this.sections.general = new CollapsibleSection(this.contentArea, 'General Settings', false);
        this.createGeneralSettings();

        // Help section
        this.sections.help = new CollapsibleSection(this.contentArea, 'Help', false);
        this.createHelpContent();
    }

    /**
     * Show template-specific properties
     */
    showTemplateProperties() {
        // Template info section
        this.sections.templateInfo = new CollapsibleSection(this.contentArea, 'Template Info', true);

        const selectedTemplate = this.editorSystem.templateSelector?.getSelectedTemplate();
        if (selectedTemplate) {
            const templateInfo = this.editorSystem.templateSelector.getTemplateInfo(selectedTemplate);
            const content = `
                <div style="font-size: 12px;">
                    <div style="margin-bottom: 8px;">
                        <strong>${templateInfo.name}</strong>
                        <span style="float: right; font-size: 18px;">${templateInfo.preview}</span>
                    </div>
                    <div style="color: #666; margin-bottom: 8px;">${templateInfo.description}</div>
                    <div style="background: #f0f0f0; padding: 8px; border-radius: 4px; font-family: monospace; font-size: 10px;">
                        <div><strong>FORCE Parameters:</strong></div>
                        ${Object.entries(templateInfo.forceParams).map(([key, value]) => 
                            `<div>${key}: ${value}</div>`
                        ).join('')}
                    </div>
                </div>
            `;
            this.sections.templateInfo.setContent(content);
        }

        // Template actions
        this.sections.templateActions = new CollapsibleSection(this.contentArea, 'Template Actions', true);
        this.createTemplateActions();
    }

    /**
     * Show chain-specific properties
     * @param {Object} data - Chain data {chainIndex, chain}
     */
    showChainProperties(data) {
        if (!data.chain || data.chainIndex === undefined) return;

        const chainConfig = this.builder.chainConfigs[data.chainIndex];
        const chain = data.chain;

        // Chain info section
        this.sections.chainInfo = new CollapsibleSection(this.contentArea, 'Chain Information', true);
        const chainInfoContent = `
            <div style="font-size: 12px;">
                <div><strong>Chain Index:</strong> ${data.chainIndex}</div>
                <div><strong>Role:</strong> ${chainConfig?.role || 'unknown'}</div>
                <div><strong>Type:</strong> ${chainConfig?.type || 'unknown'}</div>
                <div><strong>Bones:</strong> ${chain.getNumBones()}</div>
                <div><strong>Attachment:</strong> ${chainConfig?.attachment || 'unknown'}</div>
            </div>
        `;
        this.sections.chainInfo.setContent(chainInfoContent);

        // Chain properties section
        this.sections.chainProps = new CollapsibleSection(this.contentArea, 'Chain Properties', true);
        this.createChainControls(data.chainIndex, chainConfig);

        // IK controls section
        this.sections.ikControls = new CollapsibleSection(this.contentArea, 'IK Controls', false);
        this.createIKControls(data.chainIndex);
    }

    /**
     * Show bone-specific properties
     * @param {Object} data - Bone data {chainIndex, boneIndex, bone}
     */
    showBoneProperties(data) {
        if (!data.bone || data.chainIndex === undefined || data.boneIndex === undefined) return;

        const bone = data.bone;
        const start = bone.getStartLocation();
        const end = bone.getEndLocation();
        const length = Math.sqrt(Math.pow(end.x - start.x, 2) + Math.pow(end.y - start.y, 2));
        const angle = Math.atan2(end.y - start.y, end.x - start.x) * 180 / Math.PI;

        // Bone info section
        this.sections.boneInfo = new CollapsibleSection(this.contentArea, 'Bone Information', true);
        const boneInfoContent = `
            <div style="font-size: 12px;">
                <div><strong>Chain:</strong> ${data.chainIndex}</div>
                <div><strong>Bone:</strong> ${data.boneIndex}</div>
                <div><strong>Length:</strong> ${length.toFixed(1)}px</div>
                <div><strong>Angle:</strong> ${angle.toFixed(1)}°</div>
                <div><strong>Start:</strong> (${start.x.toFixed(1)}, ${start.y.toFixed(1)})</div>
                <div><strong>End:</strong> (${end.x.toFixed(1)}, ${end.y.toFixed(1)})</div>
            </div>
        `;
        this.sections.boneInfo.setContent(boneInfoContent);

        // Bone properties section
        this.sections.boneProps = new CollapsibleSection(this.contentArea, 'Bone Properties', true);
        this.createBoneControls(data.chainIndex, data.boneIndex, bone);

        // Constraints section
        this.sections.constraints = new CollapsibleSection(this.contentArea, 'Constraints', false);
        this.createConstraintControls(data.chainIndex, data.boneIndex);
    }

    /**
     * Create general settings controls
     */
    createGeneralSettings() {
        const settingsContainer = createDiv();
        settingsContainer.parent(this.sections.general.contentDiv);

        // Render mode controls
        this.controls.renderMode = new IconButton(
            settingsContainer,
            'Toggle Render Mode',
            () => this.builder.switchRenderMode(),
            '👁️'
        );

        // Debug toggle
        this.controls.debugToggle = new IconButton(
            settingsContainer,
            'Toggle Debug',
            () => {
                this.builder.showDebug = !this.builder.showDebug;
                this.controls.debugToggle.setText(`Debug: ${this.builder.showDebug ? 'ON' : 'OFF'}`);
            },
            '🔧'
        );

        // Performance info
        const perfInfo = createDiv('Performance: 60fps target');
        perfInfo.parent(settingsContainer);
        perfInfo.style('font-size: 10px; color: #666; margin-top: 8px;');
    }

    /**
     * Create template action controls
     */
    createTemplateActions() {
        const actionsContainer = createDiv();
        actionsContainer.parent(this.sections.templateActions.contentDiv);

        // Save template
        this.controls.saveTemplate = new IconButton(
            actionsContainer,
            'Save Current',
            () => {
                if (this.editorSystem.templateSelector) {
                    this.editorSystem.templateSelector.saveCurrentAsTemplate();
                }
            },
            '💾'
        );

        // Export config
        this.controls.exportConfig = new IconButton(
            actionsContainer,
            'Export JSON',
            () => {
                if (this.editorSystem.configManager) {
                    this.editorSystem.configManager.exportToFile();
                }
            },
            '📤'
        );
    }

    /**
     * Create chain control sliders and buttons
     */
    createChainControls(chainIndex, chainConfig) {
        const controlsContainer = createDiv();
        controlsContainer.parent(this.sections.chainProps.contentDiv);

        // Chain color picker (simplified)
        const colorInfo = createDiv(`Color: ${this.getChainColorName(chainConfig?.role)}`);
        colorInfo.parent(controlsContainer);
        colorInfo.style('font-size: 12px; margin-bottom: 8px;');

        // IK Test button
        this.controls.ikTest = new IconButton(
            controlsContainer,
            'IK Test Mode',
            () => {
                if (this.editorSystem.skeletonEditor) {
                    this.editorSystem.skeletonEditor.toggleIKTestMode();
                    const isActive = this.editorSystem.skeletonEditor.ikTestMode;
                    this.controls.ikTest.setText(`IK Test: ${isActive ? 'ON' : 'OFF'}`);
                }
            },
            '🎯'
        );

        // Chain manipulation buttons
        this.controls.addBone = new IconButton(
            controlsContainer,
            'Add Bone',
            () => this.addBoneToChain(chainIndex),
            '➕'
        );

        this.controls.removeBone = new IconButton(
            controlsContainer,
            'Remove Bone',
            () => this.removeBoneFromChain(chainIndex),
            '➖'
        );
    }

    /**
     * Create bone control sliders
     */
    createBoneControls(chainIndex, boneIndex, bone) {
        const controlsContainer = createDiv();
        controlsContainer.parent(this.sections.boneProps.contentDiv);

        const start = bone.getStartLocation();
        const end = bone.getEndLocation();
        const currentLength = Math.sqrt(Math.pow(end.x - start.x, 2) + Math.pow(end.y - start.y, 2));
        const currentAngle = Math.atan2(end.y - start.y, end.x - start.x) * 180 / Math.PI;

        // Length slider
        this.controls.lengthSlider = new PropertySlider(
            controlsContainer,
            'Length',
            10, 100,
            currentLength,
            (value) => this.updateBoneLength(chainIndex, boneIndex, value)
        );

        // Angle slider
        this.controls.angleSlider = new PropertySlider(
            controlsContainer,
            'Angle',
            -180, 180,
            currentAngle,
            (value) => this.updateBoneAngle(chainIndex, boneIndex, value)
        );
    }

    /**
     * Create IK control buttons
     */
    createIKControls(chainIndex) {
        const ikContainer = createDiv();
        ikContainer.parent(this.sections.ikControls.contentDiv);

        // Solve IK button
        this.controls.solveIK = new IconButton(
            ikContainer,
            'Solve IK',
            () => this.solveIKForChain(chainIndex),
            '🎯'
        );

        // Reset pose button
        this.controls.resetPose = new IconButton(
            ikContainer,
            'Reset Pose',
            () => this.resetChainPose(chainIndex),
            '🔄'
        );
    }

    /**
     * Create constraint control sliders
     */
    createConstraintControls(chainIndex, boneIndex) {
        const constraintContainer = createDiv();
        constraintContainer.parent(this.sections.constraints.contentDiv);

        // Constraint info
        const info = createDiv('Constraint controls would go here');
        info.parent(constraintContainer);
        info.style('font-size: 11px; color: #666; text-align: center; padding: 16px;');
    }

    /**
     * Create help content
     */
    createHelpContent() {
        const helpContent = `
            <div style="font-size: 11px; color: #666;">
                <div style="margin-bottom: 8px;"><strong>Keyboard Shortcuts:</strong></div>
                <div>E - Toggle Editor</div>
                <div>I - IK Test Mode</div>
                <div>Shift+Click - Select Chain</div>
                <div>Click - Select Bone</div>
                <div style="margin-top: 8px;"><strong>Mouse:</strong></div>
                <div>Click - Select element</div>
                <div>Drag - Manipulate (IK mode)</div>
            </div>
        `;
        this.sections.help.setContent(helpContent);
    }

    // Property manipulation methods

    updateBoneLength(chainIndex, boneIndex, newLength) {
        console.log(`Updating bone ${boneIndex} in chain ${chainIndex} length to ${newLength}`);
        // Implementation would depend on FIK.js bone structure
    }

    updateBoneAngle(chainIndex, boneIndex, newAngle) {
        console.log(`Updating bone ${boneIndex} in chain ${chainIndex} angle to ${newAngle}°`);
        // Implementation would depend on FIK.js bone structure
    }

    addBoneToChain(chainIndex) {
        console.log(`Adding bone to chain ${chainIndex}`);
        // Implementation would add bone to FIK.js chain
    }

    removeBoneFromChain(chainIndex) {
        console.log(`Removing bone from chain ${chainIndex}`);
        // Implementation would remove bone from FIK.js chain
    }

    solveIKForChain(chainIndex) {
        if (this.editorSystem.skeletonEditor) {
            this.editorSystem.skeletonEditor.solveIKForChain(chainIndex);
        }
    }

    resetChainPose(chainIndex) {
        console.log(`Resetting pose for chain ${chainIndex}`);
        // Implementation would reset chain to default pose
    }

    getChainColorName(role) {
        const colorMap = {
            'spine': 'Blue',
            'leg': 'Red',
            'neck': 'Green',
            'tail': 'Yellow',
            'fin': 'Magenta',
            'wing': 'Orange'
        };
        return colorMap[role] || 'Gray';
    }

    /**
     * Get current context information
     */
    getCurrentContext() {
        return {
            type: this.currentContext,
            data: this.currentData
        };
    }

    /**
     * Show/hide the property panel
     */
    show() {
        if (this.container) {
            this.container.style('display', 'block');
        }
    }

    hide() {
        if (this.container) {
            this.container.style('display', 'none');
        }
    }

    /**
     * Clean up resources
     */
    destroy() {
        this.clearContent();

        if (this.container) {
            this.container.remove();
            this.container = null;
            this.contentArea = null;
            this.header = null;
        }

        console.log('PropertyPanel destroyed');
    }
}

/**
 * Skeleton Editor for Madhuban Creature Editor
 * Core skeleton editing with simplified click-to-select interaction
 */

class SkeletonEditor {
    constructor(editorSystem, builder) {
        this.editorSystem = editorSystem;
        this.builder = builder;

        // Selection state
        this.selectedChain = null;
        this.selectedBone = null;
        this.selectionMode = 'chain'; // 'chain' or 'bone'

        // Visual highlighting
        this.highlighter = new SelectionHighlight();

        // IK test mode
        this.ikTestMode = false;
        this.ikTestPose = null;

        // Performance settings
        this.updateThrottle = 33; // 30fps target for expensive operations
        this.selectionThreshold = 15; // pixels
        this.lastUpdate = 0;
        this.lastIKUpdate = 0;

        // Interaction state
        this.dragging = false;
        this.dragStartPos = null;
        this.dragTarget = null;

        console.log('SkeletonEditor initialized');
    }

    /**
     * Handle mouse click for chain/bone selection
     * @param {number} mouseX - Mouse X coordinate
     * @param {number} mouseY - Mouse Y coordinate
     * @returns {boolean} - True if click was handled
     */
    handleMouseClick(mouseX, mouseY) {
        const startTime = performance.now();

        // Check if click is in canvas area (not on UI)
        if (mouseX < 250 || mouseY < 60) {
            return false;
        }

        let bestMatch = null;
        let bestDistance = Infinity;

        // Find closest chain/bone to click
        for (let chainIndex = 0; chainIndex < this.builder.chains.length; chainIndex++) {
            const chain = this.builder.chains[chainIndex];

            for (let boneIndex = 0; boneIndex < chain.bones.length; boneIndex++) {
                const bone = chain.bones(boneIndex);
                const start = bone.getStartLocation();
                const end = bone.getEndLocation();

                // Calculate distance from click to bone
                const distance = this.pointToLineDistance(
                    mouseX, mouseY,
                    start.x, start.y,
                    end.x, end.y
                );

                if (distance < this.selectionThreshold && distance < bestDistance) {
                    bestMatch = {
                        chainIndex: chainIndex,
                        boneIndex: boneIndex,
                        bone: bone,
                        distance: distance
                    };
                    bestDistance = distance;
                }
            }
        }

        // Update selection based on best match
        if (bestMatch) {
            this.selectElement(bestMatch.chainIndex, bestMatch.boneIndex);

            // Notify property panel of selection change
            if (this.editorSystem.propertyPanel) {
                if (this.selectionMode === 'bone') {
                    this.editorSystem.propertyPanel.updateContext('bone', {
                        chainIndex: bestMatch.chainIndex,
                        boneIndex: bestMatch.boneIndex,
                        bone: bestMatch.bone
                    });
                } else {
                    this.editorSystem.propertyPanel.updateContext('chain', {
                        chainIndex: bestMatch.chainIndex,
                        chain: this.builder.chains[bestMatch.chainIndex]
                    });
                }
            }
        } else {
            this.clearSelection();

            // Notify property panel of cleared selection
            if (this.editorSystem.propertyPanel) {
                this.editorSystem.propertyPanel.updateContext('none', {});
            }
        }

        // Performance monitoring
        const selectionTime = performance.now() - startTime;
        if (selectionTime > 50) {
            console.warn(`Skeleton selection took ${selectionTime.toFixed(1)}ms`);
        }

        return bestMatch !== null;
    }

    /**
     * Select a chain or bone element
     * @param {number} chainIndex - Index of the chain
     * @param {number} boneIndex - Index of the bone (optional)
     */
    selectElement(chainIndex, boneIndex = null) {
        // Determine selection mode based on modifier keys
        this.selectionMode = (keyIsDown(SHIFT) || boneIndex === null) ? 'chain' : 'bone';

        this.selectedChain = chainIndex;
        this.selectedBone = boneIndex;

        // Update visual highlighting
        if (this.selectionMode === 'bone' && boneIndex !== null) {
            this.highlighter.highlightBone(chainIndex, boneIndex);
            console.log(`Selected bone ${boneIndex} in chain ${chainIndex}`);
        } else {
            this.highlighter.highlightChain(chainIndex);
            this.selectedBone = null; // Clear bone selection when selecting chain
            console.log(`Selected chain ${chainIndex}`);
        }
    }

    /**
     * Clear current selection
     */
    clearSelection() {
        this.selectedChain = null;
        this.selectedBone = null;
        this.highlighter.clear();
        console.log('Selection cleared');
    }

    /**
     * Toggle IK test mode
     */
    toggleIKTestMode() {
        this.ikTestMode = !this.ikTestMode;

        if (this.ikTestMode) {
            console.log('🎯 IK Test Mode: ON - Click and drag to test poses');
            this.ikTestPose = this.saveCurrentPose();
        } else {
            console.log('🎯 IK Test Mode: OFF');
            if (this.ikTestPose) {
                this.restorePose(this.ikTestPose);
                this.ikTestPose = null;
            }
        }
    }

    /**
     * Handle mouse dragging for bone manipulation
     * @param {number} mouseX - Current mouse X
     * @param {number} mouseY - Current mouse Y
     * @returns {boolean} - True if drag was handled
     */
    handleMouseDrag(mouseX, mouseY) {
        if (!this.dragging || !this.dragTarget) {
            return false;
        }

        // Throttle drag updates for performance
        const now = performance.now();
        if (now - this.lastUpdate < this.updateThrottle) {
            return true;
        }
        this.lastUpdate = now;

        // Calculate drag delta
        const deltaX = mouseX - this.dragStartPos.x;
        const deltaY = mouseY - this.dragStartPos.y;

        // Apply drag based on target type
        if (this.dragTarget.type === 'bone_end') {
            this.dragBoneEnd(this.dragTarget.chainIndex, this.dragTarget.boneIndex, deltaX, deltaY);
        } else if (this.dragTarget.type === 'chain_tip') {
            this.dragChainTip(this.dragTarget.chainIndex, deltaX, deltaY);
        }

        return true;
    }

    /**
     * Start dragging interaction
     */
    startDrag(mouseX, mouseY) {
        if (this.selectedChain === null) return false;

        this.dragging = true;
        this.dragStartPos = { x: mouseX, y: mouseY };

        // Determine drag target based on selection
        if (this.selectedBone !== null) {
            this.dragTarget = {
                type: 'bone_end',
                chainIndex: this.selectedChain,
                boneIndex: this.selectedBone
            };
        } else {
            this.dragTarget = {
                type: 'chain_tip',
                chainIndex: this.selectedChain
            };
        }

        return true;
    }

    /**
     * Stop dragging interaction
     */
    stopDrag() {
        this.dragging = false;
        this.dragStartPos = null;
        this.dragTarget = null;
    }

    /**
     * Drag individual bone end
     */
    dragBoneEnd(chainIndex, boneIndex, deltaX, deltaY) {
        // This would modify bone length/angle based on drag
        // Implementation depends on FIK.js bone structure
        console.log(`Dragging bone ${boneIndex} in chain ${chainIndex}: ${deltaX}, ${deltaY}`);
    }

    /**
     * Drag chain tip (for IK solving)
     */
    dragChainTip(chainIndex, deltaX, deltaY) {
        if (chainIndex >= this.builder.chains.length) return;

        const chain = this.builder.chains[chainIndex];
        const currentTarget = this.builder.mouseTarget;

        // Update IK target based on drag
        this.builder.mouseTarget.x = currentTarget.x + deltaX;
        this.builder.mouseTarget.y = currentTarget.y + deltaY;

        // Solve IK if in test mode
        if (this.ikTestMode) {
            this.solveIKForChain(chainIndex);
        }
    }

    /**
     * Solve IK for specific chain
     */
    solveIKForChain(chainIndex) {
        // Throttle IK solving for performance
        const now = performance.now();
        if (now - this.lastIKUpdate < this.updateThrottle) {
            return;
        }
        this.lastIKUpdate = now;

        if (chainIndex >= this.builder.chains.length) return;

        const chain = this.builder.chains[chainIndex];
        try {
            chain.solveForTarget(this.builder.mouseTarget);
        } catch (error) {
            console.warn('IK solve failed:', error);
        }
    }

    /**
     * Save current pose for IK testing
     */
    saveCurrentPose() {
        const pose = {};
        this.builder.chains.forEach((chain, index) => {
            const chainPose = [];
            for (let i = 0; i < chain.bones.length(); i++) {
                const bone = chain.bones(i);
                const start = bone.getStartLocation();
                const end = bone.getEndLocation();
                chainPose.push({
                    start: { x: start.x, y: start.y },
                    end: { x: end.x, y: end.y }
                });
            }
            pose[index] = chainPose;
        });
        return pose;
    }

    /**
     * Restore saved pose
     */
    restorePose(pose) {
        // This would restore the saved pose
        // Implementation depends on FIK.js chain structure
        console.log('Restoring pose:', pose);
    }

    /**
     * Calculate point-to-line distance for selection
     */
    pointToLineDistance(px, py, x1, y1, x2, y2) {
        const A = px - x1;
        const B = py - y1;
        const C = x2 - x1;
        const D = y2 - y1;

        const dot = A * C + B * D;
        const lenSq = C * C + D * D;

        if (lenSq === 0) return Math.sqrt(A * A + B * B);

        let param = dot / lenSq;
        param = Math.max(0, Math.min(1, param)); // Constrain to line segment

        const xx = x1 + param * C;
        const yy = y1 + param * D;

        return Math.sqrt((px - xx) * (px - xx) + (py - yy) * (py - yy));
    }

    /**
     * Update skeleton editor (called from main update loop)
     */
    update() {
        // Throttle expensive operations
        const now = performance.now();
        if (now - this.lastUpdate < this.updateThrottle) {
            return;
        }
        this.lastUpdate = now;

        // Update IK test mode if active
        if (this.ikTestMode && this.selectedChain !== null) {
            this.solveIKForChain(this.selectedChain);
        }
    }

    /**
     * Draw skeleton editor overlay
     */
    draw() {
        if (!this.builder.chains || this.builder.chains.length === 0) {
            return;
        }

        // Draw selection highlighting
        this.highlighter.draw(this.builder.chains);

        // Draw IK test mode indicators
        if (this.ikTestMode) {
            this.drawIKTestIndicators();
        }

        // Draw editing grid
        this.drawEditingGrid();
    }

    /**
     * Draw IK test mode visual indicators
     */
    drawIKTestIndicators() {
        push();

        // Draw IK target
        fill(255, 100, 100, 150);
        noStroke();
        circle(this.builder.mouseTarget.x, this.builder.mouseTarget.y, 12);

        // Draw target crosshairs
        stroke(255, 100, 100);
        strokeWeight(2);
        const size = 8;
        line(this.builder.mouseTarget.x - size, this.builder.mouseTarget.y, 
             this.builder.mouseTarget.x + size, this.builder.mouseTarget.y);
        line(this.builder.mouseTarget.x, this.builder.mouseTarget.y - size, 
             this.builder.mouseTarget.x, this.builder.mouseTarget.y + size);

        // Draw mode indicator
        fill(255, 100, 100);
        noStroke();
        textAlign(RIGHT, TOP);
        textSize(12);
        text('IK TEST MODE', width - 10, 70);

        pop();
    }

    /**
     * Draw editing grid for positioning
     */
    drawEditingGrid() {
        push();
        stroke(200, 200, 200, 50);
        strokeWeight(1);

        const gridSize = 20;
        const startX = 250; // After sidebar
        const startY = 60;  // After toolbar

        // Vertical lines
        for (let x = startX; x < width; x += gridSize) {
            line(x, startY, x, height);
        }

        // Horizontal lines
        for (let y = startY; y < height; y += gridSize) {
            line(startX, y, width, y);
        }

        pop();
    }

    /**
     * Get current selection info
     */
    getSelection() {
        return {
            mode: this.selectionMode,
            chainIndex: this.selectedChain,
            boneIndex: this.selectedBone,
            ikTestMode: this.ikTestMode
        };
    }

    /**
     * Set selection programmatically
     */
    setSelection(chainIndex, boneIndex = null) {
        this.selectElement(chainIndex, boneIndex);
    }

    /**
     * Get chain/bone count for validation
     */
    getChainCount() {
        return this.builder.chains ? this.builder.chains.length : 0;
    }

    getBoneCount(chainIndex) {
        if (!this.builder.chains || chainIndex >= this.builder.chains.length) {
            return 0;
        }
        return this.builder.chains[chainIndex].bones.length;
    }

    /**
     * Clean up resources
     */
    destroy() {
        this.clearSelection();
        this.highlighter = null;
        this.ikTestPose = null;
        this.dragTarget = null;
        console.log('SkeletonEditor destroyed');
    }
}

/**
 * Template Selector for Madhuban Creature Editor
 * Simple template selection interface with visual previews
 */

class TemplateSelector {
    constructor(editorSystem, builder) {
        this.editorSystem = editorSystem;
        this.builder = builder;
        this.container = null;
        this.selectedTemplate = null;

        // Template definitions with FORCE parameters
        this.templates = {
            'horse': {
                name: 'Horse',
                preview: '🐎',
                description: 'Erect quadruped with rigid spine',
                buildMethod: 'buildHorse',
                forceParams: {
                    rhythm: 'gallop',
                    asymmetry: 0.8,
                    thirds: [0.33, 0.66],
                    posture: 'erect'
                }
            },
            'fish': {
                name: 'Fish',
                preview: '🐟',
                description: 'Undulating spine with fluid motion',
                buildMethod: 'buildFish',
                forceParams: {
                    rhythm: 'undulate',
                    asymmetry: 0.9,
                    thirds: [0.25, 0.75],
                    posture: 'fluid'
                }
            },
            'lizard': {
                name: 'Lizard',
                preview: '🦎',
                description: 'Sprawling quadruped with lateral sway',
                buildMethod: 'buildLizard',
                forceParams: {
                    rhythm: 'crawl',
                    asymmetry: 0.7,
                    thirds: [0.4, 0.8],
                    posture: 'sprawling'
                }
            },
            'biped': {
                name: 'Biped',
                preview: '🚶',
                description: 'Bipedal crane with erect posture',
                buildMethod: 'buildBipedalCrane',
                forceParams: {
                    rhythm: 'walk',
                    asymmetry: 0.6,
                    thirds: [0.3, 0.7],
                    posture: 'upright'
                }
            }
        };

        this.currentPreview = null;
    }

    setupUI(parent) {
        // Create main container
        this.container = createDiv();
        this.container.parent(parent);
        this.container.class('template-selector');
        this.container.style(`
            padding: 12px;
            border-radius: 6px;
            background: #f9f9f9;
            border: 1px solid #ddd;
        `);

        // Create header
        const header = createDiv('Template Selection');
        header.parent(this.container);
        header.style(`
            font-weight: bold;
            font-size: 14px;
            margin-bottom: 12px;
            color: #333;
        `);

        // Create template grid
        this.templateGrid = createDiv();
        this.templateGrid.parent(this.container);
        this.templateGrid.class('template-grid');
        this.templateGrid.style(`
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 8px;
            margin-bottom: 12px;
        `);

        // Create template buttons
        Object.keys(this.templates).forEach(templateKey => {
            this.createTemplateButton(templateKey, this.templates[templateKey]);
        });

        // Create preview section
        this.previewSection = new CollapsibleSection(this.container, 'Template Preview', false);
        this.updatePreview(null);

        // Create custom import section
        this.createCustomImportSection();
    }

    createTemplateButton(templateKey, template) {
        const button = createDiv();
        button.parent(this.templateGrid);
        button.class('template-button');
        button.style(`
            padding: 12px 8px;
            border: 2px solid #ddd;
            border-radius: 6px;
            background: #fff;
            cursor: pointer;
            text-align: center;
            transition: all 0.2s ease;
            position: relative;
        `);

        // Add preview icon
        const icon = createDiv(template.preview);
        icon.parent(button);
        icon.style(`
            font-size: 24px;
            margin-bottom: 4px;
        `);

        // Add template name
        const name = createDiv(template.name);
        name.parent(button);
        name.style(`
            font-weight: bold;
            font-size: 11px;
            margin-bottom: 2px;
        `);

        // Add description
        const desc = createDiv(template.description);
        desc.parent(button);
        desc.style(`
            font-size: 9px;
            color: #666;
            line-height: 1.2;
        `);

        // Add click handler
        button.mousePressed(() => {
            this.selectTemplate(templateKey);
        });

        // Add hover effects
        button.mouseOver(() => {
            button.style('border-color', '#999');
            button.style('background', '#f5f5f5');
            this.updatePreview(templateKey);
        });

        button.mouseOut(() => {
            if (this.selectedTemplate !== templateKey) {
                button.style('border-color', '#ddd');
                button.style('background', '#fff');
            }
        });

        // Store reference for selection highlighting
        template.buttonElement = button;
    }

    createCustomImportSection() {
        createSpacer(this.container, 8);
        createDivider(this.container);

        const customSection = createDiv();
        customSection.parent(this.container);

        const customHeader = createDiv('Custom Templates');
        customHeader.parent(customSection);
        customHeader.style(`
            font-weight: bold;
            font-size: 12px;
            margin-bottom: 8px;
            color: #333;
        `);

        // Import button
        const importButton = new IconButton(
            customSection,
            'Import JSON',
            () => this.importCustomTemplate(),
            '📁'
        );

        // Save current as template button
        const saveButton = new IconButton(
            customSection,
            'Save Current',
            () => this.saveCurrentAsTemplate(),
            '💾'
        );

        this.importButton = importButton;
        this.saveButton = saveButton;
    }

    selectTemplate(templateKey) {
        if (!this.templates[templateKey]) return;

        console.time('template-load');

        // Update visual selection
        this.clearSelection();
        this.selectedTemplate = templateKey;
        const template = this.templates[templateKey];

        // Highlight selected button
        if (template.buttonElement) {
            template.buttonElement.style('border-color', '#007acc');
            template.buttonElement.style('background', '#e6f3ff');
            template.buttonElement.style('border-width', '3px');
        }

        // Load template in builder
        this.loadTemplate(templateKey);

        // Update preview
        this.updatePreview(templateKey);

        console.timeEnd('template-load');
    }

    loadTemplate(templateKey) {
        const template = this.templates[templateKey];
        if (!template || !this.builder[template.buildMethod]) {
            console.error(`Template ${templateKey} or build method ${template.buildMethod} not found`);
            return false;
        }

        try {
            // Call the builder method
            this.builder[template.buildMethod]();

            // Notify editor system of template change
            if (this.editorSystem.onTemplateLoaded) {
                this.editorSystem.onTemplateLoaded(templateKey, template);
            }

            console.log(`✅ Template ${templateKey} loaded successfully`);
            return true;
        } catch (error) {
            console.error(`❌ Failed to load template ${templateKey}:`, error);
            return false;
        }
    }

    clearSelection() {
        // Clear all button selections
        Object.values(this.templates).forEach(template => {
            if (template.buttonElement) {
                template.buttonElement.style('border-color', '#ddd');
                template.buttonElement.style('background', '#fff');
                template.buttonElement.style('border-width', '2px');
            }
        });
        this.selectedTemplate = null;
    }

    updatePreview(templateKey) {
        if (!templateKey || !this.templates[templateKey]) {
            this.previewSection.setContent(`
                <div style="text-align: center; padding: 20px; color: #666;">
                    Hover over a template to see preview
                </div>
            `);
            return;
        }

        const template = this.templates[templateKey];
        const forceParams = template.forceParams;

        const previewContent = `
            <div style="font-size: 12px;">
                <div style="margin-bottom: 8px;">
                    <strong>${template.name}</strong>
                    <span style="float: right; font-size: 18px;">${template.preview}</span>
                </div>
                <div style="margin-bottom: 8px; color: #666;">
                    ${template.description}
                </div>
                <div style="background: #f0f0f0; padding: 8px; border-radius: 4px;">
                    <div><strong>FORCE Parameters:</strong></div>
                    <div style="margin-left: 8px; font-family: monospace; font-size: 11px;">
                        <div>Rhythm: ${forceParams.rhythm}</div>
                        <div>Asymmetry: ${(forceParams.asymmetry * 100).toFixed(0)}%</div>
                        <div>Thirds: [${forceParams.thirds.join(', ')}]</div>
                        <div>Posture: ${forceParams.posture}</div>
                    </div>
                </div>
            </div>
        `;

        this.previewSection.setContent(previewContent);
    }

    importCustomTemplate() {
        // Create file input
        const input = createFileInput((file) => {
            if (file.type === 'application/json') {
                const reader = new FileReader();
                reader.onload = (e) => {
                    try {
                        const config = JSON.parse(e.target.result);
                        this.loadCustomTemplate(config);
                    } catch (error) {
                        console.error('Invalid JSON file:', error);
                        alert('Invalid JSON file format');
                    }
                };
                reader.readAsText(file.file);
            } else {
                alert('Please select a JSON file');
            }
        });

        input.style('display', 'none');
        input.elt.click();
    }

    loadCustomTemplate(config) {
        try {
            // Use config manager if available
            if (this.editorSystem.configManager) {
                this.editorSystem.configManager.loadFromConfig(config);
                console.log('✅ Custom template loaded successfully');
            } else {
                console.error('Config manager not available');
            }
        } catch (error) {
            console.error('❌ Failed to load custom template:', error);
            alert('Failed to load template: ' + error.message);
        }
    }

    saveCurrentAsTemplate() {
        try {
            // Use config manager if available
            if (this.editorSystem.configManager) {
                const config = this.editorSystem.configManager.exportConfig();
                const templateName = prompt('Enter template name:', 'Custom Template');

                if (templateName) {
                    // Save to local storage
                    const customTemplates = JSON.parse(localStorage.getItem('madhuban_custom_templates') || '{}');
                    customTemplates[templateName] = config;
                    localStorage.setItem('madhuban_custom_templates', JSON.stringify(customTemplates));

                    console.log(`✅ Template "${templateName}" saved`);
                    alert(`Template "${templateName}" saved successfully`);
                }
            } else {
                console.error('Config manager not available');
            }
        } catch (error) {
            console.error('❌ Failed to save template:', error);
            alert('Failed to save template: ' + error.message);
        }
    }

    getSelectedTemplate() {
        return this.selectedTemplate;
    }

    getTemplateInfo(templateKey) {
        return this.templates[templateKey] || null;
    }

    show() {
        if (this.container) {
            this.container.style('display', 'block');
        }
    }

    hide() {
        if (this.container) {
            this.container.style('display', 'none');
        }
    }

    destroy() {
        if (this.previewSection) {
            this.previewSection.destroy();
            this.previewSection = null;
        }

        if (this.importButton) {
            this.importButton.destroy();
            this.importButton = null;
        }

        if (this.saveButton) {
            this.saveButton.destroy();
            this.saveButton = null;
        }

        if (this.container) {
            this.container.remove();
            this.container = null;
            this.templateGrid = null;
        }

        // Clear template button references
        Object.values(this.templates).forEach(template => {
            template.buttonElement = null;
        });
    }
}

/**
 * UI Components for Madhuban Creature Editor
 * Foundational UI components for consistent interface using p5.js DOM
 */

/**
 * CollapsibleSection - Expandable content sections with headers
 * Provides organized, space-efficient content display
 */
class CollapsibleSection {
    constructor(parent, title, expanded = false) {
        this.parent = parent;
        this.title = title;
        this.expanded = expanded;
        this.content = '';

        // Create main container
        this.container = createDiv();
        this.container.parent(parent);
        this.container.class('collapsible-section');

        // Create header with toggle functionality
        this.header = createDiv();
        this.header.parent(this.container);
        this.header.class('collapsible-header');
        this.header.style(`
            background: #e8e8e8;
            padding: 8px 12px;
            cursor: pointer;
            border: 1px solid #ddd;
            border-radius: 4px 4px 0 0;
            font-weight: bold;
            user-select: none;
        `);

        // Create arrow indicator
        this.arrow = createSpan(this.expanded ? '▼' : '▶');
        this.arrow.parent(this.header);
        this.arrow.style('margin-right: 8px; font-size: 12px;');

        // Add title text
        this.titleSpan = createSpan(this.title);
        this.titleSpan.parent(this.header);

        // Create content area
        this.contentDiv = createDiv();
        this.contentDiv.parent(this.container);
        this.contentDiv.class('collapsible-content');
        this.contentDiv.style(`
            border: 1px solid #ddd;
            border-top: none;
            border-radius: 0 0 4px 4px;
            padding: 8px 12px;
            background: #f9f9f9;
            display: ${this.expanded ? 'block' : 'none'};
        `);

        // Add click handler
        this.header.mousePressed(() => this.toggle());

        // Add hover effects
        this.header.mouseOver(() => {
            this.header.style('background', '#ddd');
        });
        this.header.mouseOut(() => {
            this.header.style('background', '#e8e8e8');
        });
    }

    toggle() {
        this.expanded = !this.expanded;
        this.arrow.html(this.expanded ? '▼' : '▶');
        this.contentDiv.style('display', this.expanded ? 'block' : 'none');
    }

    show() {
        this.container.style('display', 'block');
    }

    hide() {
        this.container.style('display', 'none');
    }

    setContent(htmlString) {
        this.content = htmlString;
        this.contentDiv.html(htmlString);
    }

    destroy() {
        if (this.container) {
            this.container.remove();
            this.container = null;
            this.header = null;
            this.contentDiv = null;
            this.arrow = null;
            this.titleSpan = null;
        }
    }
}

/**
 * PropertySlider - Labeled sliders with live value display
 * Provides consistent numeric input with immediate visual feedback
 */
class PropertySlider {
    constructor(parent, label, min, max, value, callback) {
        this.parent = parent;
        this.label = label;
        this.min = min;
        this.max = max;
        this.value = value;
        this.callback = callback;

        // Create container
        this.container = createDiv();
        this.container.parent(parent);
        this.container.class('property-slider');
        this.container.style(`
            margin: 8px 0;
            padding: 4px;
            border-radius: 4px;
        `);

        // Create label row
        this.labelRow = createDiv();
        this.labelRow.parent(this.container);
        this.labelRow.style('margin-bottom: 4px; display: flex; justify-content: space-between;');

        // Add label text
        this.labelSpan = createSpan(this.label);
        this.labelSpan.parent(this.labelRow);
        this.labelSpan.style('font-weight: bold; font-size: 12px;');

        // Add value display
        this.valueSpan = createSpan(this.value.toFixed(1));
        this.valueSpan.parent(this.labelRow);
        this.valueSpan.style('font-size: 12px; color: #666; font-family: monospace;');

        // Create slider
        this.slider = createSlider(this.min, this.max, this.value, 0.1);
        this.slider.parent(this.container);
        this.slider.style('width: 100%;');

        // Add input handler
        this.slider.input(() => {
            this.value = this.slider.value();
            this.valueSpan.html(this.value.toFixed(1));
            if (this.callback) {
                this.callback(this.value);
            }
        });
    }

    setValue(newValue) {
        this.value = constrain(newValue, this.min, this.max);
        this.slider.value(this.value);
        this.valueSpan.html(this.value.toFixed(1));
    }

    getValue() {
        return this.value;
    }

    setEnabled(enabled) {
        if (enabled) {
            this.slider.removeAttribute('disabled');
            this.container.style('opacity', '1');
        } else {
            this.slider.attribute('disabled', true);
            this.container.style('opacity', '0.5');
        }
    }

    show() {
        this.container.style('display', 'block');
    }

    hide() {
        this.container.style('display', 'none');
    }

    destroy() {
        if (this.container) {
            this.container.remove();
            this.container = null;
            this.slider = null;
            this.labelSpan = null;
            this.valueSpan = null;
            this.labelRow = null;
        }
    }
}

/**
 * IconButton - Consistent button styling with hover effects
 * Provides unified button appearance and behavior
 */
class IconButton {
    constructor(parent, text, callback, icon = null) {
        this.parent = parent;
        this.text = text;
        this.callback = callback;
        this.icon = icon;
        this.enabled = true;

        // Create button
        this.button = createButton(this.icon ? `${this.icon} ${this.text}` : this.text);
        this.button.parent(parent);
        this.button.class('icon-button');
        this.button.style(`
            padding: 6px 12px;
            margin: 2px;
            border: 1px solid #ccc;
            border-radius: 4px;
            background: #f5f5f5;
            cursor: pointer;
            font-size: 12px;
            font-family: inherit;
            transition: all 0.2s ease;
        `);

        // Add click handler
        this.button.mousePressed(() => {
            if (this.enabled && this.callback) {
                this.callback();
            }
        });

        // Add hover effects
        this.button.mouseOver(() => {
            if (this.enabled) {
                this.button.style('background', '#e8e8e8');
                this.button.style('border-color', '#999');
            }
        });

        this.button.mouseOut(() => {
            if (this.enabled) {
                this.button.style('background', '#f5f5f5');
                this.button.style('border-color', '#ccc');
            }
        });
    }

    setEnabled(enabled) {
        this.enabled = enabled;
        if (enabled) {
            this.button.style('opacity', '1');
            this.button.style('cursor', 'pointer');
            this.button.style('background', '#f5f5f5');
        } else {
            this.button.style('opacity', '0.5');
            this.button.style('cursor', 'default');
            this.button.style('background', '#e0e0e0');
        }
    }

    setText(newText) {
        this.text = newText;
        this.button.html(this.icon ? `${this.icon} ${this.text}` : this.text);
    }

    show() {
        this.button.style('display', 'inline-block');
    }

    hide() {
        this.button.style('display', 'none');
    }

    destroy() {
        if (this.button) {
            this.button.remove();
            this.button = null;
        }
    }
}

/**
 * SelectionHighlight - Visual highlighting for selected elements
 * Provides consistent visual feedback for selected chains/bones
 */
class SelectionHighlight {
    constructor() {
        this.highlightedChain = null;
        this.highlightedBone = null;
        this.chainColor = [255, 255, 0]; // Yellow
        this.boneColor = [255, 100, 100]; // Red
        this.highlightWeight = 3;
    }

    highlightChain(chainIndex, color = null) {
        this.highlightedChain = chainIndex;
        this.highlightedBone = null;
        if (color) {
            this.chainColor = color;
        }
    }

    highlightBone(chainIndex, boneIndex, color = null) {
        this.highlightedChain = chainIndex;
        this.highlightedBone = boneIndex;
        if (color) {
            this.boneColor = color;
        }
    }

    clear() {
        this.highlightedChain = null;
        this.highlightedBone = null;
    }

    draw(chains) {
        if (!chains || chains.length === 0) return;

        push();
        strokeWeight(this.highlightWeight);
        noFill();

        // Highlight selected chain
        if (this.highlightedChain !== null && this.highlightedChain < chains.length) {
            const chain = chains[this.highlightedChain];

            if (this.highlightedBone !== null) {
                // Highlight specific bone
                stroke(this.boneColor);
                if (this.highlightedBone < chain.getNumBones()) {
                    const bone = chain.getBone(this.highlightedBone);
                    const start = bone.getStartLocation();
                    const end = bone.getEndLocation();
                    line(start.x, start.y, end.x, end.y);

                    // Draw circles at bone endpoints
                    circle(start.x, start.y, 8);
                    circle(end.x, end.y, 8);
                }
            } else {
                // Highlight entire chain
                stroke(this.chainColor);
                for (let i = 0; i < chain.getNumBones(); i++) {
                    const bone = chain.getBone(i);
                    const start = bone.getStartLocation();
                    const end = bone.getEndLocation();
                    line(start.x, start.y, end.x, end.y);
                }

                // Draw circles at chain endpoints
                if (chain.getNumBones() > 0) {
                    const firstBone = chain.getBone(0);
                    const lastBone = chain.getBone(chain.getNumBones() - 1);
                    const chainStart = firstBone.getStartLocation();
                    const chainEnd = lastBone.getEndLocation();

                    fill(this.chainColor);
                    noStroke();
                    circle(chainStart.x, chainStart.y, 6);
                    circle(chainEnd.x, chainEnd.y, 6);
                }
            }
        }

        pop();
    }

    isPointNearChain(px, py, chain, threshold = 10) {
        for (let i = 0; i < chain.getNumBones(); i++) {
            const bone = chain.getBone(i);
            const start = bone.getStartLocation();
            const end = bone.getEndLocation();

            // Calculate distance from point to line segment
            const dist = this.pointToLineDistance(px, py, start.x, start.y, end.x, end.y);
            if (dist < threshold) {
                return { chainHit: true, boneIndex: i };
            }
        }
        return { chainHit: false, boneIndex: -1 };
    }

    pointToLineDistance(px, py, x1, y1, x2, y2) {
        const A = px - x1;
        const B = py - y1;
        const C = x2 - x1;
        const D = y2 - y1;

        const dot = A * C + B * D;
        const lenSq = C * C + D * D;

        if (lenSq === 0) return dist(px, py, x1, y1);

        let param = dot / lenSq;
        param = constrain(param, 0, 1);

        const xx = x1 + param * C;
        const yy = y1 + param * D;

        return dist(px, py, xx, yy);
    }
}

/**
 * Utility function to create consistent spacing
 */
function createSpacer(parent, height = 8) {
    const spacer = createDiv();
    spacer.parent(parent);
    spacer.style(`height: ${height}px;`);
    return spacer;
}

/**
 * Utility function to create section dividers
 */
function createDivider(parent) {
    const divider = createDiv();
    divider.parent(parent);
    divider.style(`
        height: 1px;
        background: #ddd;
        margin: 8px 0;
    `);
    return divider;
}

