class BipedalWalkPattern extends LocomotionPattern {
    constructor(config) {
        super('bipedal-walk', config);
        this.stepLength = config.stepLength || 25;
        this.stepHeight = config.stepHeight || 30;
        this.bodyHeight = config.bodyHeight || 60;
        this.footSteps = [];
        this.state = 'idle'; // 'walk', 'turn'
    }

    initializeFootSteps(bodyPosition, numFeet) {
        this.footSteps = [];
        for (let i = 0; i < numFeet; i++) {
            this.footSteps.push({
                target: new FIK.V2(
                    bodyPosition.x + (i % 2 === 0 ? -30 : 30),
                    bodyPosition.y + this.bodyHeight
                ),
                phase: i * Math.PI,
                isLifted: false,
                side: i % 2 === 0 ? 'left' : 'right'
            });
        }
    }

    update(creature, deltaTime) {
        super.update(creature, deltaTime);

        // 1. Compute direction to target and angle difference
        const dirToTarget = new FIK.V2(
            creature.mouseTarget.x - creature.bodyPosition.x,
            creature.mouseTarget.y - creature.bodyPosition.y
        );
        const targetAngle = Math.atan2(dirToTarget.y, dirToTarget.x);
        const angleDiff = creature.normalizeAngle(targetAngle - creature.bodyHeading);

        // 2. State selection: ALWAYS WALK toward target (like quadrupeds now)
        // Simplified: always move toward mouse for responsive control
        this.state = 'walk';

        // 3. Update heading gradually while walking
        const walkTurnBlend = 0.07;
        creature.bodyHeading = creature.normalizeAngle(
            creature.bodyHeading + walkTurnBlend * angleDiff
        );

        // 4. Update foot placement - ALWAYS (no state restriction)
        const stepDir = new FIK.V2(Math.cos(creature.bodyHeading), Math.sin(creature.bodyHeading));
        this.footSteps.forEach((foot, i) => {
            foot.phase += 0.1;
            foot.isLifted = Math.sin(foot.phase) > 0.7;

            if (foot.isLifted) {
                // Place next step ahead of current foot position, not body position
                const sideOffset = (foot.side === 'left' ? -5 : 5);
                const perp = new FIK.V2(-stepDir.y, stepDir.x);

                // Step forward from current foot position
                const targetX = creature.bodyPosition.x +
                stepDir.x * this.stepLength +      // Step forward in heading direction
                perp.x * sideOffset;               // Offset left/right from body center

            const targetY = creature.bodyPosition.y +
                stepDir.y * this.stepLength +      // Step forward in heading direction  
                perp.y * sideOffset +              // Offset left/right from body center
                this.bodyHeight;   

                foot.target.x += (targetX - foot.target.x) * 0.1;
                foot.target.y += (targetY - foot.target.y) * 0.1;
            }
        });

        // 5. Update body position based on foot average - ALWAYS
        this.updateBodyFromFeet(creature);
    }

    updateBodyFromFeet(creature) {
        let avgX = 0, avgY = 0;
        let groundedFeet = 0;

        this.footSteps.forEach(foot => {
            if (!foot.isLifted) {
                avgX += foot.target.x;
                avgY += foot.target.y;
                groundedFeet++;
            }
        });

        if (groundedFeet > 0) {
            avgX /= groundedFeet;
            avgY /= groundedFeet;

            const targetBodyX = avgX;
            const targetBodyY = avgY - this.bodyHeight;

            creature.bodyPosition.x += (targetBodyX - creature.bodyPosition.x) * 0.1;
            creature.bodyPosition.y += (targetBodyY - creature.bodyPosition.y) * 0.1;
        }
    }

    getFootTarget(footIndex) {
        if (footIndex < this.footSteps.length) {
            return this.footSteps[footIndex].target;
        }
        return null;
    }

    getGroundedFeetCount() {
        return this.footSteps.filter(f => !f.isLifted).length;
    }

    // Removed per-pattern foot HUD; unified DebugManager renders these

    getTailTarget(tailRole, context) {
        const direction = context.parentBone.getDirectionUV();
        const tailSwing = Math.sin(this.cycle) * 10;
        return new FIK.V2(
            context.attachPoint.x - direction.x * 30,
            context.attachPoint.y + direction.y * 30 + tailSwing
        );
    }

    getWingTarget(wingRole, context) {
        const direction = context.parentBone.getDirectionUV();
        const flap = Math.sin(this.cycle + (wingRole.includes('left') ? 0 : Math.PI)) * 2;
        const side = wingRole.includes('left') ? 1 : -1;
        return new FIK.V2(
            context.attachPoint.x + direction.x * 40 + side * 20,
            context.attachPoint.y + direction.y * 20 + flap
        );
    }
}

export class LocomotionPattern {
    constructor(name, config) {
        this.name = name;
        this.config = config || {};
        this.cycle = 0;
        this.frequency = config.frequency || 1.0;
        this.amplitude = config.amplitude || 1.0;
    }

    update(creature, deltaTime) {
        // Update the cycle based on time and frequency
        this.cycle = (this.cycle + deltaTime * 0.001 * this.frequency) % (Math.PI * 2);

        // Apply pattern-specific updates
        this.updatePattern(creature, deltaTime);
    }

    // To be implemented by subclasses
    updatePattern(creature, deltaTime) {
        throw new Error('Subclasses must implement updatePattern');
    }

    // Helper method to get a value that oscillates with the cycle
    getOscillation(phase = 0) {
        return Math.sin(this.cycle + phase) * this.amplitude;
    }

    // Helper method to get a value that oscillates between 0 and 1
    getNormalizedOscillation(phase = 0) {
        return (Math.sin(this.cycle + phase) + 1) * 0.5;
    }

    // Helper method to get a value that oscillates between min and max
    getRangeOscillation(min, max, phase = 0) {
        const t = (Math.sin(this.cycle + phase) + 1) * 0.5; // 0..1
        return min + (max - min) * t;
    }
}

class LocomotionSystem {
    constructor() {
        this.patterns = new Map();
        this.initializePatterns();
    }

    initializePatterns() {
        this.patterns.set('undulate', UndulatePattern);
        this.patterns.set('bipedal-walk', BipedalWalkPattern);
        this.patterns.set('quadruped-walk', QuadrupedWalkPattern);
        this.patterns.set('serpentine', SerpentinePattern);
        if (typeof SprawlingQuadrupedGaitController !== 'undefined') {
            this.patterns.set('sprawling-quadruped', SprawlingQuadrupedGaitController);
        }
    }

    createPattern(type, config) {
        const PatternClass = this.patterns.get(type);
        if (PatternClass) {
            return new PatternClass(config);
        }
        console.warn(`Locomotion pattern ${type} not found`);
        return null;
    }
}

class LocomotionPattern {
    constructor(name, config) {
        this.name = name;
        this.config = config;
        this.cycle = 0;
        this.frequency = config.frequency || 1.0;
    }

    update(creature, deltaTime) {
        this.cycle += this.frequency * deltaTime;
    }

    getCycle() {
        return this.cycle;
    }
}

class OctopusCrawlPattern {
    constructor(creature) {
        this.creature = creature;
        this.time = 0;
        this.mode = 'crawl';
        this.moveSpeed = 1.2; // crawl speed
        this.turnBlend = 0.08; // crawl turn rate
        this.swimParams = { thrust: 2.5, damping: 0.92, turnBlend: 0.05 };
    }

    setMode(mode) {
        if (mode === 'crawl' || mode === 'swim') {
            this.mode = mode;
        }
        return this.mode;
    }

    toggleMode() {
        this.mode = this.mode === 'crawl' ? 'swim' : 'crawl';
        return this.mode;
    }

    getMode() {
        return this.mode;
    }

    update(creature, deltaTime) {
        // Advance internal time for phase-based motion
        const dt = (deltaTime || 1/60);
        this.time += dt * 3.0;

        const toMouse = new FIK.V2(
            creature.mouseTarget.x - creature.bodyPosition.x,
            creature.mouseTarget.y - creature.bodyPosition.y
        );

        if (this.mode === 'crawl') {
            // Smoothly turn body toward mouse
            const targetAngle = Math.atan2(toMouse.y, toMouse.x);
            const angleDiff = creature.normalizeAngle(targetAngle - (creature.bodyHeading || 0));
            creature.bodyHeading = creature.normalizeAngle((creature.bodyHeading || 0) + this.turnBlend * angleDiff);

            // Move body toward mouse at gentle crawl speed
            const dist = toMouse.length();
            if (dist > 10) {
                const dir = toMouse.normalised();
                const speed = this.moveSpeed * (dt * 60); // frame-rate scaled
                creature.bodyPosition.x += dir.x * speed;
                creature.bodyPosition.y += dir.y * speed;
            }
        } else {
            // Swim mode: thrust pulses + damping for inertia
            const targetAngle = Math.atan2(toMouse.y, toMouse.x);
            const angleDiff = creature.normalizeAngle(targetAngle - (creature.bodyHeading || 0));
            creature.bodyHeading = creature.normalizeAngle((creature.bodyHeading || 0) + this.swimParams.turnBlend * angleDiff);

            const dist = toMouse.length();
            if (dist > 5) {
                const pulse = 0.5 + 0.5 * Math.sin(this.time * 2.0);
                const dir = toMouse.normalised();
                const thrust = this.swimParams.thrust * pulse;
                creature.bodyVelocity.x += dir.x * thrust;
                creature.bodyVelocity.y += dir.y * thrust;
            }

            // Apply water-like damping
            creature.bodyVelocity.multiplyScalar(this.swimParams.damping);
            creature.bodyPosition.add(creature.bodyVelocity);
        }
    }

    getArmTarget(role, ctx) {
        const index = parseInt((role || '').split('-')[1] || '0', 10) || 0;
        const base = ctx && ctx.attachPoint ? ctx.attachPoint : this.creature.bodyPosition;

        if (this.mode === 'swim') {
            // Arms trail behind the body heading with low amplitude
            const backDir = new FIK.V2(-Math.cos(this.creature.bodyHeading || 0), -Math.sin(this.creature.bodyHeading || 0));
            const trail = 60 + (index % 3) * 10;
            const sway = 8 * Math.sin(this.time * 2 + index * 0.6);
            return new FIK.V2(base.x + backDir.x * trail, base.y + backDir.y * trail + sway);
        }

        // Crawl mode: alternating anchor vs swing groups
        const isAnchorGroup = (index % 2) === 0;
        const anchorLift = isAnchorGroup ? 10 : 30;
        const radius = isAnchorGroup ? 30 : 55;

        const phase = index * (Math.PI / 4);
        const angle = this.time + phase;

        const offsetX = Math.cos(angle) * radius;
        const offsetY = Math.sin(angle) * (radius * 0.6) + anchorLift;

        return new FIK.V2(base.x + offsetX, base.y + offsetY);
    }

    applyMantleSwimWave(chain, cfg) {
        // Gentle undulation along mantle for swim visuals
        const len = chain.bones.length;
        for (let i = 0; i < len; i++) {
            const phase = this.time * 1.5 + (i / Math.max(1, len - 1)) * Math.PI * 2;
            const wave = Math.sin(phase) * 10;
            // Use constraints as a simple proxy for visual waving without altering solver API
            const bone = chain.bones[i];
            const baseCW = 25, baseCCW = 25;
            bone.setClockwiseConstraintDegs(baseCW + wave);
            bone.setAnticlockwiseConstraintDegs(baseCCW + wave);
        }
    }
}

// Quadruped gait system with arbitrary heading and world-space gait & stepping
class QuadrupedWalkPattern extends LocomotionPattern {
    constructor(config) {
        super('quadruped-walk', config);
