			return this.x * this.x + this.y * this.y;
		}

		add(v) {
			this.x += v.x;
			this.y += v.y;
			return this;
		}

		plus(v) {
			return new this.constructor(this.x + v.x, this.y + v.y);
		}

		min(v) {
			this.x -= v.x;
			this.y -= v.y;
			return this;
		}

		minus(v) {
			return new V2(this.x - v.x, this.y - v.y);
