			if (target) this.targets.push(target);
			if (meshBone) this.addChainMeshs(chain);
		}

		remove(id) {
			this.chains[id].clear();
			this.chains.splice(id, 1);
			this.meshChains.splice(id, 1);
			this.angleChains.splice(id, 1);
			this.targets.splice(id, 1);
			this.numChains--;
		}
