		getNumChains() {
			return this.numChains;
		}

		getChain(id) {
			return this.chains[id];
		}

		connectChain(Chain, chainNumber, boneNumber, point, target, meshBone, color) {
			let c = chainNumber;
			let n = boneNumber;
			point = point || 'end';

			if (c > this.numChains) {
				Tools.error('Chain not existe !');
				return;
			}

			if (n > this.chains[c].numBones) {
				Tools.error('Bone not existe !');
				return;
			}

			let chain = Chain.clone();
			chain.setBoneConnectionPoint(point === 'end' ? END : START);
			chain.setConnectedChainNumber(c);
			chain.setConnectedBoneNumber(n); // The chain as we were provided should be centred on the origin, so we must now make it
			// relative to the start or end position of the given bone in the given chain.

			let position = point === 'end' ? this.chains[c].bones[n].end : this.chains[c].bones[n].start; //if ( connectionPoint === 'start' ) connectionLocation = this.chains[chainNumber].getBone(boneNumber).start;
			//else connectionLocation = this.chains[chainNumber].getBone(boneNumber).end;

			chain.setBaseLocation(position); // When we have a chain connected to a another 'host' chain, the chain is which is connecting in
			// MUST have a fixed base, even though that means the base location is 'fixed' to the connection
			// point on the host chain, rather than a static location.

			chain.setFixedBaseMode(true); // Translate the chain we're connecting to the connection point

			for (let i = 0; i < chain.numBones; i++) {
