					m2.color.setHex(0x00FFFF);
					extraGeo = new this.THREE.CircleGeometry ( r, 12, a1, a1+a2 );
					extraGeo.applyMatrix4( new this.THREE.Matrix4().makeRotationX( -Math.PI*0.5 ) );
					extraMesh = new this.THREE.Mesh( extraGeo,	m2 );
