			let b = new this.THREE.Mesh(g, m);
			b.castShadow = true;
			b.receiveShadow = true;
			this.scene.add(b);
			return b;
		}

		clearAllBoneMesh() {
			if (!this.isWithMesh) return;
			let i, j, b;
			i = this.meshChains.length;

			while (i--) {
				j = this.meshChains[i].length;

				while (j--) {
					b = this.meshChains[i][j];
					this.scene.remove(b);
					b.geometry.dispose();
					b.material.dispose();
				}

				this.meshChains[i] = [];
			}

			this.meshChains = [];
