					lng = base.distanceTo(this.bones[i].position);
					this.bones[i - 1].getWorldPosition(p0);
					this.bones[i].getWorldPosition(p1);
					p1.sub(p0).normalize();
					if (p1.z === 0) uv.set(p1.x, p1.y);else if (p1.x === 0) uv.set(p1.z, p1.y); //uvs.push( uv );
					//console.log( uv, lng, this.angles[i-1][0], this.angles[i-1][1])

					if (i === 1) chain.addBone(new Bone2D(new V2(0, 0), null, uv, lng, this.angles[i - 1][0], this.angles[i - 1][1])); //else chain.addConsecutiveBone( uv, lng );//, this.angles[i-1][0], this.angles[i-1][1] );
					else chain.addConsecutiveBone(uv, lng, this.angles[i - 1][0], this.angles[i - 1][1]);
