let builder;
let editorSystem;
let editorActive = false;

function setup() {
    createCanvas(windowWidth, windowHeight);
    builder = new ModularCreatureBuilder();
    builder.buildHorse(); // Start with the horse

    // Initialize editor
    editorSystem = new EditorSystem(builder);
}

function draw() {
    background(240);

    if (editorActive) {
        editorSystem.update();
        builder.update(); // Update builder but locomotion paused
        builder.draw();
        editorSystem.draw(); // Draw editor overlay
    } else {
        builder.update();
        builder.draw();
    }
}

function keyPressed() {
    // Check for editor keyboard shortcuts first
    if (editorActive && editorSystem && editorSystem.handleKeyboard) {
        if (editorSystem.handleKeyboard({
            ctrlKey: keyIsDown(CONTROL),
            key: key.toLowerCase(),
            shiftKey: keyIsDown(SHIFT),
            preventDefault: () => {}
        })) {
            return; // Shortcut handled, don't process other keys
        }
    }

    // Editor toggle
    if (key === 'E' || key === 'e') {
        console.time('editor-toggle');

        editorActive = !editorActive;
        builder.editorActive = editorActive;

        if (editorActive) {
            builder.pauseForEditor();
            editorSystem.show();
        } else {
            editorSystem.hide();
            builder.resumeFromEditor();
        }

        console.timeEnd('editor-toggle');
        return;
    }

    // SKELETON EDITING EXTENSIONS - IK Test Mode toggle
    if ((key === 'I' || key === 'i') && editorActive) {
        if (editorSystem.skeletonEditor) {
            editorSystem.skeletonEditor.toggleIKTestMode();
        }
        return;
    }

    switch (key.toLowerCase()) {
        // Creature switching
        case '1':
            builder.buildFish();
            break;
        case '2':
            builder.buildBipedalCrane();
            break;
        case '3':
            builder.buildHorse();
            break;
        case '4':
            builder.buildLizard();
            break;
        case '5':
            builder.buildOctopus();
            break;

        // Debug toggle
        case 'd':
            // Let debug manager handle debug toggle
            if (builder.handleKeyPress(key)) {
                break; // Debug manager handled it
            }
            // Fallback to old system
            builder.showDebug = !builder.showDebug;
            break;

        // Render mode switching
        case 's':
            builder.setRenderMode('skeleton');
            break;
        case 'm':
            builder.setRenderMode('muscle');
            break;
        case 'f':
            builder.setRenderMode('skin');
            break;
        case 'c':
            builder.setRenderMode('current');
            break;
        case ' ':
            builder.switchRenderMode();
            break;

        // Octopus gait toggle (crawl/swim)
        case 'o':
            if (builder.creatureType === 'octopus' && builder.activeLocomotion.toggleMode) {
                const mode = builder.activeLocomotion.toggleMode();
                console.log(`Octopus mode: ${mode}`);
            }
            break;

        // Quadruped gait controls (works for horse and lizard)
        case 'w':
            if ((builder.creatureType === 'horse' || builder.creatureType === 'lizard') && builder.activeLocomotion.transitionToGait) {
                builder.activeLocomotion.transitionToGait('walk', true); // true = manual
            }
            break;
        case 't':
            if ((builder.creatureType === 'horse' || builder.creatureType === 'lizard') && builder.activeLocomotion.transitionToGait) {
                builder.activeLocomotion.transitionToGait('trot', true); // true = manual
            }
            break;
        case 'g':
            if ((builder.creatureType === 'horse' || builder.creatureType === 'lizard') && builder.activeLocomotion.transitionToGait) {
                builder.activeLocomotion.transitionToGait('gallop', true); // true = manual
            }
            break;
        case 'p':
            if ((builder.creatureType === 'horse' || builder.creatureType === 'lizard') && builder.activeLocomotion.transitionToGait) {
                builder.activeLocomotion.transitionToGait('pace', true); // true = manual
            }
            break;

        // Toggle automatic gait switching for quadrupeds
        case 'x':
            if ((builder.creatureType === 'horse' || builder.creatureType === 'lizard') && builder.activeLocomotion.toggleAutomaticGaitSwitching) {
                const isEnabled = builder.activeLocomotion.toggleAutomaticGaitSwitching();
                console.log(`🔄 Automatic Gait Switching: ${isEnabled ? 'ON (moves fast = trot)' : 'OFF (manual only)'}`);
            }
            break;

        // Toggle adaptive ground mode for quadrupeds
        case 'a':
            if ((builder.creatureType === 'horse' || builder.creatureType === 'lizard') && builder.activeLocomotion.adaptiveGround !== undefined) {
                builder.activeLocomotion.adaptiveGround = !builder.activeLocomotion.adaptiveGround;
                console.log(`Adaptive Ground: ${builder.activeLocomotion.adaptiveGround ? 'ON (FREE Hybrid Movement)' : 'OFF (CONSTRAINED Traditional)'}`);
            }
            break;

        // Toggle simple mode for quadrupeds (🔧 DEBUG FEATURE)
        case 'q':
            if ((builder.creatureType === 'horse' || builder.creatureType === 'lizard') && builder.activeLocomotion.debugSimpleMode !== undefined) {
                builder.activeLocomotion.debugSimpleMode = !builder.activeLocomotion.debugSimpleMode;
                console.log(`🔧 Simple Mode: ${builder.activeLocomotion.debugSimpleMode ? 'ON (Crane-like)' : 'OFF (Complex Gait)'}`);
            }
            break;
    }
}

function windowResized() {
    resizeCanvas(windowWidth, windowHeight);
}

// *** MOUSE HANDLING FOR DEBUG SYSTEM AND EDITOR ***
function mousePressed() {
    // Let editor handle mouse clicks first if active
    if (editorActive && editorSystem && editorSystem.handleMouseClick) {
        if (editorSystem.handleMouseClick(mouseX, mouseY)) {
            return; // Editor handled the click
        }
    }

    // Fallback to builder mouse handling
    if (builder && builder.handleMouseClick) {
        builder.handleMouseClick(mouseX, mouseY);
    }
}

// SKELETON EDITING EXTENSIONS - Mouse drag support
function mouseDragged() {
    // Let editor handle mouse dragging first if active
    if (editorActive && editorSystem && editorSystem.handleMouseDrag) {
        if (editorSystem.handleMouseDrag(mouseX, mouseY)) {
            return; // Editor handled the drag
        }
    }
}

class BorderDecorator {
    constructor(path, style) {
        this.path = path;
        this.style = style;
    }

    draw(strokeColor) {
        push(); // Isolate styling for the decorator
        noFill();
        strokeWeight(1); // Consistent weight for borders

        if (strokeColor) {
            stroke(...strokeColor);
        }

        // Draw border lines, preserving original inside/outside logic
        for (let i = 0; i < this.style.numLines; i++) {
            const offset = (i + 1) * this.style.strokeGap;
            this.drawPath(this.path, offset);
            this.drawPath(this.path, -offset);
        }

        // Draw beads
        if (this.style.beads && this.style.beads.count > 0) {
            if (strokeColor) {
                fill(...strokeColor);
                noStroke(); // Beads typically don't have a separate stroke
            }
            this.drawBeads();
        }
        pop(); // Restore original drawing style
    }

    drawPath(path, offset) {
        beginShape();
        for (let i = 0; i < path.length; i++) {
            const p = path[i];
            const p_next = path[(i + 1) % path.length];
            const normal = createVector(p_next.y - p.y, p.x - p_next.x).normalize();
            const new_p = p5.Vector.add(p, p5.Vector.mult(normal, offset));
            vertex(new_p.x, new_p.y);
        }
        endShape(CLOSE);
    }

    drawBeads() {
        const totalLength = this.getPathLength(this.path);
        const spacing = totalLength / this.style.beads.count;

        for (let i = 0; i < this.style.beads.count; i++) {
            const point = this.getPointAtLength(this.path, i * spacing);
            ellipse(point.x, point.y, this.style.beads.size, this.style.beads.size);
        }
    }

    getPathLength(path) {
        let length = 0;
        for (let i = 0; i < path.length; i++) {
            length += p5.Vector.dist(path[i], path[(i + 1) % path.length]);
        }
        return length;
    }

    getPointAtLength(path, length) {
        let currentLength = 0;
        for (let i = 0; i < path.length; i++) {
            const p1 = path[i];
            const p2 = path[(i + 1) % path.length];
            const segmentLength = p5.Vector.dist(p1, p2);
            if (currentLength + segmentLength >= length) {
                const t = (length - currentLength) / segmentLength;
                return p5.Vector.lerp(p1, p2, t);
            }
            currentLength += segmentLength;
        }
    }
}

class Filler {
    constructor(path, style) {
        this.path = path;
        this.style = style;
    }

    draw(strokeColor) {
        push(); // Isolate styling for the filler
        noFill(); // Fillers are typically stroke-only patterns
        strokeWeight(1); // Consistent weight for filler patterns

        if (strokeColor) {
            stroke(...strokeColor);
        }

        switch (this.style.pattern) {
            case 'hatching':
                this.drawHatching();
                break;
            case 'dots':
                this.drawDots();
                break;
            case 'circles':
                this.drawCircles();
                break;
        }
        pop(); // Restore original drawing style
    }

    drawHatching() {
        const bounds = this.getBoundingBox(this.path);
        for (let y = bounds.minY; y < bounds.maxY; y += this.style.spacing) {
            for (let x = bounds.minX; x < bounds.maxX; x += this.style.spacing) {
                if (this.isPointInPath(createVector(x, y), this.path)) {
                    line(x, y, x + this.style.spacing, y + this.style.spacing);
                }
            }
        }
    }

    drawDots() {
        const bounds = this.getBoundingBox(this.path);
        for (let y = bounds.minY; y < bounds.maxY; y += this.style.spacing) {
            for (let x = bounds.minX; x < bounds.maxX; x += this.style.spacing) {
                if (this.isPointInPath(createVector(x, y), this.path)) {
                    point(x, y);
                }
            }
        }
    }

    drawCircles() {
        const bounds = this.getBoundingBox(this.path);
        for (let y = bounds.minY; y < bounds.maxY; y += this.style.spacing) {
            for (let x = bounds.minX; x < bounds.maxX; x += this.style.spacing) {
                if (this.isPointInPath(createVector(x, y), this.path)) {
                    ellipse(x, y, this.style.radius, this.style.radius);
                }
            }
        }
    }

    getBoundingBox(path) {
        let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
        for (const p of path) {
            minX = min(minX, p.x);
            minY = min(minY, p.y);
            maxX = max(maxX, p.x);
            maxY = max(maxY, p.y);
        }
        return { minX, minY, maxX, maxY };
    }

    isPointInPath(point, path) {
        let inside = false;
        for (let i = 0, j = path.length - 1; i < path.length; j = i++) {
            const xi = path[i].x, yi = path[i].y;
            const xj = path[j].x, yj = path[j].y;

            const intersect = ((yi > point.y) !== (yj > point.y)) &&
                (point.x < (xj - xi) * (point.y - yi) / (yj - yi) + xi);
            if (intersect) inside = !inside;
        }
        return inside;
    }
}

class Segmenter {
    constructor(path) {
        this.path = path;
    }

    segment(numSegments) {
        const segments = [];
        const bounds = this.getBoundingBox(this.path);
        const segmentHeight = (bounds.maxY - bounds.minY) / numSegments;

        for (let i = 0; i < numSegments; i++) {
            const segmentY = bounds.minY + i * segmentHeight;
            const segment = this.clip(this.path, segmentY, segmentHeight);
            segments.push(segment);
        }
        return segments;
    }

    clip(path, y, h) {
        const clippedPath = [];
        for (let i = 0; i < path.length; i++) {
            const p1 = path[i];
            const p2 = path[(i + 1) % path.length];

            const p1_inside = p1.y >= y && p1.y <= y + h;
            const p2_inside = p2.y >= y && p2.y <= y + h;

            if (p1_inside) {
                clippedPath.push(p1);
            }

            if (p1_inside !== p2_inside) {
                const intersection = this.getIntersection(p1, p2, y);
                if (intersection) clippedPath.push(intersection);
                const intersection2 = this.getIntersection(p1, p2, y + h);
                if (intersection2) clippedPath.push(intersection2);
            }
        }
        return clippedPath;
    }

    getIntersection(p1, p2, y) {
        const t = (y - p1.y) / (p2.y - p1.y);
        if (t >= 0 && t <= 1) {
            return p5.Vector.lerp(p1, p2, t);
        }
        return null;
    }

    getBoundingBox(path) {
        let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
        for (const p of path) {
            minX = min(minX, p.x);
            minY = min(minY, p.y);
            maxX = max(maxX, p.x);
            maxY = max(maxY, p.y);
        }
        return { minX, minY, maxX, maxY };
    }
}

class ThemeManager {
    constructor() {
        this.themes = {
            'default': {
                background: [245, 235, 220],
                creature_fill: () => [random(180, 220), random(200, 240), random(160, 200)],
                creature_stroke: [139, 69, 19],
                stroke_weight: 2,
                border: {
                    stroke: [139, 69, 19],
                    style: { numLines: 1, strokeGap: 3, beads: { count: 15, size: 4 } }
                },
                filler: {
                    stroke: [139, 69, 19],
                    patterns: ['circles', 'hatching', 'dots'],
                    styles: {
                        'circles': { pattern: 'circles', spacing: 15, radius: 3 },
                        'hatching': { pattern: 'hatching', spacing: 10 },
                        'dots': { pattern: 'dots', spacing: 8 }
                    }
                }
            },
            'ocean': {
                background: [0, 50, 100],
                creature_fill: () => [random(0, 50), random(120, 180), random(200, 255)],
                creature_stroke: [255, 255, 255],
                stroke_weight: 1,
                border: {
                    stroke: [255, 255, 255],
                    style: { numLines: 1, strokeGap: 4, beads: { count: 20, size: 3 } }
                },
                filler: {
                    stroke: [200, 200, 255],
                    patterns: ['hatching', 'dots'],
                    styles: {
                        'hatching': { pattern: 'hatching', spacing: 8 },
                        'dots': { pattern: 'dots', spacing: 10 }
                    }
                }
            }
        };
        this.currentTheme = 'default';
    }

    setTheme(themeName) {
        if (this.themes[themeName]) {
            this.currentTheme = themeName;
            console.log(`Theme changed to: ${themeName}`);
            // Optional: Add a function to redraw the canvas or notify other components
            if (typeof redraw === 'function') {
                redraw(); // if using p5.js noLoop() mode
            }
        }
    }

    get(key) {
        const theme = this.themes[this.currentTheme];
        const keys = key.split('.');
        let value = theme;
        for (const k of keys) {
            if (value && typeof value === 'object' && k in value) {
                value = value[k];
            } else {
                return undefined; // Key not found
            }
        }
        return value;
    }
}

/**
 * Anatomical Configuration System for Madhuban Creatures
 * Centralizes all posture-specific and anatomical parameters
 * Defines the key differences between erect and sprawling postures
 */

/**
 * Anatomical configuration data for different creature types.
 * Each creature type has a nested object containing configuration data.
 *
 * @type {Object.<string, {
 *   postureType: string,
 *   bodyHeight: number,
 *   bodyLength: number,
 *   legPositioning: {
 *     spacing: number,
 *     angle: number,
 *     attachment: string,
 *     shoulderHipDistance: number,
