 *     segments: number,
 *     undulationEnabled: boolean,
 *     verticalFlex: number,
 *     lateralFlex: number,
 *     undulationAmplitude: number,
 *     undulationFrequency: number
 *   },
 *   jointOverrides: {
 *     [jointName: string]: {
 *       abductionLimit: number,
 *       verticalBias: number
 *     }
 *   },
 *   gaitParameters: {
 *     defaultGait: string,
 *     stepHeight: number,
 *     strideLength: number,
 *     bodyRoll: number,
 *     bodyPitch: number,
