                },
                stifle: {                   // Horse knee (hind leg)
                    flexion: [0, 155],      // Full flexion for galloping
                    extension: 0
                },
                carpus: {                   // Horse "knee" (front leg wrist)
                    flexion: [-10, 75],     // Forward flexion, slight extension
                    deviation: [-5, 5]      // Minimal lateral deviation
                },
                hock: {                     // Horse ankle (hind leg)
                    flexion: [-20, 85],     // Dorsal/plantar flexion
                    rotation: [-3, 3]       // Very limited rotation
                },
                fetlock: {                  // CRITICAL: Fetlock joint (both legs)
                    flexion: [-25, 65],     // Flexion + HYPEREXTENSION
                    hyperextension: 25,     // Natural shock absorption
                    lateral: [-3, 3]        // Minimal lateral movement
                },
                pastern: {                  // Pastern joint (if present)
                    flexion: [-15, 45],     // Fine movement control
                    lateral: [-3, 3]        // Very limited lateral
                },
                coffin: {                   // Inside hoof (minimal movement)
                    flexion: [-8, 25],      // Shock absorption only
                    lateral: [-2, 2]
                }
            },

            // Body Proportions - Equine anatomy
            proportions: {
                legToBody: 1.1,         // Legs slightly taller than body
                neckToBody: 0.8,        // Proportional neck
                bodyWidth: 1.0,         // Barrel chest
                legWidth: 0.25,         // Muscular legs
                cannonRatio: 0.3        // Cannon bone relative to forearm
            },

            // Width Profiles
            widthProfiles: {
                torso: [
                    {t: 0.0, width: 0.7},   // Chest
                    {t: 0.3, width: 1.0},   // Barrel (widest)
                    {t: 0.7, width: 0.9},   // Back
                    {t: 1.0, width: 0.6}    // Hip
                ],
                neck: [
                    {t: 0.0, width: 0.5},   // Base
                    {t: 0.6, width: 0.4},   // Mid-neck
                    {t: 1.0, width: 0.45}   // Head
                ],
                leg: [
                    {t: 0.0, width: 0.35},  // Shoulder/hip
                    {t: 0.4, width: 0.25},  // Upper leg
                    {t: 0.7, width: 0.15},  // Cannon bone
                    {t: 1.0, width: 0.12}   // Hoof
                ]
            },

            // Locomotion Parameters
            locomotion: {
                walk: {
                    frequency: 1.0,
                    dutyCycle: 0.75,    // 75% stance
                    phaseShift: 0.25    // 4-beat gait
                },
                trot: {
                    frequency: 2.0,
                    dutyCycle: 0.5,     // 50% stance
                    phaseShift: 0.5     // Diagonal pairs
                },
                gallop: {
                    frequency: 3.0,
                    dutyCycle: 0.25,    // 25% stance
                    phaseShift: 0.1     // Grouped beats
                }
            }
        };
    }

    static get LIZARD() {
        return {
            // Skeletal Structure - Sprawling Quadruped
            legs: {
                segments: 4,
                // Sprawling posture proportions (longer lateral reach)
                humerus: 0.45,          // Long lateral humerus
                radius: 0.45,           // Long forearm
                carpus: 0.18,           // Wrist/hand
                digits: 0.22            // Toes/claws with reach
            },

            spine: {
                segments: 15,           // Highly flexible
                flexibility: 'very-high'
            },

            tail: {
                segments: 12,           // Long undulating tail
                flexibility: 'very-high',
                taper: true
            },

            // Joint Constraints (degrees) - Sprawling posture
            constraints: {
                shoulder: {
                    flexion: [-45, 90],     // Wide range
                    abduction: [-60, 60],   // Sprawling angle
                    rotation: [-30, 30]
                },
                hip: {
                    flexion: [-30, 80],
                    abduction: [-70, 70],   // Very splayed
                    rotation: [-45, 45]
                },
                elbow: {
                    flexion: [0, 120]       // Horizontal flexion
                },
                knee: {
                    flexion: [0, 110]
                },
                spinalSegment: {
                    lateralFlexion: 15,     // High lateral flexibility
                    dorsalFlexion: 5
                },
                tailSegment: {
                    lateralFlexion: 20,     // Very flexible tail
                    dorsalFlexion: 10
                }
            },

            // Body Proportions - Low, elongated
            proportions: {
                legToBody: 0.55,        // Longer legs for pronounced sprawl reach
                tailToBody: 1.2,
                bodyWidth: 0.6,
                legWidth: 0.14,
                sprawlAngle: 55         // Strong splay
            },

            // Width Profiles
            widthProfiles: {
                torso: [
                    {t: 0.0, width: 0.5},   // Head/neck
                    {t: 0.2, width: 0.8},   // Shoulders
                    {t: 0.6, width: 0.9},   // Mid-body (widest)
                    {t: 1.0, width: 0.7}    // Hip
                ],
                tail: [
                    {t: 0.0, width: 0.6},   // Base
                    {t: 0.5, width: 0.4},   // Mid-tail
                    {t: 0.8, width: 0.2},   // Tapering
                    {t: 1.0, width: 0.05}   // Tip
                ],
                leg: [
                    {t: 0.0, width: 0.15},  // Shoulder/hip
                    {t: 0.5, width: 0.12},  // Mid-limb
                    {t: 0.8, width: 0.08},  // Lower limb
                    {t: 1.0, width: 0.06}   // Foot/claws
                ]
            },

            // Locomotion Parameters
            locomotion: {
                lateralUndulation: {
                    amplitude: 35,
                    frequency: 1.8,
                    wavelength: 1.2
                },
                limbCoordination: {
                    frequency: 1.0,
                    phaseShift: 0.25,   // Alternating pattern
                    sprawlCompensation: 0.3
                }
            }
        };
    }

    // Utility function to get width at specific point along creature
    static getWidthAtPosition(creatureType, bodyPart, t) {
        const data = this[creatureType.toUpperCase()];
        const profile = data.widthProfiles[bodyPart];

        if (!profile) return 1.0;

        // Linear interpolation between profile points
        for (let i = 0; i < profile.length - 1; i++) {
            if (t >= profile[i].t && t <= profile[i + 1].t) {
                const ratio = (t - profile[i].t) / (profile[i + 1].t - profile[i].t);
                return profile[i].width + ratio * (profile[i + 1].width - profile[i].width);
            }
        }

        return profile[profile.length - 1].width;
    }
}

class BoneTemplateSystem {
    constructor() {
        this.templates = new Map();
        this.quadrupedTemplateSystem = new QuadrupedTemplateSystem();  // NEW: Add quadruped templating
        this.initializeTemplates();
    }

    // Helper method to ensure bone lengths are always positive
    validateBoneLength(length, minLength = 0.1) {
        if (length <= 0) {
            console.warn(`Invalid bone length ${length}, clamping to ${minLength}`);
            return minLength;
        }
        return length;
    }

    initializeTemplates() {
        // Fish templates - using anatomical data
        this.templates.set('fish-spine', (length, config) => {
            const fishData = AnatomicalData.FISH;
            const bones = [];
            const segments = config.segments || fishData.spine.segments;

            for (let i = 0; i < segments; i++) {
                const t = i / (segments - 1); // Position along spine (0-1)
                const flexionLimit = fishData.constraints.spinalSegment.lateralFlexion;

                bones.push({
                    length: length,
                    direction: new FIK.V2(-1, Math.sin(i * 0.3) * 0.1),
                    constraints: { 
                        clockwise: flexionLimit, 
                        anticlockwise: flexionLimit 
                    },
                    jointType: 'hinge',
                    anatomicalRole: 'vertebra'
                });
            }
            return bones;
        });

        // Vertebrate spine
        this.templates.set('vertebrate-spine', (length, config) => {
            const bones = [];
            for (let i = 0; i < config.segments; i++) {
                bones.push({
                    length: length,
                    direction: new FIK.V2(0, -1),
                    constraints: { 
                        clockwise: config.flexibility === 'medium' ? 30 : 10, 
                        anticlockwise: config.flexibility === 'medium' ? 30 : 20 
                    }
                });
            }
            return bones;
        });

        // Vertebrate neck
        this.templates.set('vertebrate-neck', (length, config) => {
            const bones = [];
            for (let i = 0; i < config.segments; i++) {
                bones.push({
                    length: length,
                    direction: new FIK.V2(0.2, -1).normalised(),
                    constraints: { 
                        clockwise: 60, 
                        anticlockwise: 60 
                    }
                });
            }
            return bones;
        });

        // Crane leg - anatomically accurate bipedal bird leg
        this.templates.set('crane-leg', (length, config) => {
            const craneData = AnatomicalData.CRANE;
            const legData = craneData.legs;
            const constraints = craneData.constraints;

            return [
                { // Femur (hip to knee) - short, held close to body
                    length: length * legData.femur,
                    direction: new FIK.V2(0.5, 1), // Slightly angled
                    constraints: { 
                        clockwise: constraints.hip.flexion[1] / 2, 
                        anticlockwise: constraints.hip.flexion[1] / 2 
                    },
                    jointType: 'ball-socket',
                    anatomicalRole: 'hip'
                },
                { // Tibiotarsus (knee to ankle) - long, main visible leg
                    length: length * legData.tibiotarsus,
                    direction: new FIK.V2(0, 1),
                    constraints: { 
                        clockwise: constraints.knee.flexion[1], 
                        anticlockwise: 0 
                    },
                    jointType: 'hinge',
                    anatomicalRole: 'knee'
                },
                { // Tarsometatarsus (ankle to toe) - very long "foot"
                    length: length * legData.tarsometatarsus,
                    direction: new FIK.V2(0, 1),
                    constraints: { 
                        clockwise: constraints.ankle.flexion[1], 
                        anticlockwise: Math.abs(constraints.ankle.flexion[0])
                    },
                    jointType: 'hinge',
                    anatomicalRole: 'ankle'
                },
                { // Toes
                    length: length * legData.toes,
                    direction: new FIK.V2(1, 0.2),
                    constraints: { clockwise: 30, anticlockwise: 15 },
                    jointType: 'hinge',
                    anatomicalRole: 'toe'
                }
            ];
        });

        // Horse front leg - erect quadruped with unguligrade stance (NOW 5 SEGMENTS)
        this.templates.set('horse-front-leg', (length, config) => {
            const horseData = AnatomicalData.HORSE;
            const legData = horseData.legs.front;
            const constraints = horseData.constraints;

            return [
                { // Scapula/Shoulder - mostly hidden in body
                    length: this.validateBoneLength(length * legData.scapula),
                    direction: new FIK.V2(0.3, 1),
                    constraints: { 
                        clockwise: constraints.shoulder.flexion[1], 
                        anticlockwise: Math.abs(constraints.shoulder.flexion[0])
                    },
                    jointType: 'ball-socket',
                    anatomicalRole: 'shoulder'
                },
                { // Humerus
                    length: this.validateBoneLength(length * legData.humerus),
                    direction: new FIK.V2(0, 1),
                    constraints: { 
                        clockwise: constraints.elbow.flexion[1], 
                        anticlockwise: 0 
                    },
                    jointType: 'hinge',
                    anatomicalRole: 'elbow'
                },
                { // Radius/Forearm
                    length: this.validateBoneLength(length * legData.radius),
                    direction: new FIK.V2(0, 1),
                    constraints: { 
                        clockwise: constraints.carpus.flexion[1], 
                        anticlockwise: Math.abs(constraints.carpus.flexion[0])
                    },
                    jointType: 'hinge',
                    anatomicalRole: 'carpus'
                },
                { // Cannon bone (Metacarpus)
                    length: this.validateBoneLength(length * legData.cannon),
                    direction: new FIK.V2(0, 1),
                    constraints: { 
                        clockwise: constraints.fetlock.flexion[1], 
                        anticlockwise: Math.abs(constraints.fetlock.flexion[0])
                    },
                    jointType: 'hinge',
                    anatomicalRole: 'fetlock'
                },
                { // NEW: Hoof - GROUND CONTACT POINT
                    length: this.validateBoneLength(length * legData.hoof),
                    direction: new FIK.V2(0.2, 1),    // Angled forward for natural stance
                    constraints: { 
                        clockwise: constraints.coffin.flexion[1], 
                        anticlockwise: Math.abs(constraints.coffin.flexion[0])
                    },
                    jointType: 'hinge',
                    anatomicalRole: 'coffin',
                    groundContact: true    // This touches the ground
                }
            ];
        });

        // Horse hind leg - powerful hindquarters (KEEP 5 SEGMENTS, UPDATE CONSTRAINTS)
        this.templates.set('horse-hind-leg', (length, config) => {
            const horseData = AnatomicalData.HORSE;
            const legData = horseData.legs.hind;
            const constraints = horseData.constraints;

            return [
                { // Femur
                    length: this.validateBoneLength(length * legData.femur),
                    direction: new FIK.V2(-0.2, 1), // Angled back slightly
                    constraints: { 
                        clockwise: constraints.hip.flexion[1], 
                        anticlockwise: Math.abs(constraints.hip.flexion[0])
                    },
                    jointType: 'ball-socket',
                    anatomicalRole: 'hip'
                },
                { // Tibia
                    length: this.validateBoneLength(length * legData.tibia),
                    direction: new FIK.V2(0, 1),
                    constraints: { 
                        clockwise: constraints.stifle.flexion[1], 
                        anticlockwise: 0 
                    },
                    jointType: 'hinge',
                    anatomicalRole: 'stifle'
                },
                { // Cannon bone (Metatarsus)
                    length: this.validateBoneLength(length * legData.cannon),
                    direction: new FIK.V2(0, 1),
                    constraints: { 
                        clockwise: constraints.hock.flexion[1], 
                        anticlockwise: Math.abs(constraints.hock.flexion[0])
                    },
                    jointType: 'hinge',
                    anatomicalRole: 'hock'
                },
                { // Hoof
                    length: this.validateBoneLength(length * legData.hoof),
                    direction: new FIK.V2(0.2, 1),
                    constraints: { 
                        clockwise: constraints.fetlock.flexion[1], 
                        anticlockwise: Math.abs(constraints.fetlock.flexion[0])
                    },
                    jointType: 'hinge',
                    anatomicalRole: 'fetlock',
                    groundContact: true,    // Ground contact point
                    propulsionPoint: true   // Main power generation
                }
            ];
        });

        // Lizard leg - sprawling quadruped
        this.templates.set('lizard-leg', (length, config) => {
            const lizardData = AnatomicalData.LIZARD;
            const legData = lizardData.legs;
            const constraints = lizardData.constraints;
            const side = config.side || 'left';
            const sprawlAngle = lizardData.proportions.sprawlAngle;

            // Adjust direction based on sprawling posture
            const sprawlDir = side === 'left' ? -1 : 1;

            return [
                { // Humerus/Femur - strongly splayed outward, low vertical
                    length: this.validateBoneLength(length * legData.humerus),
                    direction: new FIK.V2(sprawlDir * Math.cos(sprawlAngle * Math.PI/180), 0.35),
                    constraints: { 
                        clockwise: constraints.shoulder.flexion[1], 
                        anticlockwise: Math.abs(constraints.shoulder.flexion[0])
                    },
                    jointType: 'ball-socket',
                    anatomicalRole: 'shoulder',
                    sprawlAngle: sprawlAngle
                },
                { // Radius/Tibia - forward sweep with slight downward
                    length: this.validateBoneLength(length * legData.radius),
                    direction: new FIK.V2(sprawlDir * 0.6, 0.9),
                    constraints: { 
                        clockwise: constraints.elbow.flexion[1], 
                        anticlockwise: 0 
                    },
                    jointType: 'hinge',
                    anatomicalRole: 'elbow'
                },
                { // Carpus/Tarsus - mostly forward
                    length: this.validateBoneLength(length * legData.carpus),
                    direction: new FIK.V2(sprawlDir * 0.5, 0.9),
                    constraints: { clockwise: 60, anticlockwise: 30 },
                    jointType: 'hinge',
                    anatomicalRole: 'wrist'
                },
                { // Digits (toes/claws) - forward reach
                    length: this.validateBoneLength(length * legData.digits),
                    direction: new FIK.V2(sprawlDir * 0.8, 0.6),
                    constraints: { clockwise: 45, anticlockwise: 20 },
                    jointType: 'hinge',
                    anatomicalRole: 'digits'
                }
            ];
        });

        // Generic vertebrate leg (fallback)
        this.templates.set('vertebrate-leg', (length, config) => {
            return [
                { // Hip to knee
                    length: length*0.5,
                    direction: new FIK.V2(1, 1),
                    constraints: { clockwise: 30, anticlockwise: 30 }
                },
                { // Knee to ankle
                    length: length * 1,
                    direction: new FIK.V2(0, 1),
                    constraints: { clockwise: 90, anticlockwise: 0 }
                },
                { // Ankle to toe
                    length: length * 0.6,
                    direction: new FIK.V2(0, 1),
                    constraints: { clockwise: 90, anticlockwise: 0 }
                },
                { // Foot
                    length: length * 0.2,
                    direction: new FIK.V2(1, 0),
                    constraints: { clockwise: 45, anticlockwise: 0 }
                }
            ];
        });

        // Fin template
        this.templates.set('fin', (size, config) => {
            const rad = (config.angle || 0) * Math.PI / 180;
            return [
                {
                    length: size,
                    direction: new FIK.V2(Math.cos(rad), Math.sin(rad)),
                    constraints: { clockwise: 70, anticlockwise: 70 }
                },
                {
                    length: size * 0.7,
                    direction: new FIK.V2(Math.cos(rad) * 1.2, Math.sin(rad) * 0.8),
                    constraints: { clockwise: 80, anticlockwise: 80 }
                }
            ];
        });

        // Wing template
        this.templates.set('wing', (size, config) => {
            const rad = (config.angle || 0) * Math.PI / 180;
            return [
                {
                    length: size,
                    direction: new FIK.V2(Math.cos(rad), Math.sin(rad)),
                    constraints: { clockwise: 70, anticlockwise: 70 }
                },
                {
                    length: size * 0.7,
                    direction: new FIK.V2(Math.cos(rad) * 1.2, Math.sin(rad) * 0.8),
                    constraints: { clockwise: 80, anticlockwise: 80 }
                }
            ];
        });

        // Vertebrate tail
        this.templates.set('vertebrate-tail', (length, config) => {
            const bones = [];
            for (let i = 0; i < config.segments; i++) {
                // Safe taper calculation that prevents negative lengths
                const taperFactor = config.taper ? Math.max(1 - i * 0.12, 0.15) : 1;
                const boneLength = this.validateBoneLength(length * taperFactor);

                bones.push({
                    length: boneLength,
                    direction: new FIK.V2(-0.8, 0.4),
                    constraints: { clockwise: 40, anticlockwise: 40 }
                });
            }
            return bones;
        });

        // Serpentine spine
        this.templates.set('serpentine-spine', (length, config) => {
            const bones = [];
            for (let i = 0; i < config.segments; i++) {
                bones.push({
                    length: length,
                    direction: new FIK.V2(1, Math.sin(i * 0.1) * 0.05),
                    constraints: { 
                        clockwise: config.flexibility === 'very-high' ? 45 : 30, 
                        anticlockwise: config.flexibility === 'very-high' ? 45 : 30 
                    }
                });
            }
            return bones;
        });
    }

    generateBones(templateName, scale, config) {
        // Check if it's a quadruped template request
        if (templateName.includes('quadruped-')) {
            return this.generateQuadrupedBones(templateName, scale, config);
        }

        // Use existing template system
        const template = this.templates.get(templateName);
        if (template) {
            return template(scale, config);
        }
        console.warn(`Bone template ${templateName} not found`);
        return [];
    }

    /**
     * Generate bones using the quadruped template system
     * Example: generateQuadrupedBones('quadruped-deer-front-leg', 50, { side: 'left' })
     */
    generateQuadrupedBones(templateName, scale, config = {}) {
        // Parse template name: quadruped-[species]-[front/hind]-leg
        const parts = templateName.split('-');
        if (parts.length < 4) {
            console.warn(`Invalid quadruped template name: ${templateName}`);
            return [];
        }

        const species = parts[1];     // e.g., 'deer', 'cow', 'dog'
        const legType = parts[2];     // 'front' or 'hind'

        // Get or create the quadruped template
        let template;
        if (QuadrupedTemplateSystem.PRESETS[species.toUpperCase()]) {
            const preset = QuadrupedTemplateSystem.PRESETS[species.toUpperCase()];
            if (typeof preset === 'string') {
                template = this.quadrupedTemplateSystem.templates.get(preset);
            } else {
                template = this.quadrupedTemplateSystem.createQuadruped(preset.base, preset.modifications);
            }
        } else {
            console.warn(`Quadruped preset ${species} not found, using erect-quadruped`);
            template = this.quadrupedTemplateSystem.templates.get('erect-quadruped');
        }

        if (!template) {
            console.warn(`Could not create template for ${species}`);
            return [];
        }

        // Generate bones using the template
        return this.quadrupedTemplateSystem.generateQuadrupedLeg(template, legType, scale, config);
    }
}

class ConstraintSystem {
    constructor() {
        this.constraints = new Map();
        this.jointProfiles = new Map();
        this.initializeConstraints();
        this.initializeJointProfiles();
    }

    initializeConstraints() {
        // Default constraints
        this.constraints.set('default', {
            clockwise: 180,
            anticlockwise: 180
        });

        this.constraints.set('vertebra', {
            clockwise: 25,
            anticlockwise: 25
        });

        this.constraints.set('neck', {
            clockwise: 45,
            anticlockwise: 45
        });

        this.constraints.set('leg', {
            clockwise: 60,
            anticlockwise: 10
        });

        this.constraints.set('finBase', {
            clockwise: 45,
            anticlockwise: 45
        });

        this.constraints.set('wing', {
            clockwise: 90,
            anticlockwise: 90
        });
    }

    initializeJointProfiles() {
        // Fish joint profiles
        this.jointProfiles.set('fish', {
            vertebra: {
                type: 'hinge',
                primaryAxis: 'lateral',
                range: AnatomicalData.FISH.constraints.spinalSegment.lateralFlexion,
                secondaryRange: AnatomicalData.FISH.constraints.spinalSegment.dorsalFlexion
            },
            fin: {
                type: 'hinge',
                primaryAxis: 'rotational',
                range: AnatomicalData.FISH.constraints.fins.pectoralRange
            }
        });

        // Crane joint profiles  
        this.jointProfiles.set('crane', {
            hip: {
                type: 'ball-socket',
                flexion: AnatomicalData.CRANE.constraints.hip.flexion,
                abduction: AnatomicalData.CRANE.constraints.hip.abduction,
                rotation: AnatomicalData.CRANE.constraints.hip.rotation
            },
            knee: {
                type: 'hinge',
                flexion: AnatomicalData.CRANE.constraints.knee.flexion
            },
            ankle: {
                type: 'hinge',
                flexion: AnatomicalData.CRANE.constraints.ankle.flexion
            },
            neckSegment: {
                type: 'hinge',
                flexion: AnatomicalData.CRANE.constraints.neckSegment.flexion,
                lateralBend: AnatomicalData.CRANE.constraints.neckSegment.lateralBend
            }
        });

        // Horse joint profiles - UPDATED WITH REALISTIC CONSTRAINTS
        this.jointProfiles.set('horse', {
            shoulder: {
                type: 'ball-socket',
                flexion: AnatomicalData.HORSE.constraints.shoulder.flexion,
                abduction: AnatomicalData.HORSE.constraints.shoulder.abduction,
                rotation: AnatomicalData.HORSE.constraints.shoulder.rotation
            },
            hip: {
                type: 'ball-socket',
                flexion: AnatomicalData.HORSE.constraints.hip.flexion,
                abduction: AnatomicalData.HORSE.constraints.hip.abduction,
                rotation: AnatomicalData.HORSE.constraints.hip.rotation
            },
            elbow: {
                type: 'hinge',
                flexion: AnatomicalData.HORSE.constraints.elbow.flexion
            },
            stifle: {
                type: 'hinge',
                flexion: AnatomicalData.HORSE.constraints.stifle.flexion
            },
            carpus: {  // NEW: Horse "knee" (front leg wrist)
                type: 'hinge',
                flexion: AnatomicalData.HORSE.constraints.carpus.flexion,
                deviation: AnatomicalData.HORSE.constraints.carpus.deviation
            },
            hock: {
                type: 'hinge',
                flexion: AnatomicalData.HORSE.constraints.hock.flexion,
                rotation: AnatomicalData.HORSE.constraints.hock.rotation
            },
            fetlock: {  // CRITICAL: Updated with hyperextension
                type: 'hinge',
                flexion: AnatomicalData.HORSE.constraints.fetlock.flexion,
                hyperextension: AnatomicalData.HORSE.constraints.fetlock.hyperextension,
                lateral: AnatomicalData.HORSE.constraints.fetlock.lateral
            },
            pastern: {  // NEW: Fine movement control
                type: 'hinge',
                flexion: AnatomicalData.HORSE.constraints.pastern.flexion,
                lateral: AnatomicalData.HORSE.constraints.pastern.lateral
            },
            coffin: {   // NEW: Minimal hoof movement
                type: 'hinge',
                flexion: AnatomicalData.HORSE.constraints.coffin.flexion,
                lateral: AnatomicalData.HORSE.constraints.coffin.lateral
            }
        });

        // Lizard joint profiles
        this.jointProfiles.set('lizard', {
            shoulder: {
                type: 'ball-socket',
                flexion: AnatomicalData.LIZARD.constraints.shoulder.flexion,
                abduction: AnatomicalData.LIZARD.constraints.shoulder.abduction,
                rotation: AnatomicalData.LIZARD.constraints.shoulder.rotation
            },
            hip: {
                type: 'ball-socket',
                flexion: AnatomicalData.LIZARD.constraints.hip.flexion,
                abduction: AnatomicalData.LIZARD.constraints.hip.abduction,
                rotation: AnatomicalData.LIZARD.constraints.hip.rotation
            },
            elbow: {
                type: 'hinge',
                flexion: AnatomicalData.LIZARD.constraints.elbow.flexion
            },
            knee: {
                type: 'hinge',
                flexion: AnatomicalData.LIZARD.constraints.knee.flexion
            },
            spinalSegment: {
                type: 'hinge',
                lateralFlexion: AnatomicalData.LIZARD.constraints.spinalSegment.lateralFlexion,
                dorsalFlexion: AnatomicalData.LIZARD.constraints.spinalSegment.dorsalFlexion
            },
            tailSegment: {
                type: 'hinge',
                lateralFlexion: AnatomicalData.LIZARD.constraints.tailSegment.lateralFlexion,
                dorsalFlexion: AnatomicalData.LIZARD.constraints.tailSegment.dorsalFlexion
            }
        });
    }

    /**
     * Get constraints based on creature type and anatomical role
     */
    getAnatomicalConstraints(creatureType, anatomicalRole, boneConfig = {}) {
        const creatureProfile = this.jointProfiles.get(creatureType.toLowerCase());

        if (!creatureProfile || !creatureProfile[anatomicalRole]) {
            return this.getConstraints('default', boneConfig.constraints);
        }

        const joint = creatureProfile[anatomicalRole];

        if (joint.type === 'hinge') {
            return this.getHingeConstraints(joint, boneConfig);
        } else if (joint.type === 'ball-socket') {
            return this.getBallSocketConstraints(joint, boneConfig);
        }

        return this.getConstraints('default', boneConfig.constraints);
    }

    /**
     * Calculate hinge joint constraints
     */
    getHingeConstraints(joint, boneConfig) {
        let clockwise = 45, anticlockwise = 45;

        if (joint.flexion) {
            const [min, max] = joint.flexion;
            clockwise = Math.abs(max);
            anticlockwise = Math.abs(min);
        } else if (joint.lateralFlexion !== undefined) {
            clockwise = anticlockwise = joint.lateralFlexion;
        } else if (joint.range !== undefined) {
            clockwise = anticlockwise = joint.range;
        }

        // Apply any bone-specific overrides
        if (boneConfig.constraints) {
            clockwise = boneConfig.constraints.clockwise || clockwise;
            anticlockwise = boneConfig.constraints.anticlockwise || anticlockwise;
        }

        return { clockwise, anticlockwise };
    }

    /**
     * Calculate ball-and-socket joint constraints (simplified to primary flexion)
     */
    getBallSocketConstraints(joint, boneConfig) {
        let clockwise = 90, anticlockwise = 90;

        if (joint.flexion) {
            const [min, max] = joint.flexion;
            clockwise = Math.abs(max);
            anticlockwise = Math.abs(min);
        }

        // Ball-and-socket joints typically have larger range
        clockwise = Math.min(clockwise, 120);
        anticlockwise = Math.min(anticlockwise, 120);

        // Apply any bone-specific overrides
        if (boneConfig.constraints) {
            clockwise = boneConfig.constraints.clockwise || clockwise;
            anticlockwise = boneConfig.constraints.anticlockwise || anticlockwise;
        }

        return { clockwise, anticlockwise };
    }

    /**
     * Legacy method for backward compatibility
     */
    getConstraints(templateName, overrides = {}) {
        const defaults = this.constraints.get(templateName) || this.constraints.get('default');
        return { ...defaults, ...overrides };
    }

    /**
     * Get joint type information
     */
    getJointType(creatureType, anatomicalRole) {
        const creatureProfile = this.jointProfiles.get(creatureType.toLowerCase());
        if (creatureProfile && creatureProfile[anatomicalRole]) {
            return creatureProfile[anatomicalRole].type;
        }
        return 'hinge'; // Default
    }
}

/**
 * Unified Debug Manager - Consolidates all debug information into a single, clean panel
 * Replaces multiple scattered debug systems with one organized interface
 */
class DebugManager {
    constructor() {
        this.enabled = true;
        this.currentTab = 'overview'; // 'overview', 'gait', 'locomotion', 'skeleton', 'performance'
        this.showFootTargets = true;
        this.showSkeletonOverlay = false;
        this.showPerformanceMetrics = false;

        // Panel configuration
        this.panelX = 20;
        this.panelY = 20;
        this.panelWidth = 320;
        this.panelHeight = 280;
        this.tabHeight = 30;

        // Performance tracking
        this.frameCount = 0;
        this.lastFPSUpdate = 0;
        this.currentFPS = 60;

        // Colors
        this.colors = {
            background: [0, 0, 0, 200],
            border: [100, 100, 100],
            activeTab: [70, 130, 180],
            inactiveTab: [40, 40, 40],
            text: [255, 255, 255],
            accent: [100, 200, 255],
            warning: [255, 200, 100],
            error: [255, 100, 100],
            success: [100, 255, 100]
        };
    }

    // *** MAIN UPDATE CALL - Called from creature builder ***
    update(builder) {
        if (!this.enabled) return;

        this.frameCount++;
        this.updatePerformanceMetrics();
        this.collectDebugData(builder);
    }

    // *** MAIN DRAW CALL - Called from creature builder ***
    draw(builder) {
        if (!this.enabled) return;

        push();

        // Draw main debug panel
        this.drawDebugPanel(builder);

        // Draw overlay elements if enabled
        if (this.showSkeletonOverlay) {
            this.drawSkeletonOverlay(builder);
        }

        if (this.showFootTargets && builder.activeLocomotion) {
            this.drawConsolidatedFootTargets(builder);
        }

        pop();
    }

    // *** UNIFIED DEBUG PANEL ***
    drawDebugPanel(builder) {
        // Background panel
        fill(...this.colors.background);
        stroke(...this.colors.border);
        strokeWeight(1);
        rect(this.panelX, this.panelY, this.panelWidth, this.panelHeight, 8);

        // Tab headers
        this.drawTabHeaders();

        // Content area
        const contentY = this.panelY + this.tabHeight + 10;
        const contentHeight = this.panelHeight - this.tabHeight - 20;

        // Draw content based on active tab
        switch(this.currentTab) {
            case 'overview':
                this.drawOverviewTab(builder, contentY, contentHeight);
                break;
            case 'gait':
                this.drawGaitTab(builder, contentY, contentHeight);
                break;
            case 'locomotion':
                this.drawLocomotionTab(builder, contentY, contentHeight);
                break;
            case 'skeleton':
                this.drawSkeletonTab(builder, contentY, contentHeight);
                break;
            case 'performance':
                this.drawPerformanceTab(builder, contentY, contentHeight);
                break;
        }

        // Instructions footer
        this.drawInstructions();
    }

    // *** TAB HEADERS ***
    drawTabHeaders() {
        const tabs = [
            { id: 'overview', label: 'Overview' },
            { id: 'gait', label: 'Gait' },
            { id: 'locomotion', label: 'Motion' },
            { id: 'skeleton', label: 'Bones' },
            { id: 'performance', label: 'Perf' }
        ];

        const tabWidth = this.panelWidth / tabs.length;

        tabs.forEach((tab, i) => {
            const x = this.panelX + i * tabWidth;
            const y = this.panelY;
            const isActive = this.currentTab === tab.id;

            // Tab background
            const tabColor = isActive ? this.colors.activeTab : this.colors.inactiveTab;
            fill(tabColor[0], tabColor[1], tabColor[2]);
            const borderColor = this.colors.border;
            stroke(borderColor[0], borderColor[1], borderColor[2]);
            strokeWeight(1);
            rect(x, y, tabWidth, this.tabHeight);

            // Tab text
            fill(...this.colors.text);
            textAlign(CENTER, CENTER);
            textSize(11);
            textStyle(isActive ? BOLD : NORMAL);
            text(tab.label, x + tabWidth/2, y + this.tabHeight/2);
        });
    }

    // *** OVERVIEW TAB ***
    drawOverviewTab(builder, contentY, contentHeight) {
        let y = contentY + 15;
        const lineHeight = 16;

        fill(...this.colors.text);
        textAlign(LEFT);
        textSize(12);
        textStyle(BOLD);
        text('🎮 Project Status', this.panelX + 10, y);

        y += lineHeight + 5;
        textStyle(NORMAL);
        textSize(10);

        // Creature info
        fill(...this.colors.accent);
        text(`Creature: ${builder.creatureType || 'None'}`, this.panelX + 10, y);
        y += lineHeight;

        fill(...this.colors.text);
        text(`Render Mode: ${builder.renderMode}`, this.panelX + 10, y);
        y += lineHeight;

        text(`Body: (${builder.bodyPosition.x.toFixed(0)}, ${builder.bodyPosition.y.toFixed(0)})`, this.panelX + 10, y);
        y += lineHeight;

        text(`Mouse: (${builder.mouseTarget.x.toFixed(0)}, ${builder.mouseTarget.y.toFixed(0)})`, this.panelX + 10, y);
        y += lineHeight + 5;

        // Locomotion status
        textStyle(BOLD);
        text('🚶 Locomotion', this.panelX + 10, y);
        y += lineHeight;

        textStyle(NORMAL);
        if (builder.activeLocomotion) {
            const locomotion = builder.activeLocomotion;

            fill(...this.colors.success);
            text(`Pattern: ${locomotion.name || 'Active'}`, this.panelX + 10, y);
            y += lineHeight;

            fill(...this.colors.text);
            if (locomotion.gaitType) {
                text(`Gait: ${locomotion.gaitType.toUpperCase()}`, this.panelX + 10, y);
                y += lineHeight;
            }

            if (locomotion.getGroundedFeetCount) {
                text(`Grounded Feet: ${locomotion.getGroundedFeetCount()}/4`, this.panelX + 10, y);
                y += lineHeight;
            }

            if (locomotion.isInSuspension !== undefined) {
                fill(locomotion.isInSuspension ? this.colors.warning : this.colors.text);
                text(`Status: ${locomotion.isInSuspension ? 'AIRBORNE' : 'GROUNDED'}`, this.panelX + 10, y);
                y += lineHeight;
            }
        } else {
            fill(...this.colors.error);
            text('No active locomotion', this.panelX + 10, y);
        }

        // Performance summary
        y += 5;
        fill(...this.colors.text);
        textStyle(BOLD);
        text('⚡ Performance', this.panelX + 10, y);
        y += lineHeight;

        textStyle(NORMAL);
        const fpsColor = this.currentFPS > 50 ? this.colors.success : 
                        this.currentFPS > 30 ? this.colors.warning : this.colors.error;
        fill(...fpsColor);
        text(`FPS: ${this.currentFPS.toFixed(0)}`, this.panelX + 10, y);

        fill(...this.colors.text);
        text(`Chains: ${builder.chains.length}`, this.panelX + 100, y);
    }

    // *** GAIT ANALYSIS TAB ***
    drawGaitTab(builder, contentY, contentHeight) {
        let y = contentY + 15;
        const lineHeight = 14;

        if (!builder.activeLocomotion || !builder.activeLocomotion.gaitType) {
            fill(...this.colors.error);
            textAlign(CENTER);
            textSize(12);
            text('No gait data available', this.panelX + this.panelWidth/2, y + 50);
            return;
        }

        const locomotion = builder.activeLocomotion;
        const gaitParams = locomotion.gaitParams;

        // Gait header
        fill(...this.colors.text);
        textAlign(LEFT);
        textSize(14);
        textStyle(BOLD);

        const gaitColor = locomotion.gaitType === 'trot' ? this.colors.warning : this.colors.success;
        fill(...gaitColor);
        text(`${locomotion.gaitType.toUpperCase()} Gait`, this.panelX + 10, y);

        y += lineHeight + 8;
        fill(...this.colors.text);
        textStyle(NORMAL);
        textSize(10);

        // Core gait parameters
        text(`Duty Factor: ${(gaitParams.dutyFactor * 100).toFixed(0)}%`, this.panelX + 10, y);
        y += lineHeight;

        text(`Frequency: ${gaitParams.frequency.toFixed(1)}Hz`, this.panelX + 10, y);
        y += lineHeight;

        text(`Step Height: ${(gaitParams.stepHeight * 100).toFixed(0)}%`, this.panelX + 10, y);
        y += lineHeight;

        if (locomotion.groundedFeetCount !== undefined) {
            text(`Grounded: ${locomotion.groundedFeetCount}/4`, this.panelX + 10, y);
            y += lineHeight;
        }

        // Suspension status
        if (locomotion.isInSuspension !== undefined) {
            y += 5;
            textStyle(BOLD);
            fill(locomotion.isInSuspension ? this.colors.warning : this.colors.success);
            text(locomotion.isInSuspension ? '🚀 SUSPENSION PHASE' : '⚓ GROUND CONTACT', this.panelX + 10, y);
            y += lineHeight + 5;
        }

        // Transition data
        if (locomotion.transitionData) {
            fill(...this.colors.text);
            textStyle(BOLD);
            text('🔄 Transitions', this.panelX + 10, y);
            y += lineHeight;

            textStyle(NORMAL);
            const data = locomotion.transitionData;

            text(`Froude #: ${data.froudeNumber.toFixed(3)}`, this.panelX + 10, y);
            y += lineHeight;

            text(`Velocity: ${data.velocity.toFixed(2)} m/s`, this.panelX + 10, y);
            y += lineHeight;

            text(`Distance: ${data.distanceToTarget.toFixed(0)}px`, this.panelX + 10, y);
            y += lineHeight;

            const autoColor = data.automaticEnabled ? this.colors.success : this.colors.error;
            fill(...autoColor);
            text(`Auto: ${data.automaticEnabled ? 'ON' : 'OFF'}`, this.panelX + 10, y);

            if (data.cooldownRemaining > 0) {
                fill(...this.colors.warning);
                text(`Cooldown: ${data.cooldownRemaining}`, this.panelX + 100, y);
            }
        }

        // Gait pattern visualization
        if (locomotion.gaitType === 'trot') {
            y += lineHeight + 10;
            fill(...this.colors.text);
            textStyle(BOLD);
            text('Diagonal Pairs:', this.panelX + 10, y);
            y += lineHeight;

            textStyle(NORMAL);
            textSize(9);
            fill(255, 100, 100);
            text('🔴 LF + RH (Pair 1)', this.panelX + 10, y);
            y += lineHeight - 2;

            fill(100, 100, 255);
            text('🔵 RF + LH (Pair 2)', this.panelX + 10, y);
        }
    }

    // *** LOCOMOTION TAB ***
    drawLocomotionTab(builder, contentY, contentHeight) {
        let y = contentY + 15;
        const lineHeight = 14;

        // Body dynamics
        fill(...this.colors.text);
        textAlign(LEFT);
        textSize(12);
        textStyle(BOLD);
        text('🏃 Body Dynamics', this.panelX + 10, y);

        y += lineHeight + 5;
        textStyle(NORMAL);
        textSize(10);

        text(`Position: (${builder.bodyPosition.x.toFixed(1)}, ${builder.bodyPosition.y.toFixed(1)})`, this.panelX + 10, y);
        y += lineHeight;

        text(`Heading: ${(builder.bodyHeading * 180 / Math.PI).toFixed(1)}°`, this.panelX + 10, y);
        y += lineHeight;

        const distToMouse = Math.sqrt(
            Math.pow(builder.mouseTarget.x - builder.bodyPosition.x, 2) +
            Math.pow(builder.mouseTarget.y - builder.bodyPosition.y, 2)
        );
        text(`Mouse Distance: ${distToMouse.toFixed(0)}px`, this.panelX + 10, y);
        y += lineHeight + 8;

        // Chain information
        textStyle(BOLD);
        text('🔗 Chain System', this.panelX + 10, y);
        y += lineHeight + 5;

        textStyle(NORMAL);
        text(`Total Chains: ${builder.chains.length}`, this.panelX + 10, y);
        y += lineHeight;

        // List first few chains
        builder.chains.slice(0, 6).forEach((chain, i) => {
            const config = builder.chainConfigs[i];
            if (config) {
                const roleColor = this.getChainRoleColor(config.role);
                fill(...roleColor);
                text(`${config.role}: ${chain.bones.length} bones`, this.panelX + 10, y);
                y += lineHeight - 2;
            }
        });

        if (builder.chains.length > 6) {
            fill(...this.colors.text);
            text(`... and ${builder.chains.length - 6} more`, this.panelX + 10, y);
        }
    }

    // *** SKELETON TAB ***
    drawSkeletonTab(builder, contentY, contentHeight) {
        let y = contentY + 15;
        const lineHeight = 16;

        fill(...this.colors.text);
        textAlign(LEFT);
        textSize(12);
        textStyle(BOLD);
        text('🦴 Skeleton System', this.panelX + 10, y);

        y += lineHeight + 5;
        textStyle(NORMAL);
        textSize(10);

        // Skeleton controls
        const overlayColor = this.showSkeletonOverlay ? this.colors.success : this.colors.error;
        fill(...overlayColor);
        text(`Overlay: ${this.showSkeletonOverlay ? 'ON' : 'OFF'} (Press S)`, this.panelX + 10, y);
        y += lineHeight;

        fill(...this.colors.text);
        text(`Render Mode: ${builder.renderMode}`, this.panelX + 10, y);
        y += lineHeight + 5;

        // Chain breakdown by role
        textStyle(BOLD);
        text('Chain Roles:', this.panelX + 10, y);
        y += lineHeight;

        textStyle(NORMAL);
        const roleCount = {};
        builder.chainConfigs.forEach(config => {
            if (config && config.role) {
                roleCount[config.role] = (roleCount[config.role] || 0) + 1;
            }
        });

        Object.entries(roleCount).forEach(([role, count]) => {
            const roleColor = this.getChainRoleColor(role);
            fill(...roleColor);
            text(`${role}: ${count}`, this.panelX + 10, y);
            y += lineHeight;
        });

        // Controls help
        y += 10;
        fill(...this.colors.text);
        textStyle(BOLD);
        text('🎮 Controls:', this.panelX + 10, y);
        y += lineHeight;

        textStyle(NORMAL);
        textSize(9);
        text('S - Toggle skeleton overlay', this.panelX + 10, y);
        y += lineHeight - 2;
        text('M - Muscle mode', this.panelX + 10, y);
        y += lineHeight - 2;
        text('F - Skin mode', this.panelX + 10, y);
        y += lineHeight - 2;
        text('C - Current mode', this.panelX + 10, y);
    }

    // *** PERFORMANCE TAB ***
    drawPerformanceTab(builder, contentY, contentHeight) {
        let y = contentY + 15;
        const lineHeight = 16;

        fill(...this.colors.text);
        textAlign(LEFT);
        textSize(12);
        textStyle(BOLD);
        text('⚡ Performance Metrics', this.panelX + 10, y);

        y += lineHeight + 5;
        textStyle(NORMAL);
        textSize(10);

        // FPS display
        const fpsColor = this.currentFPS > 50 ? this.colors.success : 
                        this.currentFPS > 30 ? this.colors.warning : this.colors.error;
        fill(...fpsColor);
        textStyle(BOLD);
        text(`FPS: ${this.currentFPS.toFixed(1)}`, this.panelX + 10, y);

        textStyle(NORMAL);
        fill(...this.colors.text);
        text(`Frame: ${this.frameCount}`, this.panelX + 100, y);
        y += lineHeight + 5;

        // System stats
        text(`Chains: ${builder.chains.length}`, this.panelX + 10, y);
        y += lineHeight;

        let totalBones = 0;
        builder.chains.forEach(chain => totalBones += chain.bones.length);
        text(`Total Bones: ${totalBones}`, this.panelX + 10, y);
        y += lineHeight;

        if (builder.activeLocomotion && builder.activeLocomotion.footTargets) {
            text(`Foot Targets: ${builder.activeLocomotion.footTargets.length}`, this.panelX + 10, y);
            y += lineHeight;
        }

        y += 5;
        const memUsage = performance.memory ? 
            (performance.memory.usedJSHeapSize / 1024 / 1024).toFixed(1) : 'N/A';
        text(`Memory: ${memUsage} MB`, this.panelX + 10, y);
        y += lineHeight;

        // Performance status
        y += 10;
        textStyle(BOLD);
        if (this.currentFPS > 50) {
            fill(...this.colors.success);
            text('✅ Performance: Excellent', this.panelX + 10, y);
        } else if (this.currentFPS > 30) {
            fill(...this.colors.warning);
            text('⚠️ Performance: Good', this.panelX + 10, y);
        } else {
            fill(...this.colors.error);
            text('❌ Performance: Poor', this.panelX + 10, y);
        }
    }

    // *** INSTRUCTIONS FOOTER ***
    drawInstructions() {
        const instructY = this.panelY + this.panelHeight + 10;

        fill(...this.colors.text);
        textAlign(LEFT);
        textSize(9);
        textStyle(NORMAL);
        text('D: Toggle Debug | Click tabs to switch | 1-4: Creatures | W/T: Gaits | X: Auto-switching', 
             this.panelX, instructY);
    }

    // *** CONSOLIDATED FOOT TARGETS (NO PANEL OVERLAP) ***
    drawConsolidatedFootTargets(builder) {
        if (!builder.activeLocomotion || !builder.activeLocomotion.footTargets) return;

        const footTargets = builder.activeLocomotion.footTargets;
        const footNames = ['LF', 'RF', 'LH', 'RH'];

        // Use gait-appropriate colors
        let footColors;
        if (builder.activeLocomotion.gaitType === 'trot') {
            footColors = [
                [255, 100, 100], // LF - Red (Diagonal Pair 1)
                [100, 100, 255], // RF - Blue (Diagonal Pair 2)
                [100, 100, 255], // LH - Blue (Diagonal Pair 2)  
                [255, 100, 100]  // RH - Red (Diagonal Pair 1)
            ];
        } else {
            footColors = [
                [100, 255, 100], // LF - Green
                [255, 255, 100], // RF - Yellow
                [100, 100, 255], // LH - Blue
                [255, 100, 255]  // RH - Magenta
            ];
        }

        footTargets.forEach((foot, i) => {
            if (!foot || !foot.target) return;

            push();

            const color = footColors[i] || [200, 200, 200];

            if (foot.isLifted) {
                // Swing phase
                fill(...color);
                noStroke();
                circle(foot.target.x, foot.target.y, 8);

                // Ground projection
                stroke(...color, 100);
                strokeWeight(1);
                noFill();
                circle(foot.target.x, foot.target.y + 20, 12);
            } else {
                // Stance phase
                fill(...color.map(c => c * 0.7));
                stroke(...color);
                strokeWeight(2);
                circle(foot.target.x, foot.target.y, 10);
            }

            // Foot label
            fill(0);
            textAlign(CENTER);
            textSize(8);
            textStyle(BOLD);
            text(footNames[i] || `F${i}`, foot.target.x, foot.target.y - 12);

            pop();
        });
    }

    // *** SKELETON OVERLAY ***
    drawSkeletonOverlay(builder) {
        if (!builder.chains || builder.chains.length === 0) return;

        push();

        builder.chains.forEach((chain, chainIndex) => {
            const config = builder.chainConfigs[chainIndex];
            const role = config ? config.role : 'default';
            const color = this.getChainRoleColor(role);

            // Draw bones as lines
            stroke(...color, 180);
            strokeWeight(2);

            for (let i = 0; i < chain.bones.length; i++) {
                const bone = chain.bones[i];
                const start = bone.getStartLocation();
                const end = bone.getEndLocation();

                line(start.x, start.y, end.x, end.y);
            }

            // Draw joints as circles
            fill(...color, 120);
            noStroke();

            for (let i = 0; i < chain.bones.length; i++) {
                const bone = chain.bones[i];
                const joint = bone.getStartLocation();
                circle(joint.x, joint.y, 4);

                // End joint for last bone
                if (i === chain.bones.length - 1) {
                    const endJoint = bone.getEndLocation();
                    circle(endJoint.x, endJoint.y, 4);
                }
            }
        });

        pop();
    }

    // *** HELPER METHODS ***
    updatePerformanceMetrics() {
        if (millis() - this.lastFPSUpdate > 500) { // Update every 500ms
            this.currentFPS = frameRate();
            this.lastFPSUpdate = millis();
        }
    }

    collectDebugData(builder) {
        // Future: collect and process debug data here
    }

    getChainRoleColor(role) {
        const colorMap = {
            'spine': [100, 150, 255],
            'leg': [255, 100, 100],
            'neck': [100, 255, 100],
            'tail': [255, 255, 100],
            'fin': [255, 100, 255],
            'wing': [255, 150, 100],
            'head': [255, 200, 100],
            'default': [150, 150, 150]
        };
        return colorMap[role] || colorMap['default'];
    }

    // *** KEYBOARD CONTROLS ***
    handleKeyPress(key) {
        switch(key.toLowerCase()) {
            case 'd':
                this.enabled = !this.enabled;
                return true;

            case 's':
                this.showSkeletonOverlay = !this.showSkeletonOverlay;
                return true;

            case '1':
            case '2':
            case '3':
            case '4':
            case '5':
                // Tab switching
                const tabs = ['overview', 'gait', 'locomotion', 'skeleton', 'performance'];
                const tabIndex = parseInt(key) - 1;
                if (tabIndex < tabs.length) {
                    this.currentTab = tabs[tabIndex];
                    return true;
                }
                break;
        }
        return false;
    }

    // *** MOUSE CONTROLS ***
    handleMouseClick(mouseX, mouseY) {
        if (!this.enabled) return false;

        // Check if click is on tab headers
        if (mouseX >= this.panelX && mouseX <= this.panelX + this.panelWidth &&
            mouseY >= this.panelY && mouseY <= this.panelY + this.tabHeight) {

            const tabs = ['overview', 'gait', 'locomotion', 'skeleton', 'performance'];
            const tabWidth = this.panelWidth / tabs.length;
            const clickedTab = Math.floor((mouseX - this.panelX) / tabWidth);

            if (clickedTab >= 0 && clickedTab < tabs.length) {
                this.currentTab = tabs[clickedTab];
                return true;
            }
        }

        return false;
    }
}

class GaitSystem {
    constructor() {
        this.gaits = new Map();
        this.initializeGaits();
    }

    initializeGaits() {
        this.gaits.set('walk', {
            dutyCycle: 0.6,
            phaseOffset: Math.PI,
            frequency: 1.0,
            stepHeight: 0.3
        });

        this.gaits.set('trot', {
            dutyCycle: 0.5,
            phaseOffsets: [0, Math.PI, Math.PI, 0],
            frequency: 1.5
        });

        this.gaits.set('undulate', {
            wavelength: 0.7,
            amplitude: 20,
            frequency: 1.0
        });
    }

    getGait(name) {
        return this.gaits.get(name);
    }
}

/**
 * Geometric Shape System - Artist-inspired basic forms for creature construction
 * Based on how artists approach figure drawing: skeleton first, simple shapes second, details later
 */

class GeometricShapeSystem {
    /**
     * Generate basic geometric shape profiles for bone chains
     * @param {string} shapeType - Shape primitive type
     * @param {Object} config - Shape configuration
     * @returns {Function} Width function for the shape
     */
    static createShapeProfile(shapeType, config = {}) {
        switch (shapeType) {
            case 'rectangle':
                return this.createRectangle(config);
            case 'cylinder':
                return this.createCylinder(config);
            case 'ellipse':
                return this.createEllipse(config);
            case 'tapered-cylinder':
                return this.createTaperedCylinder(config);
            case 'capsule':
                return this.createCapsule(config);
            case 'sphere':
                return this.createSphere(config);
            default:
                return this.createCylinder(config); // Default fallback
        }
    }

    /**
     * Rectangle - Uniform width for torso, simple limbs
     */
    static createRectangle(config) {
        const width = config.width || 20;
        const height = config.height || width;

        return (position) => {
            return {
                width: width,
                height: height,
                shape: 'rectangle'
            };
        };
    }

    /**
     * Cylinder - Rounded uniform width for neck, arms
     */
    static createCylinder(config) {
        const radius = config.radius || 10;

        return (position) => {
            return {
                width: radius * 2,
                height: radius * 2,
                shape: 'cylinder'
            };
        };
    }

    /**
     * Ellipse - Oval cross-section for muscle groups, fish body
     */
    static createEllipse(config) {
        const width = config.width || 20;
        const height = config.height || width * 0.6;

        return (position) => {
            return {
                width: width,
                height: height,
                shape: 'ellipse'
            };
        };
    }

    /**
     * Tapered Cylinder - Gradual width change for tail, legs
     */
    static createTaperedCylinder(config) {
        const startRadius = config.startRadius || 15;
        const endRadius = config.endRadius || 5;

        return (position) => {
            // Position is 0.0 to 1.0 along the bone chain
            const t = Math.max(0, Math.min(1, position));
            const radius = startRadius + (endRadius - startRadius) * t;

            return {
                width: radius * 2,
                height: radius * 2,
                shape: 'tapered-cylinder'
            };
        };
    }

    /**
     * Capsule - Rounded rectangle for limbs with joints
     */
    static createCapsule(config) {
        const width = config.width || 16;
        const height = config.height || width * 3;
        const cornerRadius = config.cornerRadius || width * 0.4;

        return (position) => {
            return {
                width: width,
                height: height,
                cornerRadius: cornerRadius,
                shape: 'capsule'
            };
        };
    }

    /**
     * Sphere - For joints (shoulders, elbows, knees)
     */
    static createSphere(config) {
        const radius = config.radius || 8;

        return (position) => {
            return {
                width: radius * 2,
                height: radius * 2,
                shape: 'sphere'
            };
        };
    }

    /**
     * Get creature-specific shape configurations
     * Artist approach: 3 main masses (head, torso, pelvis) + simple limbs
     */
    static getCreatureShapes(creatureType) {
        const shapes = {
            fish: {
                spine: { type: 'tapered-cylinder', config: { startRadius: 12, endRadius: 3 } },
                fins: { type: 'ellipse', config: { width: 8, height: 4 } }
            },

            snake: {
                spine: { type: 'tapered-cylinder', config: { startRadius: 8, endRadius: 2 } }
            },

            crane: {
                // 3 main masses approach
                head: { type: 'ellipse', config: { width: 8, height: 6 } },
                neck: { type: 'tapered-cylinder', config: { startRadius: 3, endRadius: 4 } },
                torso: { type: 'ellipse', config: { width: 18, height: 12 } },
                legs: { type: 'tapered-cylinder', config: { startRadius: 4, endRadius: 2 } },
                wings: { type: 'ellipse', config: { width: 15, height: 6 } }
            },

            horse: {
                // 3 main masses: head, torso, pelvis
                head: { type: 'ellipse', config: { width: 12, height: 8 } },
                neck: { type: 'tapered-cylinder', config: { startRadius: 6, endRadius: 8 } },
                torso: { type: 'ellipse', config: { width: 25, height: 18 } }, // Main mass
                pelvis: { type: 'ellipse', config: { width: 20, height: 15 } }, // Main mass
                legs: { type: 'tapered-cylinder', config: { startRadius: 5, endRadius: 3 } },
                tail: { type: 'tapered-cylinder', config: { startRadius: 4, endRadius: 1 } }
            },

            lizard: {
                // Sprawling body structure
                head: { type: 'ellipse', config: { width: 8, height: 6 } },
                neck: { type: 'cylinder', config: { radius: 3 } },
                torso: { type: 'ellipse', config: { width: 16, height: 10 } },
                legs: { type: 'tapered-cylinder', config: { startRadius: 3, endRadius: 2 } },
                tail: { type: 'tapered-cylinder', config: { startRadius: 5, endRadius: 1 } }
            }
        };

        return shapes[creatureType] || shapes.fish; // Default fallback
    }

    /**
     * Apply geometric shape to bone chain - replaces complex anatomical profiles
     */
    static applyShapeToChain(chain, shapeConfig) {
        if (!chain || !chain.bones) return;

        const shapeProfile = this.createShapeProfile(shapeConfig.type, shapeConfig.config);
        const totalLength = chain.bones.length;

        chain.bones.forEach((bone, index) => {
            const position = totalLength > 1 ? index / (totalLength - 1) : 0;
            const shapeData = shapeProfile(position);

            // Store shape data on bone for rendering
            bone.shapeData = shapeData;
        });
    }
}

// Export for use in other systems
if (typeof module !== 'undefined' && module.exports) {
    module.exports = GeometricShapeSystem;
} else if (typeof window !== 'undefined') {
    window.GeometricShapeSystem = GeometricShapeSystem;
}

class OctopusTemplateSystem {
    constructor(builder) {
        this.builder = builder;
        this.boneTemplateSystem = new BoneTemplateSystem();
    }

    createMantle(config) {
        const mantleBones = this.boneTemplateSystem.generateBones('serpentine-spine', config.length, {
            segments: config.segments,
            flexibility: 'very-high'
        });
        return this.builder.addChain(this.builder.createChainConfig({
            role: 'mantle',
            type: 'spine',
            attachment: 'free',
            targetMode: 'calculated',
            color: [0, 0, 255], // Blue for octopus mantle
            bones: mantleBones,
            locomotionRole: 'primary',
            constraintTemplate: 'vertebra',
            shapeProfile: 'torso',
            scale: 1.0
        }));
    }

    createArm(config) {
        const armBones = this.boneTemplateSystem.generateBones('serpentine-spine', config.length, {
            segments: config.segments,
            flexibility: 'very-high'
        });
        return this.builder.addChain(this.builder.createChainConfig({
            role: config.role || 'arm',
            type: 'arm',
            attachment: 'parent',
            targetMode: 'calculated',
            parentRole: 'mantle',
            attachmentPoint: 'bone-index',
            attachmentIndex: (typeof config.attachmentIndex === 'number') ? config.attachmentIndex : Math.floor(this.builder.creatureConfig.mantleSegments / 2),
            color: [0, 255, 0], // Green for octopus arms
            bones: armBones,
            locomotionRole: 'propulsion',
            constraintTemplate: 'limb',
            shapeProfile: 'limb',
            scale: 0.8
        }));
    }
}

class PostureConstraintSystem {
    static getJointConstraints(creatureType, jointType) {
        const constraints = {
            horse: {
                shoulder: {
                    minAngle: -30,      // Limited forward swing
                    maxAngle: 60,       // Good backward swing  
                    abductionMax: 25,   // Limited lateral movement
                    vertical: true      // Primarily vertical plane
                },
                hip: {
                    minAngle: -45,      // Powerful backward extension
                    maxAngle: 30,       // Limited forward swing
                    abductionMax: 20,   // Minimal lateral
                    vertical: true
                }
            },
            lizard: {
                shoulder: {
                    minAngle: -60,      // Wide range
                    maxAngle: 60,       
                    abductionMax: 90,   // Very wide lateral movement
                    vertical: false     // Horizontal plane movement
                },
                hip: {
                    minAngle: -60,      
                    maxAngle: 60,
                    abductionMax: 85,   // Wide lateral movement
                    vertical: false
                }
            }
        };

        return constraints[creatureType]?.[jointType] || {};
    }
}

/**
 * Quadruped Template System
 * Templating system to easily create different quadrupeds by changing proportions
 * Based on the improved horse implementation
 */

class QuadrupedTemplateSystem {
    constructor() {
