        this.initializeTemplates();
    }

    initializeTemplates() {
        // Base erect quadruped template (horse-like)
        this.templates.set('erect-quadruped', {
            posture: 'erect',
            legStyle: 'unguligrade',  // Walks on hooves/toes
            locomotion: 'quadruped-walk',

            // Basic anatomy structure
            anatomy: {
                legs: {
                    segments: 5,
                    front: {
                        scapula: 0.6,    // Hidden in body
                        humerus: 0.5,    // Upper arm
                        radius: 0.6,     // Forearm (main visible upper)
                        cannon: 0.26,    // Lower leg (main visible lower)
                        hoof: 0.05       // Ground contact
                    },
                    hind: {
                        femur: 0.6,      // Thigh (hidden in body)
                        tibia: 0.6,      // Lower leg (main visible)
                        cannon: 0.26,    // Cannon bone
                        hoof: 0.05       // Ground contact
                    }
                },
                spine: {
                    segments: 8,
                    flexibility: 'low'
                },
                neck: {
                    segments: 6,
                    flexibility: 'medium'
                }
            },

            // Joint constraint templates
            constraints: {
                shoulder: { flexion: [-25, 55], abduction: [-8, 12], rotation: [-5, 5] },
                hip: { flexion: [-15, 65], abduction: [-8, 18], rotation: [-10, 10] },
                elbow: { flexion: [0, 160] },
                stifle: { flexion: [0, 155] },
                carpus: { flexion: [-10, 75], deviation: [-5, 5] },
                hock: { flexion: [-20, 85], rotation: [-3, 3] },
                fetlock: { flexion: [-25, 65], hyperextension: 25, lateral: [-3, 3] },
                pastern: { flexion: [-15, 45], lateral: [-3, 3] },
                coffin: { flexion: [-8, 25], lateral: [-2, 2] }
            },

            // Body proportions
            proportions: {
                legToBody: 1.05,
                neckToBody: 0.75,
                bodyWidth: 0.95,
                legWidth: 0.22
            },

            // Locomotion parameters
            locomotion: {
                walk: { frequency: 0.8, dutyCycle: 0.78, phaseShift: 0.25 },
                trot: { frequency: 1.4, dutyCycle: 0.52, phaseShift: 0.5 },
                canter: { frequency: 1.8, dutyCycle: 0.35, phaseShift: 0.33 },
                gallop: { frequency: 2.5, dutyCycle: 0.25, phaseShift: 0.15 }
            }
        });

        // Sprawling quadruped template (lizard-like)
        this.templates.set('sprawling-quadruped', {
            posture: 'sprawling',
            legStyle: 'digitigrade',  // Walks on toes
            locomotion: 'sprawling-walk',

            anatomy: {
                legs: {
                    segments: 4,     // Simpler leg structure
                    front: {
                        humerus: 0.35,    // Short, splayed
                        radius: 0.35,     // Short forearm
                        carpus: 0.15,     // Wrist
                        digits: 0.15      // Toes/claws
                    },
                    hind: {
                        femur: 0.35,      // Short thigh
                        tibia: 0.35,      // Short lower leg
                        tarsus: 0.15,     // Ankle
                        digits: 0.15      // Toes/claws
                    }
                },
                spine: {
                    segments: 15,         // Highly flexible
                    flexibility: 'very-high'
                },
                tail: {
                    segments: 12,
                    flexibility: 'very-high'
                }
            },

            constraints: {
                shoulder: { flexion: [-45, 90], abduction: [-60, 60], rotation: [-30, 30] },
                hip: { flexion: [-30, 80], abduction: [-70, 70], rotation: [-45, 45] },
                elbow: { flexion: [0, 120] },
                knee: { flexion: [0, 110] },
                spinalSegment: { lateralFlexion: 15, dorsalFlexion: 5 }
            },

            proportions: {
                legToBody: 0.4,      // Short legs
                tailToBody: 1.2,     // Long tail
                bodyWidth: 0.6,      // Wide, low body
                sprawlAngle: 45      // Leg splay angle
            }
        });
    }

    /**
     * Create a new quadruped by modifying an existing template
     */
    createQuadruped(baseTemplate, modifications = {}) {
        const template = this.deepClone(this.templates.get(baseTemplate));
        if (!template) {
            throw new Error(`Template ${baseTemplate} not found`);
        }

        // Apply modifications recursively
        this.applyModifications(template, modifications);

        return template;
    }

    /**
     * Apply modifications to a template recursively
     */
    applyModifications(target, modifications) {
        for (const [key, value] of Object.entries(modifications)) {
            if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
                if (!target[key]) target[key] = {};
                this.applyModifications(target[key], value);
            } else {
                target[key] = value;
            }
        }
    }

    /**
     * Deep clone an object
     */
    deepClone(obj) {
        if (obj === null || typeof obj !== 'object') return obj;
        if (obj instanceof Array) return obj.map(item => this.deepClone(item));

        const cloned = {};
        for (const [key, value] of Object.entries(obj)) {
            cloned[key] = this.deepClone(value);
        }
        return cloned;
    }

    /**
     * Generate bone template for quadruped leg
     */
    generateQuadrupedLeg(template, legType, length, config = {}) {
        const legData = template.anatomy.legs[legType];
        const constraints = template.constraints;
        const bones = [];

        // Generate bones based on leg structure
        const boneNames = Object.keys(legData);

        for (let i = 0; i < boneNames.length; i++) {
            const boneName = boneNames[i];
            const proportion = legData[boneName];

            // Determine anatomical role and constraints
            const anatomicalRole = this.mapBoneToRole(boneName, i, boneNames.length);
            const jointConstraints = constraints[anatomicalRole] || { flexion: [0, 45] };

            // Calculate direction based on posture
            const direction = this.calculateBoneDirection(
                template.posture, 
                boneName, 
                i, 
                config.side
            );

            bones.push({
                length: length * proportion,
                direction: direction,
                constraints: {
                    clockwise: Math.abs(jointConstraints.flexion[1]),
                    anticlockwise: Math.abs(jointConstraints.flexion[0])
                },
                jointType: this.getJointType(anatomicalRole),
                anatomicalRole: anatomicalRole,
                groundContact: i === boneNames.length - 1  // Last bone touches ground
            });
        }

        return bones;
    }

    /**
     * Map bone name to anatomical role
     */
    mapBoneToRole(boneName, index, totalBones) {
        const roleMap = {
            'scapula': 'shoulder',
            'humerus': 'elbow', 
            'radius': 'carpus',
            'cannon': 'fetlock',
            'hoof': 'coffin',
            'femur': 'hip',
            'tibia': 'stifle',
            'tarsus': 'hock',
            'digits': 'digits'
        };

        return roleMap[boneName] || 'generic';
    }

    /**
     * Calculate bone direction based on posture
     */
    calculateBoneDirection(posture, boneName, boneIndex, side = 'left') {
        if (posture === 'erect') {
            // Erect posture - mostly vertical
            const angleOffsets = {
                'scapula': 0.3,
                'humerus': 0.0,
                'radius': 0.0,
                'cannon': 0.0,
                'hoof': 0.2
            };
            const offset = angleOffsets[boneName] || 0;
            return new FIK.V2(offset, 1);

        } else if (posture === 'sprawling') {
            // Sprawling posture - splayed legs
            const sideMultiplier = side === 'left' ? -1 : 1;
            const sprawlFactor = 0.8 - (boneIndex * 0.2); // Less splay toward ground
            return new FIK.V2(sideMultiplier * sprawlFactor, 0.6 + (boneIndex * 0.1));
        }

        return new FIK.V2(0, 1); // Default vertical
    }

    /**
     * Get joint type for anatomical role
     */
    getJointType(role) {
        const ballSocketJoints = ['shoulder', 'hip'];
        return ballSocketJoints.includes(role) ? 'ball-socket' : 'hinge';
    }

    /**
     * Preset quadruped configurations
     */
    static get PRESETS() {
        return {
            // Existing horse (already implemented)
            HORSE: 'erect-quadruped',

            // Future quadrupeds using the same system
            DEER: {
                base: 'erect-quadruped',
                modifications: {
                    anatomy: {
                        legs: {
                            front: { scapula: 0.4, humerus: 0.3, radius: 0.7, cannon: 0.3, hoof: 0.04 },
                            hind: { femur: 0.4, tibia: 0.7, cannon: 0.3, hoof: 0.04 }
                        },
                        neck: { segments: 8, flexibility: 'high' }
                    },
                    proportions: {
                        legToBody: 1.2,  // Longer legs
                        neckToBody: 0.9  // Longer neck
                    }
                }
            },

            COW: {
                base: 'erect-quadruped', 
                modifications: {
                    anatomy: {
                        legs: {
                            front: { scapula: 0.5, humerus: 0.4, radius: 0.5, cannon: 0.2, hoof: 0.06 },
                            hind: { femur: 0.5, tibia: 0.5, cannon: 0.2, hoof: 0.06 }
                        }
                    },
                    proportions: {
                        legToBody: 0.9,   // Shorter legs
                        bodyWidth: 1.2,   // Wider body
                        legWidth: 0.3     // Thicker legs
                    }
                }
            },

            DOG: {
                base: 'erect-quadruped',
                modifications: {
                    anatomy: {
                        legs: {
                            segments: 4,  // Simpler leg structure
                            front: { humerus: 0.4, radius: 0.4, carpus: 0.15, paw: 0.05 },
                            hind: { femur: 0.4, tibia: 0.4, tarsus: 0.15, paw: 0.05 }
                        },
                        spine: { flexibility: 'medium' }
                    },
                    proportions: {
                        legToBody: 0.8,
                        neckToBody: 0.4
                    }
                }
            },

            LIZARD: 'sprawling-quadruped'
        };
    }
}

/**
 * Shape Generation System - Handles outline generation from bone chains
 * Placeholder for shape generation functionality used by creature rendering
 */

// Shape generation utilities
function generateOutlineFromChain(chain, widthProfile) {
    // Basic outline generation from chain bones
    if (!chain || !chain.bones || chain.bones.length < 2) {
        return { leftSide: [], rightSide: [] };
    }

    const leftSide = [];
    const rightSide = [];
    const defaultWidth = widthProfile || 10;

    for (let i = 0; i < chain.bones.length; i++) {
        const bone = chain.bones[i];
        const start = bone.getStartLocation();
        const end = bone.getEndLocation();

        // Calculate perpendicular direction for width
        const dir = new FIK.V2(end.x - start.x, end.y - start.y);
        const perp = new FIK.V2(-dir.y, dir.x).normalised();

        const width = Array.isArray(widthProfile) && i < widthProfile.length ? 
                     widthProfile[i] : defaultWidth;

        // Add points to left and right sides
        leftSide.push({
            x: start.x + perp.x * width,
            y: start.y + perp.y * width
        });

        rightSide.unshift({
            x: start.x - perp.x * width,
            y: start.y - perp.y * width
        });

        // Add end point for last bone
        if (i === chain.bones.length - 1) {
            leftSide.push({
                x: end.x + perp.x * width,
                y: end.y + perp.y * width
            });

            rightSide.unshift({
                x: end.x - perp.x * width,
                y: end.y - perp.y * width
            });
        }
    }

    return { leftSide, rightSide };
}

// Export for other systems to use
if (typeof module !== 'undefined' && module.exports) {
    module.exports = { generateOutlineFromChain };
}

/**
 * Shape Profile System for Madhuban Creatures
 * Generates anatomically accurate width profiles for different body parts
 * Uses anatomical-data.js for research-based proportions
 */

class ShapeProfileSystem {
    constructor() {
        this.baseWidth = 30; // Base width multiplier for scaling
        this.profileCache = new Map();
    }

    /**
     * Get width profile function for a specific creature and body part
     * @param {string} creatureType - 'fish', 'crane', 'horse', 'lizard'
     * @param {string} bodyPart - 'torso', 'neck', 'leg', 'tail', 'spine'
     * @param {object} config - Additional configuration (scale, role, etc.)
     * @returns {function} Width function that takes t (0-1) and returns width
     */
    getWidthProfile(creatureType, bodyPart, config = {}) {
        const cacheKey = `${creatureType}-${bodyPart}-${JSON.stringify(config)}`;

        if (this.profileCache.has(cacheKey)) {
            return this.profileCache.get(cacheKey);
        }

        const widthFunc = this.createWidthFunction(creatureType, bodyPart, config);
        this.profileCache.set(cacheKey, widthFunc);
        return widthFunc;
    }

    /**
     * Create width function based on creature anatomy
     */
    createWidthFunction(creatureType, bodyPart, config) {
        const anatomyData = AnatomicalData[creatureType.toUpperCase()];
        if (!anatomyData) {
            return this.getGenericProfile();
        }

        const scale = config.scale || 1.0;
        const role = config.role || bodyPart;

        switch (creatureType.toLowerCase()) {
            case 'fish':
                return this.createFishProfile(anatomyData, bodyPart, scale);
            case 'crane':
                return this.createCraneProfile(anatomyData, bodyPart, scale, role);
            case 'horse':
                return this.createHorseProfile(anatomyData, bodyPart, scale, role);
            case 'lizard':
                return this.createLizardProfile(anatomyData, bodyPart, scale, role);
            default:
                return this.getGenericProfile();
        }
    }

    /**
     * Fish Profile - Streamlined torpedo shape
     */
    createFishProfile(data, bodyPart, scale) {
        const baseWidth = this.baseWidth * scale;

        if (bodyPart === 'spine' || bodyPart === 'body') {
            // Main fish body - torpedo shape
            return (t) => {
                const width = AnatomicalData.getWidthAtPosition('fish', 'widthProfile', t);
                return baseWidth * width;
            };
        } else if (bodyPart === 'fin') {
            // Fins - tapered from base to tip
            return (t) => {
                return baseWidth * 0.3 * (1 - t * 0.8); // Tapers to 20% at tip
            };
        }

        return (t) => baseWidth * 0.5; // Default fin width
    }

    /**
     * Crane Profile - Thin neck, compact body, slender legs
     */
    createCraneProfile(data, bodyPart, scale, role) {
        const baseWidth = this.baseWidth * scale;

        switch (bodyPart) {
            case 'torso':
            case 'body':
                // Compact body profile
                return (t) => {
                    const width = AnatomicalData.getWidthAtPosition('crane', 'torso', t);
                    return baseWidth * width * data.proportions.torsoWidth;
                };

            case 'neck':
                // Long thin neck with slight head bulge
                return (t) => {
                    const width = AnatomicalData.getWidthAtPosition('crane', 'neck', t);
                    return baseWidth * width * 0.5; // Scale down for neck
                };

            case 'leg':
                // Slender legs, thicker at joints
                return (t) => {
                    const width = AnatomicalData.getWidthAtPosition('crane', 'leg', t);
                    // Add joint bulges at knee and ankle
                    const jointBulge = this.getJointBulge(t, [0.25, 0.75], 1.3);
                    return baseWidth * width * data.proportions.legWidth * jointBulge;
                };

            case 'tail':
                // Small tail feathers
                return (t) => {
                    return baseWidth * 0.15 * (1 - t * 0.5); // Tapered
                };

            case 'wing':
                // Wing profile
                return (t) => {
                    return baseWidth * 0.2 * (1 - t * 0.6); // Tapered wing
                };
        }

        return (t) => baseWidth * 0.3; // Default
    }

    /**
     * Horse Profile - Muscular barrel chest, thick legs
     */
    createHorseProfile(data, bodyPart, scale, role) {
        const baseWidth = this.baseWidth * scale;

        switch (bodyPart) {
            case 'torso':
            case 'body':
                // Barrel chest profile
                return (t) => {
                    const width = AnatomicalData.getWidthAtPosition('horse', 'torso', t);
                    return baseWidth * width * data.proportions.bodyWidth;
                };

            case 'neck':
                // Strong neck
                return (t) => {
                    const width = AnatomicalData.getWidthAtPosition('horse', 'neck', t);
                    return baseWidth * width * 0.7; // Substantial neck
                };

            case 'leg':
                // Muscular legs with defined joints
                return (t) => {
                    const width = AnatomicalData.getWidthAtPosition('horse', 'leg', t);
                    // Emphasize muscle definition and joints
                    const jointBulge = this.getJointBulge(t, [0.3, 0.65], 1.2);
                    const muscleBulge = this.getMuscleDefinition(t, role);
                    return width * data.proportions.legWidth * jointBulge * muscleBulge;
                };

            case 'tail':
                // Thick tail base, flowing hair
                return (t) => {
                    return baseWidth * 0.25 * (0.8 - t * 0.3); // Gradual taper
                };
        }

        return (t) => baseWidth * 0.4; // Default
    }

    /**
     * Lizard Profile - Low, elongated body, thin limbs
     */
    createLizardProfile(data, bodyPart, scale, role) {
        const baseWidth = this.baseWidth * scale;

        switch (bodyPart) {
            case 'torso':
            case 'body':
            case 'spine':
                // Low, wide body
                return (t) => {
                    const width = AnatomicalData.getWidthAtPosition('lizard', 'torso', t);
                    return baseWidth * width * data.proportions.bodyWidth;
                };

            case 'tail':
                // Long tapering tail
                return (t) => {
                    const width = AnatomicalData.getWidthAtPosition('lizard', 'tail', t);
                    return baseWidth * width * 0.8; // Scale for tail
                };

            case 'leg':
                // Thin sprawling legs
                return (t) => {
                    const width = AnatomicalData.getWidthAtPosition('lizard', 'leg', t);
                    // Minimal joint definition
                    const jointBulge = this.getJointBulge(t, [0.4, 0.8], 1.1);
                    return baseWidth * width * data.proportions.legWidth * jointBulge;
                };

            case 'neck':
                // Continuous with body
                return (t) => {
                    return baseWidth * 0.4 * (1 - t * 0.2); // Slight taper to head
                };
        }

        return (t) => baseWidth * 0.2; // Default thin
    }

    /**
     * Add joint bulges at specific positions
     */
    getJointBulge(t, jointPositions, bulgeAmount) {
        let bulge = 1.0;
        const bulgeWidth = 0.1; // Width of bulge effect

        for (const jointPos of jointPositions) {
            const distance = Math.abs(t - jointPos);
            if (distance < bulgeWidth) {
                const bulgeIntensity = 1 - (distance / bulgeWidth);
                bulge *= 1 + (bulgeAmount - 1) * bulgeIntensity;
            }
        }

        return bulge;
    }

    /**
     * Add muscle definition based on leg role
     */
    getMuscleDefinition(t, role) {
        if (role && role.includes('front')) {
            // Front legs - more muscle in upper portion
            return 1 + 0.3 * Math.exp(-t * 3); // Exponential decay from shoulder
        } else if (role && role.includes('back')) {
            // Back legs - power muscles in middle
            return 1 + 0.4 * Math.exp(-Math.pow((t - 0.3) * 4, 2)); // Gaussian at 30%
        }
        return 1.0;
    }

    /**
     * Generic fallback profile
     */
    getGenericProfile() {
        return (t) => {
            return this.baseWidth * (0.5 + 0.5 * (1 - Math.pow(2 * t - 1, 2)));
        };
    }

    /**
     * Get profile for specific chain configuration
     */
    getProfileForChain(creatureType, chainConfig) {
        const bodyPart = this.mapChainToBodyPart(chainConfig);
        const scale = chainConfig.scale || 1.0;

        return this.getWidthProfile(creatureType, bodyPart, {
            scale: scale,
            role: chainConfig.role,
            type: chainConfig.type
        });
    }

    /**
     * Map chain configuration to body part type
     */
    mapChainToBodyPart(chainConfig) {
        const role = chainConfig.role.toLowerCase();
        const type = chainConfig.type.toLowerCase();

        // Direct mapping from chain type
        if (['torso', 'neck', 'leg', 'tail', 'wing', 'fin'].includes(type)) {
            return type;
        }

        // Map from role
        if (role.includes('spine') || role.includes('body')) return 'torso';
        if (role.includes('neck')) return 'neck';
        if (role.includes('leg')) return 'leg';
        if (role.includes('tail')) return 'tail';
        if (role.includes('wing')) return 'wing';
        if (role.includes('fin')) return 'fin';

        // Default based on type
        return type || 'torso';
    }

    /**
     * Utility: Create width function from profile points
     */
    static createInterpolatedProfile(profilePoints, baseWidth = 30) {
        return (t) => {
            // Find the two points to interpolate between
            for (let i = 0; i < profilePoints.length - 1; i++) {
                if (t >= profilePoints[i].t && t <= profilePoints[i + 1].t) {
                    const ratio = (t - profilePoints[i].t) / (profilePoints[i + 1].t - profilePoints[i].t);
                    const width = profilePoints[i].width + ratio * (profilePoints[i + 1].width - profilePoints[i].width);
                    return baseWidth * width;
                }
            }

            // Handle edge cases
            if (t <= profilePoints[0].t) return baseWidth * profilePoints[0].width;
            return baseWidth * profilePoints[profilePoints.length - 1].width;
        };
    }
}

/**
 * Shape Profile System - Geometric Primitives Approach
 * Artist approach: skeleton first, simple shapes second, details later
 * Uses basic geometric shapes instead of complex anatomical profiles
 */

class ShapeProfileSystem {
    constructor() {
        this.shapeCache = new Map();
    }

    /**
     * Get geometric shape profile for creature body parts
     * @param {string} creatureType - 'fish', 'crane', 'horse', 'lizard'
     * @param {string} bodyPart - 'torso', 'neck', 'leg', 'tail', 'spine'
     * @param {object} config - Additional configuration
     * @returns {function} Width function using geometric shapes
     */
    getWidthProfile(creatureType, bodyPart, config = {}) {
        const cacheKey = `${creatureType}-${bodyPart}-${JSON.stringify(config)}`;

        if (this.shapeCache.has(cacheKey)) {
            return this.shapeCache.get(cacheKey);
        }

        const baseShapeFunc = this.createGeometricShape(creatureType, bodyPart, config);
        const scale = config.scale || 1.0;

        // Apply scaling to the shape function
        const scaledShapeFunc = (t) => {
            return baseShapeFunc(t) * scale;
        };

        this.shapeCache.set(cacheKey, scaledShapeFunc);
        return scaledShapeFunc;
    }

    /**
     * Create geometric shape function - artist's basic forms approach
     */
    createGeometricShape(creatureType, bodyPart, config) {
        const shapes = this.getCreatureShapes(creatureType);
        const partShape = shapes[bodyPart] || shapes.default;

        return this.createShapeFunction(partShape.type, partShape.config);
    }

    /**
     * Get basic shape configurations for each creature
     * Based on artist's "3 main masses" principle: head, torso, pelvis
     */
    getCreatureShapes(creatureType) {
        const shapeConfigs = {
            fish: {
                spine: { type: 'tapered-cylinder', config: { startWidth: 24, endWidth: 6 } },
                default: { type: 'cylinder', config: { width: 12 } }
            },

            snake: {
                spine: { type: 'tapered-cylinder', config: { startWidth: 16, endWidth: 4 } },
                default: { type: 'cylinder', config: { width: 8 } }
            },

            crane: {
                // Artist's 3 main masses
                head: { type: 'ellipse', config: { width: 12, height: 10 } },
                neck: { type: 'tapered-cylinder', config: { startWidth: 6, endWidth: 8 } },
                torso: { type: 'ellipse', config: { width: 32, height: 24 } }, // Main mass 1
                leg: { type: 'tapered-cylinder', config: { startWidth: 8, endWidth: 4 } },
                wing: { type: 'ellipse', config: { width: 20, height: 8 } },
                default: { type: 'cylinder', config: { width: 10 } }
            },

            horse: {
                // Artist's 3 main masses approach
                head: { type: 'ellipse', config: { width: 20, height: 16 } }, // Main mass 1
                neck: { type: 'tapered-cylinder', config: { startWidth: 12, endWidth: 16 } },
                torso: { type: 'ellipse', config: { width: 40, height: 10 } }, // Main mass 2 (largest)
                pelvis: { type: 'ellipse', config: { width: 32, height: 26 } }, // Main mass 3
                leg: { type: 'tapered-cylinder', config: { startWidth: 10, endWidth: 6 } },
                tail: { type: 'tapered-cylinder', config: { startWidth: 8, endWidth: 2 } },
                default: { type: 'cylinder', config: { width: 12 } }
            },

            lizard: {
                // Sprawling body structure
                head: { type: 'ellipse', config: { width: 14, height: 10 } },
                neck: { type: 'cylinder', config: { width: 6 } },
                torso: { type: 'ellipse', config: { width: 28, height: 18 } },
                leg: { type: 'tapered-cylinder', config: { startWidth: 6, endWidth: 4 } },
                tail: { type: 'tapered-cylinder', config: { startWidth: 10, endWidth: 2 } },
                default: { type: 'cylinder', config: { width: 8 } }
            }
        };

        return shapeConfigs[creatureType] || shapeConfigs.fish;
    }

    /**
     * Create shape function based on geometric primitive
     */
    createShapeFunction(shapeType, config) {
        switch (shapeType) {
            case 'rectangle':
                return this.createRectangleProfile(config);
            case 'cylinder':
                return this.createCylinderProfile(config);
            case 'ellipse':
                return this.createEllipseProfile(config);
            case 'tapered-cylinder':
                return this.createTaperedCylinderProfile(config);
            case 'capsule':
                return this.createCapsuleProfile(config);
            default:
                return this.createCylinderProfile(config);
        }
    }

    /**
     * Rectangle - Uniform width, good for torso, simple limbs
     */
    createRectangleProfile(config) {
        const width = config.width || 20;

        return (t) => {
            return width; // Constant width
        };
    }

    /**
     * Cylinder - Rounded uniform width, good for neck, arms
     */
    createCylinderProfile(config) {
        const width = config.width || 16;

        return (t) => {
            return width; // Constant width with rounded ends
        };
    }

    /**
     * Ellipse - Oval cross-section, good for muscle groups, fish body
     */
    createEllipseProfile(config) {
        const width = config.width || 24;
        const height = config.height || width * 0.7;

        return (t) => {
            // Ellipse width varies along length (simulates oval cross-section)
            const centerT = 0.5;
            const distFromCenter = Math.abs(t - centerT) * 2; // 0 at center, 1 at ends
            const widthFactor = Math.sqrt(1 - distFromCenter * distFromCenter); // Ellipse equation
            return width * widthFactor;
        };
    }

    /**
     * Tapered Cylinder - Gradual width change, perfect for tail, legs
     */
    createTaperedCylinderProfile(config) {
        const startWidth = config.startWidth || 20;
        const endWidth = config.endWidth || 8;

        return (t) => {
            // Linear taper from start to end
            return startWidth + (endWidth - startWidth) * t;
        };
    }

    /**
     * Capsule - Rounded rectangle, good for limbs with joints
     */
    createCapsuleProfile(config) {
        const width = config.width || 18;
        const tapering = config.tapering || 0.1; // Slight taper at ends

        return (t) => {
            // Slight taper at ends to create capsule effect
            const endFactor = Math.min(t, 1 - t) * 2; // 0 at ends, 1 in middle
            const taperAmount = 1 - tapering + (tapering * endFactor);
            return width * taperAmount;
        };
    }

    /**
     * Generic fallback profile
     */
    getGenericProfile() {
        return (t) => 12; // Simple constant width
    }

    /**
     * Get width profile for specific chain configuration - maintains compatibility
     */
    getProfileForChain(creatureType, chainConfig) {
        const bodyPart = this.mapChainToBodyPart(chainConfig);
        const scale = chainConfig.scale || 1.0;

        return this.getWidthProfile(creatureType, bodyPart, {
            scale: scale,
            role: chainConfig.role,
            type: chainConfig.type
        });
    }

    /**
     * Map chain configuration to body part type
     */
    mapChainToBodyPart(chainConfig) {
        const role = chainConfig.role.toLowerCase();
        const type = chainConfig.type.toLowerCase();

        // Direct mapping from chain type
        if (['torso', 'neck', 'leg', 'tail', 'wing', 'fin'].includes(type)) {
            return type;
        }

        // Map from role
        if (role.includes('spine') || role.includes('body')) return 'torso';
        if (role.includes('neck')) return 'neck';
        if (role.includes('leg')) return 'leg';
        if (role.includes('tail')) return 'tail';
        if (role.includes('wing')) return 'wing';
        if (role.includes('fin')) return 'fin';

        // Default based on type
        return type || 'torso';
    }

    /**
     * Apply width profile to bone chain
     */
    applyWidthToChain(chain, widthProfile, config = {}) {
        if (!chain || !chain.bones || chain.bones.length === 0) return;

        const bones = chain.bones;
        const totalBones = bones.length;

        bones.forEach((bone, index) => {
            const t = totalBones > 1 ? index / (totalBones - 1) : 0.5;
            const width = widthProfile(t);

            // Store width and shape info on bone
            bone.renderWidth = width;
            bone.shapeProfile = {
                width: width,
                position: t,
                config: config
            };
        });
    }
}

// Export for use in creature builder
if (typeof module !== 'undefined' && module.exports) {
    module.exports = ShapeProfileSystem;
} else if (typeof window !== 'undefined') {
    window.ShapeProfileSystem = ShapeProfileSystem;
}

/**
 * Validation tests for ConfigManager (PRP1-7)
 * 
 * Tests JSON import/export functionality, backward compatibility,
 * and integration with ModularCreatureBuilder.
 */

class ConfigManagerValidator {
    constructor() {
        this.results = [];
        this.passed = 0;
        this.failed = 0;

        console.log('🔍 Starting ConfigManager Validation Tests');
        console.log('============================================');
    }

    test(name, condition, details = '') {
        const result = {
            name: name,
            passed: condition,
            details: details,
            timestamp: Date.now()
        };

        this.results.push(result);

        if (condition) {
            this.passed++;
            console.log(`✅ ${name}`, details ? `- ${details}` : '');
        } else {
            this.failed++;
            console.error(`❌ ${name}`, details ? `- ${details}` : '');
        }

        return condition;
    }

    async runAllTests() {
        console.log('\n📋 CONFIGMANAGER FOUNDATION TESTS');
        console.log('===================================');

        // Test 1: ConfigManager exists and is initialized
        this.test(
            'ConfigManager class exists',
            typeof ConfigManager !== 'undefined',
            'ConfigManager class should be loaded'
        );

        this.test(
            'Editor has ConfigManager instance',
            editor && editor.configManager && editor.configManager instanceof ConfigManager,
            'EditorMode should initialize ConfigManager'
        );

        this.test(
            'ConfigManager has builder reference',
            editor.configManager.builder === builder,
            'ConfigManager should reference ModularCreatureBuilder'
        );

        console.log('\n📤 EXPORT FUNCTIONALITY TESTS');
        console.log('==============================');

        // Test 2: Export functionality
        await this.testExportFunctionality();

        console.log('\n📥 IMPORT FUNCTIONALITY TESTS');
        console.log('==============================');

        // Test 3: Import functionality
        await this.testImportFunctionality();

        console.log('\n🔄 ROUND-TRIP TESTS');
        console.log('====================');

        // Test 4: Round-trip export/import
        await this.testRoundTripFunctionality();

        console.log('\n🎯 UI INTEGRATION TESTS');
        console.log('========================');

        // Test 5: UI integration
        this.testUIIntegration();

        // Summary
        console.log('\n📊 TEST SUMMARY');
        console.log('================');
        console.log(`✅ Passed: ${this.passed}`);
        console.log(`❌ Failed: ${this.failed}`);
        console.log(`📈 Success Rate: ${((this.passed / (this.passed + this.failed)) * 100).toFixed(1)}%`);

        return this.failed === 0;
    }

    async testExportFunctionality() {
        try {
            // Ensure we have a creature to export
            builder.buildHorse();

            // Test basic export
            const config = editor.configManager.exportConfig('complete');

            this.test(
                'Export config returns object',
                config && typeof config === 'object',
                'exportConfig should return configuration object'
            );

            this.test(
                'Export config has required fields',
                config.version && config.creatureType && config.chainConfigs,
                'Configuration should have version, creatureType, and chainConfigs'
            );

            this.test(
                'Export config has correct creature type',
                config.creatureType === 'horse',
                'Should export current creature type'
            );

            this.test(
                'Export config has chain configurations',
                Array.isArray(config.chainConfigs) && config.chainConfigs.length > 0,
                'Should export chain configurations'
            );

            // Test different export formats
            const skeletonConfig = editor.configManager.exportConfig('skeleton');
            this.test(
                'Skeleton export format works',
                skeletonConfig && skeletonConfig.format === 'skeleton',
                'Skeleton format should export without locomotion data'
            );

            const baseConfig = editor.configManager.exportConfig('base');
            this.test(
                'Base export format works',
                baseConfig && baseConfig.format === 'base' && !baseConfig.editorMetadata,
                'Base format should export without editor metadata'
            );

        } catch (error) {
            this.test(
                'Export functionality basic test',
                false,
                `Export failed: ${error.message}`
            );
        }
    }

    async testImportFunctionality() {
        try {
            // Create a test configuration
            const originalType = builder.creatureType;
            const testConfig = {
                version: '1.0',
                exportDate: new Date().toISOString(),
                format: 'complete',
                creatureType: 'fish',
                creatureConfig: {
                    bodyLength: 200,
                    bodySegments: 8,
                    segmentLength: 25,
                    finSize: 30
                },
                chainConfigs: [
                    {
                        role: 'spine',
                        type: 'spine',
                        attachment: 'free',
                        targetMode: 'mouse',
                        color: [100, 150, 255],
                        bones: [
                            { length: 25, direction: { x: 1, y: 0 }, constraints: { clockwise: 30, anticlockwise: 30 } },
                            { length: 25, direction: { x: 1, y: 0 }, constraints: { clockwise: 30, anticlockwise: 30 } }
                        ]
                    }
                ],
                locomotion: null,
                editorMetadata: {
                    lastModified: new Date().toISOString(),
                    editorVersion: '1.0'
                }
            };

            // Test import
            const success = editor.configManager.importConfig(testConfig);

            this.test(
                'Import config returns success',
                success === true,
                'importConfig should return true on success'
            );

            this.test(
                'Import changes creature type',
                builder.creatureType === 'fish',
                'Should change creature type to imported value'
            );

            this.test(
                'Import creates chains',
                builder.chains.length > 0,
                'Should create chains from imported configuration'
            );

            // Restore original creature
            if (originalType === 'horse') {
                builder.buildHorse();
            }

        } catch (error) {
            this.test(
                'Import functionality basic test',
                false,
                `Import failed: ${error.message}`
            );
        }
    }

    async testRoundTripFunctionality() {
        try {
            // Start with a known creature
            builder.buildHorse();
            const originalChainCount = builder.chains.length;
            const originalType = builder.creatureType;

            // Export configuration
            const exportedConfig = editor.configManager.exportConfig('complete');

            // Clear and import
            builder.clearCreature();
            const importSuccess = editor.configManager.importConfig(exportedConfig);

            this.test(
                'Round-trip import succeeds',
                importSuccess === true,
                'Should successfully import exported configuration'
            );

            this.test(
                'Round-trip preserves creature type',
                builder.creatureType === originalType,
                'Creature type should be preserved through export/import'
            );

            this.test(
                'Round-trip preserves chain count',
                builder.chains.length === originalChainCount,
                'Number of chains should be preserved'
            );

            this.test(
                'Round-trip preserves chain configurations',
                builder.chainConfigs.length === originalChainCount,
                'Chain configurations should be preserved'
            );

        } catch (error) {
            this.test(
                'Round-trip functionality test',
                false,
                `Round-trip failed: ${error.message}`
            );
        }
    }

    testUIIntegration() {
        // Test UI elements exist
        this.test(
            'Save button exists in UI',
            document.querySelector('button[onclick="editor.saveCreatureConfig();"]') !== null,
            'Save button should be present in editor UI'
        );

        this.test(
            'Load button exists in UI',
            document.querySelector('button[onclick="editor.loadCreatureConfig();"]') !== null,
            'Load button should be present in editor UI'
        );

        this.test(
            'Export button exists in UI',
            document.querySelector('button[onclick="editor.exportCreatureConfig();"]') !== null,
            'Export button should be present in editor UI'
        );

        this.test(
            'Format selector exists',
            document.getElementById('editor-export-format') !== null,
            'Export format selector should be present'
        );

        this.test(
            'File input exists',
            document.getElementById('editor-config-upload') !== null,
            'File upload input should be present'
        );

        // Test UI methods exist
        this.test(
            'Save method exists on editor',
            typeof editor.saveCreatureConfig === 'function',
            'saveCreatureConfig method should exist'
        );

        this.test(
            'Load method exists on editor',
            typeof editor.loadCreatureConfig === 'function',
            'loadCreatureConfig method should exist'
        );

        this.test(
            'Export method exists on editor',
            typeof editor.exportCreatureConfig === 'function',
            'exportCreatureConfig method should exist'
        );
    }

    // Manual test helper for file operations
    testFileOperations() {
        console.log('\n📁 MANUAL FILE OPERATION TESTS');
        console.log('===============================');
        console.log('Run these tests manually:');
        console.log('1. Press E to enter editor mode');
        console.log('2. Modify a creature (select chains, move bones, etc.)');
        console.log('3. Click "Save" button - should download JSON file');
        console.log('4. Click "Load" button - should open file dialog');
        console.log('5. Select the downloaded file - should load configuration');
        console.log('6. Click "Export JSON" - should copy to clipboard');
        console.log('7. Check console for exported JSON');
    }
}

